(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["tr"] = {"ui":{"lead":"İnsanlar oyunları yalnızca oynamadı, resmini de yaptı. 3300 yıllık resim ve heykeli büyütüp ayrıntılarına bakın.","details":"Ayrıntılar","links":"Oyuna bak ya da oyna","record":"Eser hakkında","game":"Oyun","exhibit":"Koleksiyon","room":"Salon","room_chance":"Şans","hint":"Büyütmek için kıstırın ya da tekerleği kullanın · taşımak için sürükleyin · bir numaraya dokunun","r_artist":"Sanatçı","r_date":"Tarih","r_place":"Yer","r_medium":"Teknik","r_size":"Boyut","r_museum":"Müze","r_credit":"Edinim","r_rights":"Görsel","met":"Metropolitan Sanat Müzesi","cc0":"Açık erişim (kamu malı)","metlink":"Eserin müzedeki sayfası","credit":"Görseller: Metropolitan Sanat Müzesi, Cleveland Sanat Müzesi, Chicago Sanat Enstitüsü ve Rijksmuseum, açık erişim (kamu malı).","cma":"Cleveland Sanat Müzesi","aic":"Chicago Sanat Enstitüsü","rijks":"Rijksmuseum, Amsterdam"},"nefertari":{"title":"Senet oynayan Kraliçe Nefertari","artist":"Nina de Garis Davies (kopya)","date":"aslı MÖ y. 1290–1224 · kopya 1921–22","place":"Mısır (Kraliçeler Vadisi)","game":"Senet","medium":"Kâğıt üzerine tempera (yarı boyutta kopya)","p":["Nefertari, II. Ramses’in baş eşiydi. Bu, Kraliçeler Vadisi’ndeki mezarındaki bir resmin, 1921–22’de mezarın içinde yapılmış kopyasıdır; duvardaki çatlaklar ve kayıplar bile kopyalanmıştır.","Kraliçe bir tahtanın önünde oturmuş, görünmeyen bir rakiple senet oynuyor. Bir mezara resmedilen oyunun, eğlenceden öte bir anlamı olduğu düşünülür: öbür dünyaya giden yolculuğu kazanmak."],"spots":[["İki tür taş","Tahtada sivri başlı taşlar ve makara biçimli taşlar duruyor: her oyuncuya bir takım."],["Kraliçenin eli","Parmakları bir taşa uzanıyor."],["Tahta ve sehpa","Tahta yandan gösterildiği için haneler görünmüyor. İnce ayaklı bir sehpanın üstünde duruyor."],["Adı","Kraliçenin adı oval bir çerçevenin, kartuşun içine yazılmış."],["Görünmeyen rakip","Karşısında kimse yok: Kraliçe görünmeyen bir rakiple oynuyor."]]},"hydria":{"title":"Tahta oyunu oynayan Akhilleus ve Aias (su testisi)","artist":"Leagros Grubu’na atfedilir","date":"MÖ y. 510","place":"Yunanistan (Attika)","game":"Bir zar oyunu","medium":"Pişmiş toprak (siyah figür)","p":["Truva kuşatması sırasında iki Yunan kahramanı, Akhilleus ve Aias, bir tahtanın başında vakit geçiriyor. Sahneyi MÖ 540 dolaylarında çömlekçi ve ressam Eksekias tasarlamıştır; aslı Vatikan Müzeleri’ndeki bir amforada durur.","Konu yaklaşık MÖ 540–480 arasında çok sevilmiş, 150’den fazla örneği bilinir. Bu testide ortada tanrıça Athena duruyor. Kahramanlar, taşların zar atışına göre ilerlediği bir oyun oynuyor."],"spots":[["Athena","Tanrıça Athena ikisinin arasında duruyor."],["Soldaki kahraman","Mızrağı hâlâ elinde, tahtaya eğiliyor."],["Sağdaki kahraman","O da silahlarını bırakmamış: savaşın ortasında kısa bir oyun."],["Tahta","Aralarındaki alçak blok tahtadır."],["Omuz","Testinin omzunda bir savaş arabası yola çıkıyor."]]},"liubo":{"title":"Liubo oynayan iki oturan figür","date":"MÖ 1. yüzyıl – MS 1. yüzyıl","place":"Çin (Han hanedanı)","game":"Liubo","medium":"Boyalı pişmiş toprak","p":["Han Çini’nin gözde oyunu liuboyu oynayan iki kişi. Bu tür figürler, hayatın zevklerinin ölümden sonra da sürmesi dileğiyle mezarlara konurdu.","Fotoğrafta aralarında bu müzenin koleksiyonundaki liubo tahtası ve kemik taşları duruyor. Figürler, kızışmış bir oyunun dramatik bir anını yakalıyor."],"spots":[["Liubo tahtası","Koleksiyondaki “Liubo Tahtası ve Taşları” ile aynı tahta: T, L ve V işaretlerine bakın."],["Soldaki oyuncu","Tahtayı sakin sakin inceliyor."],["Sağdaki oyuncu","Eli havada, ağzı kocaman açık: kazandıran hamleyi mi yaptı?"],["Tahtadaki taşlar","Kemik taşlar tahtanın iki ucunda duruyor."],["Tahta dışındaki taşlar","Yerde de taşlar var."]]},"shahnama":{"title":"“Büzürcmihr Hint oyunu satrancı çözer”, Şah Tahmasb’ın Şehnamesi’nden","artist":"Resim Abdülvahhab’a atfedilir","date":"y. 1530–35","place":"İran (Tebriz)","game":"Satranç","medium":"Kâğıt üzerine opak suluboya, mürekkep, gümüş ve altın","p":["Firdevsi’nin destanı Şehname’den (Şahlar Kitabı) bir sahne. Hint kralı bir elçiyle satranç tahtası ve taşları gönderip İran kralı Nuşirevan’a meydan okur: oyunun nasıl oynandığını bulursa Hindistan haraç ödeyecektir.","Bunu vaktinde ancak genç bilge Büzürcmihr çözer. Şehname’de İran karşılık olarak tavlayı gönderir ve Hintliler onu çözemez. Kral ve saray halkı gözlerini tahtaya ve oyunculara dikmiş."],"spots":[["Satranç tahtası","Taşlar kareli bir tahtada duruyor; o kadar küçükler ki biçimleri zor seçiliyor."],["Kral Nuşirevan","Tahtında, bilmecenin çözülmesini bekliyor."],["Tahtanın çevresinde","Oyuncular tahtaya eğilmiş."],["Beyitler","Üstteki ve alttaki çerçevelerde Firdevsi’nin beyitleri yazılı."],["Saray halkı","Kırmızı uzun çubuklu sarıklı adamlar ayakta izliyor."]]},"chaupar":{"title":"Çaupar oynayan Şiva ve Parvati, bir Rasamancari serisinden","artist":"Nurpurlu Devidasa","date":"1694–95","place":"Hindistan (Basohli, Cammu)","game":"Çaupar (Ludo’nun atasının akrabası)","medium":"Kâğıt üzerine opak suluboya, mürekkep, gümüş ve altın","p":["15. yüzyıldan bir Sanskrit aşk şiiri olan Rasamancari’yi resimleyen bir seriden bir sayfa. Tanrı Şiva ile eşi Parvati, bir kaplan postunun üstünde haç biçimli bir tahtanın başında oturuyor.","Şiva hile yaparak Parvati’nin kolyesini almış, Parvati de geri vermesi için yalvarıyor. Cesur renkler, belirsiz bir mekân derinliği, anlam taşıyan renk ve jestler: Basohli okulunun izleri."],"spots":[["Haç biçimli tahta","Çaupar ve pachisi bu haç biçimli tahtada oynanır."],["Tahtadaki beyaz çubuklar","Muhtemelen çauparın uzun zarları (pasa)."],["Şiva","Bembeyaz gövde, boynunda bir yılan."],["Parvati","Elini uzatmış, kolyesini geri istiyor."],["Kaplan postu","İkisi de bir kaplan postunun üstünde oturuyor."]]},"shogi":{"title":"Şogi oynayan genç bir kadın ve erkek (“Çūnagon Kanesuke”, Otuz Altı Ölümsüz Şair serisinden)","artist":"Suzuki Harunobu","date":"y. 1767–69","place":"Japonya (Edo)","game":"Şogi","medium":"Renkli ağaç baskı (nişiki-e)","p":["Otuz Altı Ölümsüz Şair’e gönderme yapan bir seriden bir baskı; bu, şair Çūnagon Kanesuke’yi temsil ediyor. Bir yaz gecesi, bir cibinliğin yanında genç bir kadınla bir erkek şogi tahtasının başında.","Harunobu, birçok kalıpla basılan çok renkli baskıları yaygınlaştıran sanatçıdır. Tahtadaki taşlar bile ayrıntılı çizilmiş."],"spots":[["Ayaklı şogi tahtası","Bugünkü gibi ayaklı, kalın bir tahta."],["Küçük bir kutu","Muhtemelen taşların kutusu."],["Cibinlik","Yeşil bir cibinlik asılı: bir yaz gecesi."],["Fener","Ayaklı bir lamba tahtayı aydınlatıyor."],["Şiir","Bulut biçimli çerçevede şairin adı ve bir şiir var."]]},"sugoroku":{"title":"Sugoroku oynayan iki genç kadın","artist":"I. Utagawa Toyokuni","date":"Edo dönemi (18. yy. sonu – 19. yy. başı)","place":"Japonya (Edo)","game":"Ban-sugoroku (tavlanın akrabası)","medium":"İki parçalı renkli ağaç baskı","p":["İki baskı birleşerek geniş bir resim oluşturuyor: bir odada toplanmış genç kadınlar ban-sugoroku oynuyor. Oyun tavlanın akrabasıdır; bu koleksiyondaki Şōsōin sugoroku tahtasıyla aynı soydandır.","Tahtada beyaz ve siyah pullar var; sağdaki genç kadın zarları sallamak için bir kap tutuyor. Pencereden Fuji Dağı görünüyor."],"spots":[["Tahta","Uzun hanelerinde beyaz ve siyah pullar."],["Zar kabı","Zarlar bu kapta sallanır."],["Tahta dışındaki pullar","Çoktan toplanmış mı, yoksa henüz girmemiş mi?"],["Fuji Dağı","Pencerenin ardında Fuji."],["Birleşme yeri","İki baskı burada birleşiyor."]]},"eakins":{"title":"Satranç Oyuncuları","artist":"Thomas Eakins","date":"1876","place":"ABD (Philadelphia)","game":"Satranç","medium":"Ahşap üzerine yağlıboya","p":["Philadelphia’daki bir evin salonunda iki arkadaş satranç oynuyor, sanatçının babası Benjamin Eakins de izliyor. Eakins özenli mekân kurgusunu ve titiz ayrıntıyı Paris’teki hocası Gérôme’dan öğrenmişti.","1881’de Satranç Oyuncuları, Metropolitan Müzesi’nin yaşayan bir sanatçıdan bağış olarak kabul ettiği ilk eser oldu."],"spots":[["Satranç taşları","Loş odada tahtadaki taşlar ışıkta öne çıkıyor."],["Sanatçının babası","Ayakta oyunu izleyen kişi: Benjamin Eakins."],["Sağdaki oyuncu","Ressam George W. Holmes, sanatçının babasının arkadaşı."],["Çekmece","Latince bir yazı: “Bunu Benjamin Eakins’in oğlu ’76’da yaptı.”"],["Şöminenin üstü","Eakins’in hocası Gérôme’un bir tablosunun reprodüksiyonu."],["Kedi","Yerde, oyunla ilgilenmeyen tek kişi kedi gibi."]]},"weiqi":{"title":"Weiqi oynayan ölümsüzler tabağı","artist":"Bilinmiyor","date":"1425–36 (Ming hanedanı, Xuande dönemi)","place":"Çin","game":"Go (weiqi)","medium":"Oyma kırmızı ve yeşil lake","size":"Y. 3,5; G. 14,9; U. 23,5 cm","credit":"Florence ve Herbert Irving bağışı, 2015","p":["Oyma lakeden bir tabak: onlarca kat lake sürülüp sonra oyulmuştur; kırmızının altında yeşil bir kat vardır, oyma derinliği renkleri ortaya çıkarır. Dilimli kenarın içinde ölümsüzler bir çamın altında go oynar.","Çin’de “çürümüş balta sapı” anlamına gelen Lanke efsanesi vardır: oduncu Wang Zhi dağda ölümsüzlerin go oyununu seyreder, kendine geldiğinde o kadar zaman geçmiştir ki baltasının sapı çürümüştür. Tahta başındaki ölümsüzler sevilen bir konuydu. Ayaktaki kişinin kim olduğunu kayıtlar söylemez."],"spots":[["Tahta","İki ölümsüzün arasındaki go tahtası, çizgilerine kadar oyulmuş."],["Oynayan ölümsüzler","Kayaların yanında tahtanın başında oturan iki kişi."],["Ayaktaki kişi","Biraz uzakta duran bir kişi. Efsanedeki oduncuyu hatırlatır ama kim olduğu bilinmez."],["Ay","Gökte yuvarlak bir ay (belki de güneş)."],["Çam","Dallarını geniş açmış bir çam; uzun ömrü ve ölümsüzler diyarını simgeleyen bir ağaç."],["Şakayıklı kenar","Kenara iri şakayıklar ve yapraklar oyulmuştur."]]},"webb":{"title":"Tavla oynayanlar (dolap)","artist":"Philip Webb (tasarım), Edward Burne-Jones (resim), Morris, Marshall, Faulkner & Co. (yapım)","date":"1861","place":"Britanya (Londra)","game":"Tavla","medium":"Boyalı çam, deri üzerine yağlıboya, pirinç, bakır","size":"Y. 185,4; G. 114,3; D. 53,3 cm","credit":"Rogers Fonu, 1926","p":["William Morris’in 1861’de arkadaşlarıyla kurduğu firmanın en erken mobilyalarından biri. Kapakların derisi üzerine, Orta Çağ giysileri içinde tavla oynayan bir erkek ve bir kadın yağlıboyayla resmedilmiştir. 1862 Londra Uluslararası Sergisi’nde gösterildi.","Güzel sanatlarla uygulamalı sanatlar arasındaki sınırı kaldırmak isteyen Arts and Crafts hareketinin amacını özetler. Deri zemin, Orta Çağ tekniğiyle minik noktalarla zımbalanmıştır."],"spots":[["Tahta","İkisinin arasındaki masada duran tavla tahtası."],["Erkek","Elinde bir pul, tahtaya bakan genç bir adam."],["Kadın","Karşısında elinde pul (ya da zar kabı) tutan bir kadın."],["Ayaklarının dibindeki çiçekler","Oyuncuların ayaklarının dibinde çiçekler açar."],["Zımbalanmış deri","Deri zemin, ışığı yakalayan ince noktalarla zımbalanmıştır."],["Baklava bantları","Altın zemin üzerine baklava desenli bantlar kapakları üstten ve alttan çerçeveler."]]},"liberale":{"title":"Satranç Oynayanlar","artist":"Liberale da Verona","date":"1475 dolayları","place":"İtalya (Verona)","game":"Satranç","medium":"Ahşap üzerine tempera","size":"34,9 × 41,3 cm","credit":"Maitland F. Griggs Koleksiyonu, Maitland F. Griggs vasiyeti, 1943","p":["Rönesans İtalya’sında gelinin çeyizini koyduğu süslü sandık “cassone”nin ön yüzünden bir parça. Liberale, Siena Katedrali’nin koro kitaplarındaki minyatürleriyle de tanınır.","Adı bilinmeyen bir aşk öyküsünden bir an görülür. Eş parçada pencerenin önündeki genç kız bir delikanlıyı içeri çağırıyor gibidir; burada ise ikisi satranç oynar. Müzeye göre kız kaybetmek üzeredir. Satranç, dönemin aşk edebiyatında kur yapmanın sevilen bir simgesiydi."],"spots":[["Satranç tahtası","Koyu taşların dizildiği kırmızı-beyaz tahta; oyun sona yaklaşmış görünüyor."],["Delikanlı","Tahtaya uzanan delikanlı; oyunu o kazanacak gibi."],["Genç kız","Karşısında oturuyor; eş parçada onu pencereden çağırır."],["Pencere","Açık pencerenin ardında bir tepe ve gökyüzü."],["İzleyen gençler","Kollarını kavuşturmuş adamlar oyunu izliyor."],["İzleyen genç kızlar","Sütunun ardından oyuna bakan kızlar."]]},"mirror":{"title":"Satranç oynayan çiftli ayna kabı","artist":"Bilinmiyor","date":"1325–50","place":"Fransa (Paris)","game":"Satranç","medium":"Fildişi","size":"Çap 10,2 cm","credit":"J. H. Wade Fonu ile satın alındı, 1940","p":["Avuç içi büyüklüğündeki bu fildişi disk bir el aynasının kapağıydı. 14. yüzyıl Paris’inde cilalı metal ayna iki fildişi levha arasına konup yanda taşınırdı; böyle oymalar sarayın ve soyluların sevdiği lüks eşyalardı.","Perdeleri toplanmış bir çadırda bir delikanlı ile bir hanım satranç oynuyor. Orta Çağ öykülerinde satranç hem aşkı hem savaşı simgelerdi. Çiftin Tristan ile İsolde ya da Lancelot ile Guinevere olduğu öne sürülmüştür, ama kimse bilmiyor. Müze ziyaretçilerine soruyor: Sizce kim kazanıyor?"],"spots":[["Satranç tahtası","Tek ayaklı bir masa üzerindeki tahta; üstünde birkaç taş var."],["Delikanlı","Sıradaki hamlesini yapmak için uzanıyor."],["Hanım","Başörtülü bir kadın; parmak uçları bir taşa dokunuyor."],["Kapalı el","Öbür eli yumruk hâlinde kucağında. Aldığı bir taşı mı tutuyor?"],["Çadır","İki yana bağlanmış perdeler; ayna kaplarındaki satranç sahnelerinin sevilen dekoru."]]},"morris":{"title":"Bir oyun tahtası (dokuz taş)","artist":"Peter Flötner","date":"1500–46","place":"Almanya","game":"Dokuz taş (Nine Men’s Morris)","medium":"Ağaç baskı","credit":"Charles W. Harkness Vakıf Fonu, 1923","p":["Rönesans Nürnberg’inin en yetenekli heykeltıraşlarından Peter Flötner’in bir ağaç baskısı. Flötner süsleme desenleri, mobilya, kuyumcu modelleri ve hicviyle ünlü bir oyun kâğıdı destesi de tasarladı. Kıvrılan yaprakların altında, Almancada “Mühle” denen dokuz taş oyununun tahtası saklı: kenar ortalarından birbirine bağlanan iç içe üç kare.","Tahtada 24 nokta var. Kendi üç taşını bir sıraya dizen (değirmen) rakibin bir taşını alır. Bu tür baskılar zanaatkârlara da örnek olurdu; müze bu yaprağı kuyumcu modelleri ve tasarımları sergisinde gösterdi. Kâğıdın üstünde mi oynandığı, yoksa ağaca ya da metale mi aktarıldığı bilinmiyor."],"spots":[["Orta kare","En içteki kare; ince örgü desenle dolu."],["Dış köşe","Dış karenin köşesi — taşların konduğu 24 noktadan biri."],["Orta köşe","Ortadaki karenin köşeleri de birer noktadır."],["Bağlantı çizgileri","Üç kareyi kenar ortalarından bağlayan şeritler; taşlar bunların üstünde de yürür."],["Maske","Üstte, altta ve yanlarda kıvrımlı kartuşlar ve yüzler — Rönesans grotesk süslemesi."],["Asma bordürü","Siyah zemin üzerine beyaz oyulmuş yapraklar ve meyveler."]]},"leifeng":{"title":"Leifeng Pagodası oyun tahtası","artist":"Bilinmiyor","date":"1736–95 (Qianlong dönemi)","place":"Çin","game":"Yarış oyunu","medium":"Ağaç baskı; kâğıt üzerine mürekkep","size":"31 × 29,8 cm","credit":"J. H. Wade Fonu ile satın alındı, 2025","p":["Qing Çini’nde İmparator Qianlong döneminden, oynamak için basılmış tek bir yaprak. Kareleri Beyaz Yılan Efsanesi’nin kahramanlarıyla dolu: yılan ruhu Bai Suzhen (“Beyaz Hanım”), arkadaşı Xiaoqing (“Küçük Yeşil”), genç Xu Xuan (sonraki anlatımlarda Xu Xian) ve sonunda Beyaz Hanım’ı Batı Gölü kıyısındaki Leifeng Pagodası’nın altına hapseden keşiş Fahai.","Yol, 起馬 (“yola çık”) yazılı kareden sarmal çizerek ortadaki pagodaya gider. Oyuncular herhalde Batı’daki Kaz Oyunu gibi zarla öykü boyunca yarışırdı; kuralları kayıtlı değil. Müzeye göre bu tür renkli baskılar şehirlerde satılır, duvarlara asılır, kent görsel kültürünün parçası olurdu — her renk ayrı oyulmuş bir kalıpla basılırdı."],"spots":[["Başlangıç","起馬, “yola çık” yazılı kare — büyük olasılıkla başlangıç noktası."],["Beyaz Hanım ile Küçük Yeşil","Yılan ruhu Bai Suzhen ve arkadaşı Xiaoqing."],["Xu Xuan","Beyaz Hanım’la evlenen delikanlı."],["Keşiş Fahai","Onu pagodanın altına hapseden keşiş."],["Leifeng Pagodası","Hangzhou’da Batı Gölü kıyısındaki pagoda; öykünün bittiği yer."],["Merkez","Pagodanın önünde oturan bir kadın ve diz çökmüş bir adam — öykünün son sahnesi, belki de bitiş."]]},"tutinama":{"title":"Yaralı maymun satranç arkadaşı prensin elini ısırıyor (Tuti-nâme, “Papağanın Masalları”ndan)","artist":"Dasavanta","date":"1560 dolayları","place":"Hindistan (Ekber’in Babür sarayı)","game":"Satranç","medium":"Kâğıt üzerine guaj, mürekkep ve altın","size":"20 × 14,2 cm (resim 10,2 × 10,6 cm)","credit":"Bayan A. Dean Perry bağışı, 1962","p":["Babür imparatoru Ekber’in sarayında hazırlanan Tuti-nâme’den (“Papağanın Masalları”) bir resim. Anne papağanın, yavrularını tilki yavruları gibi başka türden hayvanlarla dostluk kurmaktan sakındırmak için anlattığı öykülerden biri: satrançta usta bir maymun sık sık bir prensle satranç oynarmış.","Bir gün konukların önünde maymun kaba bir şaka yapmış, prens onu tokatlamış, maymun da prensin elini ısırmış. Sağda, dışarıda hizmetkârlar yemek hazırlarken konuklar şaşkınlıkla bakıyor. Alttaki yazı, sonradan Babür sarayının en ünlü ustalarından biri olacak Dasavanta’nın adını veriyor; genç ressam resminin altına serin bir mavi katman sürmüş."],"spots":[["Maymun","Satranç arkadaşı prensin elini ısırıyor."],["Prens","Eli ısırılan prens."],["Satranç tahtası","Yerde kırmızı kareli bir tahta."],["Şaşkın konuklar","Toplantıya çağrılan konuklar."],["Yemek hazırlığı","Dışarıda kazanları ateşe koyan hizmetkârlar."],["Farsça metin","Yukarıda öykü Farsça yazılmış."]]},"teniers":{"title":"Tavla oyunu","artist":"David Teniers","date":"1640’lar","place":"Flandre","game":"Tavla (backgammon)","medium":"Ahşap üzerine yağlıboya, tuvale aktarılmış","size":"59 × 80,6 cm","credit":"Bay ve Bayan Samuel D. Wise bağışı, 1943","p":["Flaman ressam Teniers’in yüksek bahisli bir tavla maçını gösteren tablosu. Oyun çok eskidir: bugünkü biçimi 1400’lerde ortaya çıktı, “backgammon” adı da aşağı yukarı bu resmin yapıldığı sıralarda doğdu. 1600’lerde çok yaygındı ve sık sık para için oynanırdı.","İki oyuncunun çevresini seyirciler sarmış, duvar dibinde de biri puan tutuyor. Seyreden kadınlardan — biri pencereden sarkıyor — yola çıkan müze, odanın bir genelevin oyun odası olduğunu düşünüyor. Böyle oyun sahneleri çoğu zaman bir ders taşırdı: kumar aptalca, hatta kötüdür ve vakit kaybıdır."],"spots":[["Tahta","Masada açık bir tavla tahtası; oyun sürüyor."],["Beyazlı adam","Sırtı dönük oyuncu, pullarına uzanıyor."],["Düşünceli adam","Rakibi, elini yanağına dayamış."],["Puan tutan","Duvardaki tahtaya işaret koyan adam — puan mı, bahis mi?"],["Penceredeki kadın","Yukarıdan bakan yaşlı bir kadın."],["Arka oda","Arkada erkekler genç bir kadının yanında içiyor."]]},"imari":{"title":"Go oynayan iki adamlı tabak","artist":"Bilinmiyor","date":"18. yüzyıl","place":"Japonya (Edo dönemi)","game":"Go","medium":"Kalıpta biçimlendirilmiş porselen, sır üstü boya (Hizen, Imari üslubu)","size":"2,4 × 13,8 cm","credit":"Severance ve Greta Millikin Koleksiyonu, 1964","p":["Bu küçük kare tabakta iki adam bir çam ağacının altında go oynuyor: sarılı olan, doğrudan yere konmuş tahtanın karşısında oturuyor; yeşilli rakibi ağaca yaslanmış.","Hizen’de (bugünkü Saga ve Nagasaki) yapılmış bir Imari porseleni; yeşilleri Kutani emayelerini andırıyor. Japonya’nın Avrupa’ya porselen tedarikinde Çin’in yerini aldığı dönemde ihracat için yapıldı."],"spots":[["Go tahtası","Yere doğrudan konmuş, çizgili bir tahta."],["Sarılı adam","Tahtanın karşısında oturuyor."],["Yeşilli adam","Rakibi; gülümseyerek ağaca yaslanmış."],["Çam","Başlarının üstüne dallarını uzatan çam."],["Kırmızı çerçeve","Köşeleri kesik kırmızı bir çerçeve sahneyi kuşatıyor."]]},"shoei":{"title":"Dört Hüner (bir çift paravandan biri)","artist":"Kanō Shōei’ye atfedilir","date":"16. yüzyıl sonu–17. yüzyıl başı","place":"Japonya (Momoyama dönemi)","game":"Go","medium":"Bir çift altı kanatlı paravandan biri; kâğıt üzerine mürekkep ve hafif renk","size":"153 × 358,6 cm","credit":"John L. Severance Fonu, 1979","p":["Kanō okulundan Kanō Shōei’ye atfedilen altı kanatlı bir paravan. Eşiyle birlikte kültürlü bir Çinli beyefendiden beklenen “dört hüner”i gösterir: qin çalmak, qi (go) oynamak, hat ve resim. Burada yüksek mevkili Çinli beyefendiler hizmetkârlarıyla çamların altında kırda dinleniyor.","Ortada iki adam go oynuyor, üçüncüsü izliyor. Yanlarındaki masada kitaplar ve hâlâ kumaş kılıfında duran, çalınmayı bekleyen bir qin var. Sahne eğlenceyle resmiyeti dengeliyor. Müze, hizmetkârlardan birinin sudaki bir balığın hareketine dalıp gittiğine dikkat çekiyor."],"spots":[["Go tahtası","Ayaklı bir tahta; iki beyefendi karşılıklı oynuyor."],["Beyefendiler","İki oyuncu ve izleyen üçüncüsü."],["Masa","Büyük olasılıkla kitapların ve kılıfındaki qin’in durduğu masa."],["Hizmetkârlar","Masanın yanında bekleyen hizmetkârlar."],["Dalgın hizmetkâr","Su kıyısına uzanmış, bir balığı izliyor."],["Çam","Sahnenin üstüne dallarını yayan büyük bir çam."]]},"umaya":{"title":"Ahır Paravanı (verandada go ve shogi)","artist":"Bilinmiyor","date":"16. yüzyılın başı","place":"Japonya (Muromachi dönemi)","game":"Go ve shogi","medium":"Altı kanatlı bir çift paravandan biri; kâğıt üzerine mürekkep, renk ve altın","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Altı kanadın birleştirildiği bu paravan bir çiftin tekidir. Asıl konu bölmelerdeki değerli atlar olabilir, ama öndeki verandada da pek çok şey oluyor.","Orada insanlar iki ayrı oyunda yarışıyor: solda go, sağda shogi. Müzeye göre sahnenin canlılığı, huzursuz atlarla oyunların sessiz stratejisi arasındaki karşıtlıktan doğuyor. Japonyada maymunların atları koruduğuna inanılır, ahırlarda bazen maymun beslenirdi."],"spots":[["Go tahtası","İnce çizgili, üzerinde siyah taşlar olan bir tahta."],["Siyah başlıklı iki adam","Uzun siyah eboshi başlıklı adamlar: yeşilli olan tahtaya uzanıyor, kırmızılı olan izliyor."],["Shogi tahtası","Büyük kareli bir tahta; go tahtasındakinden çok daha az kare var."],["Gülen rakip","Başı tıraşlı bir keşiş bir taş alırken karşısındaki adam elini başına koyup kahkaha atıyor. Biri az önce puan mı aldı?"],["Bir maymun","Verandanın ucunda, kırmızı giysili bir maymun mu?"],["Bir at","İplerle bağlı siyah bir at şaha kalkıyor."]]},"goryeo":{"title":"Go oynayan figürlerle kakmalı seladon testi","artist":"Bilinmiyor","date":"13. yüzyıl","place":"Kore (Goryeo hanedanı)","game":"Go (baduk)","medium":"Beyaz ve siyah astar kakmalı seladon","size":"Yük. 20,4 cm, çap 14,3 cm","credit":"John L. Severance bağışı, 1917","p":["Emzikli ve kulplu bir Goryeo seladon testisi. Kakma tekniği — kile çizgiler kazıyıp beyaz ve siyah astarla doldurmak, sonra sırlayıp pişirmek — Goryeo çömlekçilerinin ustalığıydı; burada yuvarlak bir çerçevenin içinde, söğüt altında oturan iki figür beyaz olarak belirir.","Aralarında bir tahta var; müze sahneyi go (Korecede baduk) oynayanların resimlerine benzetir. Çalgı çalmak, go, hat ve resim, kültürlü bilginin “dört hüneri” sayılırdı ve zarif buluşmaları zanaatkârlar için de bir motif oldu. İnsan figürlü Kore seladonu nadirdir."],"spots":[["Tahta","İkisinin arasındaki tahta, beyaz bir kare."],["Soldaki figür","Tahtaya dönük oturuyor."],["Sağdaki figür","Karşısında oturan rakip."],["Söğüt","Başlarının üstüne sarkan, siyah astarla çizilmiş söğüt dalları."],["Bulut çerçeve","Yuvarlak çerçevenin çevresini bulut gibi kıvrımlar dolanır."],["Çatlaklar","Sırdaki ince çatlaklar. Kil ile sır farklı oranda büzüldüğü için soğurken oluşur."]]},"kangra":{"title":"Terasta chaupar oynayan çift","artist":"Bilinmiyor","date":"y. 1790–1800","place":"Hindistan (Pahari, Kangra okulu)","game":"Chaupar","medium":"Kırmızı aşı boyasıyla ön çizimli desen","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Himalayaların eteğindeki Pahari tepelerinde, Kangralı bir sanatçının deseni. İlk taslak kırmızıyla (kırmızı aşı boyası) yapılmış, sonra siyahla netleştirilmiş. Üstünde renk olmadığından figürlerin ve eşyaların her çizgisi izlenebilir.","Bir terasta, haç biçimli bir tahtanın iki yanında oturan bir kadın ve bir erkek chaupar oynuyor; pachisi ile aynı haç üzerinde oynanan ve uzun zarlar (pasa) atılarak ilerlenen eski bir Hint yarış oyunu. Tahtaya kareler henüz çizilmemiş. Hizmetçiler çifte hizmet ediyor."],"spots":[["Haç biçimli tahta","Yerde haç biçimli bir tahta. Kareleri henüz çizilmemiş."],["Kadın","Avucu yukarıda — zarları atmak üzere mi?"],["Erkek","Sorguçlu sarıklı; elini tahtaya uzatıyor."],["Soldaki hizmetçi","Küçük bir şişe tutuyor ve bir bez uzatıyor."],["Sağdaki hizmetçi","Uzun saplı bir alet ve küçük bir kap tutuyor."],["Kırmızı taslak","Sarığın çevresinde, siyah çizgilerin altından kırmızı taslak görünüyor."]]},"vuillard":{"title":"Dama Oyunu (Manzaralar ve İç Mekânlar’dan)","artist":"Édouard Vuillard","date":"1899","place":"Fransa","game":"Dama","medium":"Renkli litografi (III/III. durum); baskı Auguste Clot, yayımcı Ambroise Vollard","size":"Görüntü 33 × 25,7 cm (kâğıt 38 × 30,8 cm)","credit":"Hanna Fund bağışı, 1951","p":["İzlenimci resim satıcısı Ambroise Vollard aynı zamanda önemli bir baskı yayımcısıydı. 1895’te Pierre Bonnard’a 12 renkli litografiden oluşan bir albüm ısmarladı; ardından pek çok albüm daha yayımladı. Vuillard’ın Manzaralar ve İç Mekânlar’ı da bunlardan biridir ve usta baskıcı Auguste Clot tarafından basılmıştır.","Bonnard ve Vuillard, İbranicede “peygamberler” anlamına gelen Nabiler grubundandı. Biçim ve rengin kendisiyle duygu anlatan yeni bir sanat arıyor, kent ve aile yaşamından sahneleri seviyorlardı. Desenlerle dolu bir odada iki adam dama tahtasının başında karşılıklı oturuyor, ayaktaki bir kadın oyunu izliyor. Fransızcada dama “dames” diye anılır; sol alttaki kurşun kalem notu “partie de dames”, yani “bir dama oyunu” diye okunur."],"spots":[["Tahta","Taşları dizilmiş küçük, kareli bir tahta."],["Soldaki adam","Sakallı bir adam elini tahtanın üzerine uzatıyor."],["Sağdaki adam","Rakibi, koltukta tahtaya eğilmiş; ayaktaki kadın onu yarı yarıya kapatıyor."],["Ayaktaki kadın","Elini çenesine dayamış, oyunu izliyor."],["Lamba","Duvarın yanında bir lamba. Duvar kâğıdı da döşeme de desenle dolu."],["Kurşun kalem notu","Sol altta kurşun kalemle: “partie de dames” — bir dama oyunu."]]},"talbot":{"title":"Satranç Oyuncuları (erken dönem fotoğraf)","artist":"William Henry Fox Talbot’a atfedilir","date":"y. 1843–47","place":"İngiltere","game":"Satranç","medium":"Tuzlu kâğıt baskı","size":"19,9 × 15 cm","credit":"Bay ve Bayan Everett Kovler’in fonuyla satın alındı","p":["Talbot’un icat ettiği negatif-pozitif yöntemi, mümkün kıldığı sınırsız kopyalarla, dijital çağa dek fotoğrafa hâkim oldu. İlk deneyleri hem bilime ilgisini hem sanatsal hedeflerini gösterir; araştırmacılar onun satranç oyuncularını en az on kez fotoğrafladığını doğrulamıştır.","Ama bu kare onun olmayabilir: bu baskı ve aynı sahnenin diğerleri imzasızdır ve Talbot’un alışık olduğu kâğıttan farklı bir kâğıda basılmıştır. Oturanlar büyük olasılıkla fotoğrafçı Antoine Claudet ile Talbot’un yardımcısı Nicolaas Henneman’dır; yeni araştırmalara göre görüntüler Claudet’nin stüdyosunda çekilmiş, Henneman’a geçmiş ve bir borcun karşılığı olarak Talbot’a verilmiştir (müze notu)."],"spots":[["Tahta","Masadaki satranç tahtası, taşlar sıra sıra."],["Silindir şapkalı adam","Şapkası başında, bir taşa uzanıyor."],["Düşünceli adam","Eli çenesinde, rakip tahtayı inceliyor."],["Perde","Arkada asılı bir perde — çekim için bir fon mu?"],["Bir şapka daha","Sağdaki sehpada ikinci bir silindir şapka duruyor."]]},"pvl":{"title":"Zar Oynayan Adamlar","artist":"Usta PVL","date":"y. 1520","place":"Hollanda (Alçak Ülkeler)","game":"Zar","medium":"Kâğıt üzerine gravür","size":"9,4 × 9,4 cm (yuvarlak)","credit":"Charles Hack ve Hearn Ailesi Vakfı Koleksiyonu, 2023’te satın alındı","p":["16. yüzyıl başında Alçak Ülkeler’de çalışmış adı bilinmeyen bir gravürcünün eseri; sol altta kazınmış “PVL” monogramından ötürü Usta PVL diye anılır. Avuç içine sığacak kadar küçük yuvarlak baskıda sık, ince çizgiler odanın derinliğini ve giysilerin dokusunu kurar.","Masada iki zar var. Öne eğilmiş bir adam ile kürk yakalı bir genç parmakla gösterip tartışıyor — belki sayı üzerine. Arkada kadınlar izliyor, masanın altında bir şarap testisi duruyor. Zar, antik çağdan beri kumarla bağlantılıdır ve tekrar tekrar yasaklanmıştır."],"spots":[["Zarlar","Masada yuvarlanan iki zar."],["Gösteren eller","İki parmak masada buluşuyor — sayı üzerine bir tartışma mı?"],["Geniş şapkalı adam","Öne eğilmiş; yırtmaçlı kabarık kolları dönemin modasıydı."],["Kürk yakalı genç","Büyük şapkalı, kürk yakalı bir genç."],["İzleyen kadınlar","Kadınlar arkadan oyuna bakıyor."],["Monogram","Sol alttaki “PVL” — sanatçının adına dair tek ipucu."]]},"kiyohiro":{"title":"Sugoroku Oyuncuları","artist":"Torii Kiyohiro","date":"y. 1750","place":"Japonya (Edo dönemi)","game":"Ban-sugoroku","medium":"Renkli ağaç baskı (benizuri-e), ōban; yayımcı Urokogataya","size":"43,5 × 29,3 cm","credit":"Clarence Buckingham Koleksiyonu","p":["Torii Kiyohiro, yaklaşık 1737–1776 arasında çalışmış bir ukiyo-e sanatçısıdır. Bu bir benizuri-e’dir: tam renkli nishiki-e’lerin 1765’te ortaya çıkmasından önceki yıllarda, pembe beni ve yeşil gibi az sayıda renk kalıbıyla basılmıştır.","Siyah ayaklığın üzerindeki oyun ban-sugoroku’dur: iki oyuncu zar atıp beyaz ve siyah taşları ilerletir, taşlarının hepsini önce çıkaran kazanır. Tavla ile aynı aileden bir oyundur ve ukiyo-e baskıları kadınları bu oyunla sıkça gösterir. Arkada bir kadın uzun bir pipo içerek izliyor."],"spots":[["Tahta","Ayaklığı üzerinde, beyaz ve siyah taşlı bir sugoroku tahtası."],["Soldaki figür","Bir taşı oynatmak için uzanıyor."],["Sağdaki kadın","Tahtaya eğilmiş rakip taşları inceliyor."],["Pipolu kadın","Uzun kiseru pipesiyle oyunu arkadan izliyor."],["Kalkık el","Sağdaki kadın küçük, siyah bir şey tutuyor — zar kabı mı?"],["İmza","“Torii Kiyohiro hitsu” imzası ve yayımcı Urokogataya’nın mührü."]]},"ingram":{"title":"Çin Satrancı Oyunu","artist":"John Ingram, François Boucher’den","date":"1741–63","place":"Fransa (Paris)","game":"Xiangqi","medium":"Asitle oyma ve gravür","size":"Kâğıt 39,4 × 27,7 cm (kalıp 24,5 × 16,4 cm)","credit":"Elisha Whittelsey Koleksiyonu, 1966","p":["Fransız ressam François Boucher’in bir çizimi, Londra doğumlu gravürcü John Ingram tarafından oyulmuştur. Ingram Paris’e taşınmış ve 1741–1763 arasında Boucher’in şinuazrilerinden — Avrupalıların hayal ettiği Çin’den — bir dizi baskı yapmıştır. Alttaki başlık “LE JEU D'ECHETS CHINOIS”, yani Çin satrancı oyunudur.","Saçları yüksekte toplanmış bir kadın kucağındaki tahtada bir taşı oynatıyor, küçük bir çocuk da izliyor. Oyunun xiangqi olduğu kabul edilir; ama gerçek xiangqi taşları hep yassı disklerdir, burada ise uzun taşlar küçük kare taşların yanında duruyor. Palmiye ve küpün üstünde oturan figür de gerçek Çin’den çok, dönemin Avrupa’sının düşlediği uzak ülkeye aittir."],"spots":[["Tahta ve taşlar","Kucağındaki tahta; uzun ve kare taşlar. Gerçek xiangqi taşları yassı disklerdir."],["Taştaki el","Sağ eli bir taşı oynatıyor."],["Elde yanak","Sol eli çenesinde, tahtaya bakıyor."],["İzleyen çocuk","Tahtanın yanında duran çocuk oyunu izliyor."],["Küpün üstündeki figür","Büyük bir küpün üstünde bağdaş kurmuş bir figür."],["Başlık ve adlar","“Dessiné par Fr. Boucher”, “Gravé par Ingram” ve başlık “LE JEU D'ECHETS CHINOIS”."]]},"posada":{"title":"Kaz Oyunu","artist":"José Guadalupe Posada","date":"1909","place":"Meksika","game":"Kaz oyunu","medium":"Kâğıt üzerine çinko kabartma baskı","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["İskelet “calavera”larıyla ünlü Meksikalı gravürcü Posada’nın, Mexico City’deki yayımcı Antonio Vanegas Arroyo için yaptığı, üzerinde oynanan tek yapraklık bir baskı. Sol alttaki şeritte “JUEGO DE LA OCA” (kaz oyunu) yazar; yol 1 numaralı kareden merkezdeki 63’e sarmal çizerek ilerler.","Ortada kurallar (EXPLICACION) basılıdır: ilk atışta 5 ve 4 gelirse 26’ya, 6 ve 3 gelirse 53’e gidilir. Kaza (bir kuşa) gelen aynı sayıyı bir kez daha sayar; handa (Venta, 19) iki el beklenir; kuyuda (Poso, 31) ve hapishanede (Carcel, 52) başkası gelene dek kalınır; labirent (42) 39’a, ölüm (Muerte, 58) başa geri gönderir. 63’e tam olarak gelmek gerekir. Bazı karelerde bahis ödenirdi: bu aynı zamanda bir kumar oyunuydu."],"spots":[["Kurallar","Ortadaki “EXPLICACION”: her karenin etkisi ve bahsin ne zaman ödeneceği."],["1 numaralı kare","Başlangıç. Buradan yol sarmal çizerek merkeze gider."],["Kuyu (31)","Çeşmeye benzeyen bir kuyu. Düşen, başkası gelene dek kalır."],["Ölüm (58)","Kafatası karesi: başa dönülür."],["Başlık şeridi","Sol alttaki şeritte “JUEGO DE LA OCA”; altında çocuklar oynuyor."],["Yayımcının adı","Tanrıçanın şeridinde “IMPRENTA DE A. VANEGAS ARROYO” — Posada’nın pek çok baskısını yayımlayan basımevi."]]},"jintile":{"title":"Masa oyunu oynayan kadınlı karo","artist":"Bilinmiyor","date":"13. yüzyıl","place":"Çin (Jin hanedanı)","game":"Masa oyunu (büyük olasılıkla go)","medium":"Pişmiş toprak (kalıp kabartma)","size":"Yük. 27,3 cm, gen. 24,8 cm, der. 5,4 cm","credit":"Friends of Asian Art bağışlarıyla satın alındı, 2002","p":["Kuzey Çin’i yöneten Jurçen halkının hanedanı Jin (1115–1234) döneminde yapılmış kabartmalı bir karo. Çiçekli bir ağacın altında iki kadın bir sekinin üzerinde karşılıklı oturuyor, aralarında bir tahta var.","Tahtada ince bir ızgara var; büyük olasılıkla go oynuyorlar. Sağdaki kadın öne eğilip tahtayı işaret ediyor, soldaki izliyor. Kuzey Çin’deki Jin dönemi mezarlarının pek çoğu gündelik yaşam sahneli kabartma tuğlalarla kaplanırdı; bu karo da büyük olasılıkla böyle bir mezarı süslüyordu."],"spots":[["Tahta","İnce ızgaralı bir tahta, büyük olasılıkla go tahtası."],["İşaret eden el","Sağdaki kadın tahtayı işaret ediyor. Sıradaki hamlesi mi?"],["Soldaki kadın","Saçları yukarıda toplanmış, tahtaya bakıyor."],["Sağdaki kadın","Tahtaya doğru eğilmiş."],["Çiçekli ağaç","Üstlerinde çiçekli bir ağacın dalları uzanıyor."],["Seki","Oturdukları seki; ayakları arasında dalgalı bir süs var."]]},"kyosai":{"title":"Bir yellenme go oyununu altüst ediyor (bir eskiz albümünden)","artist":"Kawanabe Kyōsai","date":"19. yüzyılın ortası–sonu","place":"Japonya (Edo–Meiji dönemi)","game":"Go","medium":"26 çift yapraklı akordeon albümün bir açılımı; kâğıt üzerine mürekkep ve renk","size":"Albüm (kapalı) 28 × 18 cm","credit":"Anne ve Anthony d’Offay bağışı, Evan Turner onuruna","p":["Şogunluğun son yıllarından Meiji dönemine kadar çalışmış ressam Kawanabe Kyōsai’nin (1831–1889) eskiz albümünden bir sahne; katlanır bir albümün sayfalarına hızlı, serbest fırça darbeleriyle çizilmiş. Kanō okulunun titiz tekniğiyle yetişen Kyōsai, cinleri, karikatürleri ve hicivleriyle de sevilirdi.","Müzenin verdiği ad her şeyi anlatıyor: “Bir yellenme go oyununu altüst ediyor.” Solda siyah başlıklı bir adam eğiliyor; sağda tahta havaya uçuyor, kaplardan taşlar yağmur gibi dökülüyor, rakip sırtüstü devriliyor. Ciddi bir oyun tek bir patlamayla mahvoluyor: Kyōsai, ortaçağ tomarlarında bile görülen eski Japon yellenme mizahını hızlı fırçasıyla resmediyor."],"spots":[["Siyah başlıklı adam","Eğilmiş, kalçasını çıkarmış — kargaşanın sebebi mi?"],["Uçan tahta","Çizgili go tahtası çapraz uçup gidiyor."],["Kaplar ve taşlar","İki kap devriliyor, taşlar yağıyor."],["Yelpaze","Tahtanın yanında açık bir yelpaze de uçuyor."],["Devrilen rakip","Sırtüstü yatmış, gözleri faltaşı gibi açık."],["Fırça çizgisi","Taslaksız, bir çırpıda çekilmiş gibi güçlü mürekkep çizgileri."]]},"yokuts":{"title":"Kumar Tepsisi","artist":"Yokuts dokumacı (adı bilinmiyor)","date":"y. 1900","place":"ABD (Dunlap yakını, Kaliforniya)","game":"Huuchuish (ceviz kabuğu zarlar)","medium":"Bitki lifleri (sarmal örgü)","size":"Yük. 5,1 cm, çap 61 cm","credit":"Bayan Leonard S. Florsheim Jr.’ın fonuyla satın alındı","p":["Kaliforniya’nın pek çok yerli halkı şans oyunları oynardı. Bu tepsi, yalnızca kadınların oynadığı bir zar oyunu olan huuchuish için kullanılırdı: sekiz ceviz kabuğu zar tepsiye atılır, puanlar çubuklarla sayılırdı.","Tepsiye dokunmuş dairesel desen oyunun kendisini gösterir — zarları, sayı çubuklarını ve oyuncuları (müze notu). Kendi oyununun resmini taşıyan bir oyun aracıdır. Fotoğrafta ceviz kabuğu zarlar tepsinin üstünde ve çevresinde duruyor."],"spots":[["Oyuncular","Kenar boyunca dizilen figürler — oyuna katılanlar."],["Sayı çubukları","Kısa dikey çizgi demetleri: puan sayan çubuklar."],["Yuvarlak motifler","Küçük yuvarlak motifler — zarlar mı?"],["Ceviz zar","Ceviz kabuğundan bir zar. Sekizi tepsiye atılırdı."],["Üçgen kuşak","Koyu üçgenlerden bir kuşak çepeçevre dolanır."],["Merkez","Örgü merkezden sarmal çizerek çıkar; çevresinde kesikli bir halka var."]]},"hokkei":{"title":"Ushiwakamaru, Benkei’yi sugoroku’da yeniyor","artist":"Totoya Hokkei","date":"y. 1825","place":"Japonya (Edo dönemi)","game":"Ban-sugoroku","medium":"Surimono (renkli ağaç baskı, shikishiban)","size":"21,8 × 19,1 cm","credit":"Helen C. Gunsaulus bağışı","p":["Hokusai’nin öğrencisi Totoya Hokkei’nin (1780–1850) bir surimonosu. Surimonolar özel olarak — çoğu zaman şiir çevrelerince, kendi dizeleriyle — sipariş edilen ve ticari ukiyo-e’den daha gösterişli, iyi kâğıt ve metalik pigmentlerle basılan baskılardı.","Kahraman Minamoto no Yoshitsune’nin çocukluk adı Ushiwakamaru ile dev savaşçı keşiş Benkei. Ünlü karşılaşmaları Kyoto’daki Gojō Köprüsü’ndeki düellodur; burada ise mücadele bir sugoroku oyununa dönüşüyor: çocuk tahtanın ardında sakin oturuyor, sırtında teber taşıyan Benkei yenilgiyle başını kaşıyor. Oyunbaz bir yeniden yorum gibi görünüyor."],"spots":[["Sugoroku tahtası","Beyaz ve siyah taşlı, kutu biçimli bir tahta."],["Başını kaşıyan Benkei","Tam zırhlı, yenilen Benkei başını kaşıyor."],["Ushiwakamaru","Tahtanın ardında oturan genç kahraman."],["Teber","Benkei’nin büyük naginatasının ağzı."],["Şiir","Sağ üstteki dizeler — büyük olasılıkla baskıyı sipariş eden çevreden."],["İmza","Sağ alttaki çerçevede Hokkei’nin imzası."]]},"vorsterman":{"title":"Tavla Oyuncuları (gece sahnesi)","artist":"Lucas Emil Vorsterman, Adam de Coster’den","date":"y. 1630","place":"Flandre (Anvers)","game":"Tavla","medium":"Fildişi rengi kâğıt üzerine gravür","size":"Görüntü 25,5 × 34,4 cm","credit":"Bernard F. Rogers Koleksiyonu","p":["Adam de Coster, 1630 dolaylarında Anvers’te mum ışığında gece sahneleriyle tanınan bir ressamdı; aynı dönemde aynı kentte Vorsterman, popüler çağdaşlarının eserlerini gravüre aktarıyordu. Rubens’in öğrencisi olan Vorsterman ustasıyla bozuşup İngiltere’ye gittikten sonra, bunun gibi daha güçlü, üslupçu, Caravaggio tarzı gravürler yaptı.","Karanlık bir odada bir masanın çevresinde adamlar tavla tahtasının başına toplanmış. De Coster’in ışık kullanımını izleyerek iki mum alevi masadaki yüzleri aydınlatıyor (müze notu). Sağda lavtalı bir genç bize bakıyor."],"spots":[["Tahta","Masada kutu gibi açılmış bir tavla."],["Mum","Şamdandaki mum; alevi yüzleri aydınlatıyor."],["Pipolu adam","Geniş şapkalı, pipo içerek oyunu izliyor."],["Arkası dönük adam","Ellerini masaya dayamış, öne eğilmiş."],["Lavtacı genç","Lavtasıyla bize gülümseyen bir genç."],["Adlar","Sol altta “A. De Coster pi.”, sağ altta “Vorsterman”."]]},"zorn":{"title":"Satranç Oyuncuları","artist":"Anders Zorn","date":"1891","place":"İsveç","game":"Satranç","medium":"Fildişi rengi vergé kâğıt üzerine asitle oyma","size":"Görüntü 13,5 × 9,6 cm (kalıp 13,9 × 10 cm)","credit":"Wallace L. DeWolf ve Charles Deering’in Anders Zorn asitle oyma koleksiyonları","p":["İsveçli sanatçı Anders Zorn’un (1860–1920) bir asitle oyması. Zorn yağlıboya ve suluboya portreleriyle uluslararası ün kazanmış, gravürde de büyük bir iş bırakmıştır. Kalıp bir avuç büyüklüğündedir.","Üst üste atılmış hızlı, eğik çizgiler, bakırdan karanlık bir oda ve iki insan çıkarmaya yetiyor. Öndeki adam sırtı bize dönük, tahtaya eğiliyor; karşıdaki figür başını eğmiş, sonraki hamleyi düşünüyor. Taşlar ince çizgilerle çizilmiş. Kimlerin poz verdiği bilinmiyor."],"spots":[["Tahta ve taşlar","Alttaki açık alan tahta; kısa dikey çizgiler taşlar."],["Öndeki adam","Sırtı bize dönük, tahtaya eğilmiş."],["Rakip","Başı eğik, gözleri tahtada."],["Karanlık fon","Dikey çizgilerle kurulmuş odanın derinliği."],["Eğik çizgiler","Ceket, üst üste atılmış hızlı çapraz çizgilerden."],["İmza","Kalıbın altında kurşun kalemle “Zorn” imzası."]]},"harunobu-sugoroku":{"title":"Oyunu İzlemek (sugoroku)","artist":"Suzuki Harunobu","date":"y. 1766","place":"Japonya (Edo dönemi)","game":"Ban-sugoroku","medium":"Renkli ağaç baskı (chūban, surimono)","size":"28,5 × 21 cm","credit":"Clarence Buckingham Koleksiyonu","p":["Suzuki Harunobu (1725?–1770), birçok kalıpla basılan tam renkli nishiki-e baskıları 1765 dolaylarında doğduğunda merkezdeki isimdi. Bu, özel olarak basılmış bir surimonodur; yumuşak, katmanlı renkleri yeniliği gösterir.","Erik çiçekli bir odada iki genç kadın kutu biçimli bir sugoroku tahtasında oynuyor, üçüncüsü ayakta tahtaya bakıyor. Tahtada beyaz ve siyah taşlar dizili; soldaki bir taş oynatıyor, sağdaki tahtaya uzanıyor. Arkadaki sürgülü kapıda şelale ve çamlar resmedilmiş."],"spots":[["Sugoroku tahtası","Beyaz ve siyah taşlı, kutu biçimli bir ban-sugoroku tahtası."],["Soldaki genç kadın","Kâğıt turnalı kimonosuyla bir taş oynatıyor."],["Sağdaki genç kadın","Eğilmiş, tahtaya uzanıyor."],["İzleyen","Ayakta oyuna bakıyor; elinde uzun saplı bir nesne var."],["Erik","Yukarıdan dallarını uzatan beyaz bir erik."],["Resimli kapı","Şelale ve çamlarla bezeli sürgülü kapı."]]},"kota":{"title":"Kota Mihracesi Kishor Singh II, Krishna’ya Brij Rajji olarak tapınırken","artist":"Bilinmiyor","date":"y. 1825","place":"Hindistan (Racastan, Kota)","game":"Pachisi","medium":"Kâğıt üzerine zamklı tempera, gümüş ve altın","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["Küçük Kota prensliğinin hükümdarı (hd. 1819–28), Pushti Marg tarikatının rahibi kılığında, beş alevli bir kandil sunuyor. Sunaktaki küçük mabette, iki eşiyle birlikte Krishna’nın metal tasvirleri duruyor — yalnızca Kota’da tapınılan bir ikon.","Tavandan pek çok cam lamba sarkıyor; sunağa çıkan basamaklarda Krishna’yı ve arkadaşlarını eğlendirecek oyuncaklar ve oyunlar dizili: pirinç filler, gümüş inekler, toplar ve bir pachisi tahtası (müze notu). Kırmızı haç biçimli bez o tahtadır — tanrıya oyuncak olarak sunulmuş pachisi."],"spots":[["Pachisi tahtası","Basamaklardaki kırmızı haç biçimli bez: bir pachisi tahtası."],["Filler","Tahtanın yanında iki pirinç fil."],["Toplar","Üst basamakta altın renkli toplar."],["Krishna","Küçük mabetteki Krishna ve iki eşinin tasvirleri."],["Hükümdar ve kandil","Rahip kılığında beş alevli kandil sunuyor."],["Cam lambalar","Tavandan sarkan çok sayıda cam lamba."]]},"coyote":{"title":"Çakal Oyunu","artist":"José Guadalupe Posada’nın bir takipçisi","date":"Tarihsiz","place":"Meksika","game":"Çakal ve tavuklar (tilki ve kazlar ailesinden)","medium":"Kâğıt üzerine çinko kabartma baskı","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Posada’nın Mexico City’deki halk matbaaları için yaptıkları gibi çinko kabartmayla basılmış, üzerinde oynanan tek yapraklık bir baskı. Üstte “JUEGO DEL COYOTE” (çakal oyunu) yazar; çevrede çakallar kümese saldırıyor, bir adam da birini kovmak için sopa sallıyor. Alttaki şeritte “Ildefonso T. Orellana’nın mülküdür” yazar.","Kurallar alttaki “EXPLICACION”da basılıdır: iki kişi oynar; birinde on beş tavuk, ötekinde tek bir çakal vardır. Tavuklar ileri ya da yana gider ama asla geri dönmez; çakal her yöne gider ve arkası boşsa bir tavuğun üzerinden atlayarak onu yer. Tavuklar çakalı kıstırırsa kazanır. Avrupa’daki tilki ve kazlar ile aynı av oyunudur."],"spots":[["Çakalın yeri","Ortadaki dairede çakal başı: çakal buradan başlar."],["Tavukların yerleri","Tavuk resimli daireler: taşlar buraya dizilir."],["Kurallar","“EXPLICACION”: taşlar, hamleler ve kazanma."],["Başlık","“JUEGO DEL COYOTE” — çakal oyunu."],["Tavuğa saldıran çakal","Sol altta bir çakal bir tavuğa saldırıyor."],["Sopalı adam","Sağ üstte bir adam bir çakala sopa kaldırıyor."]]},"mons":{"title":"Mons (Bergen) Üzerine Tavla, 1709","artist":"Pieter Nolpe (kalıp ve yayımcı)","date":"Kalıp 1623–53; baskı y. 1709","place":"Hollanda (Amsterdam)","game":"Trictrac (tavla ailesinden)","medium":"Asitle oyma, gravür ve dizgi şiir","size":"Kâğıt 35,8 × 18,6 cm (kalıp 12,9 × 17,5 cm)","credit":"","p":["Dört adam bir masada trictrac oynuyor. Müze kaydına göre A–D harfleri Marlborough Dükü, Bavyera Prens Seçicisi, Ouwerkerk Lordu ve Villeroy Dükü’nü gösterir. Müttefiklerin 1709’da Mons’u (Felemenkçede Bergen) Fransızlardan kuşatıp almasını, kentin ortaya konduğu bir tavla oyunu olarak hicveden bir baskıdır. Arka odada (E) İspanya Kralı V. Felipe bir kadınla birliktedir.","Kalıpta yapımcı ve yayımcı olarak Pieter Nolpe’nin imzası var; ama Nolpe 1650’lerin başında öldüğüne göre, 17. yüzyıldan kalma eski bir kalıp harfler ve yeni bir şiir eklenerek yeniden basılmış olmalı. Alttaki şiir, büyük beylerin oyununun hep tiktak ve verkeer (bu aileden iki oyun) olduğunu söyleyerek başlar, sonra her oyuncuyla tek tek alay eder."],"spots":[["Tahta","Masadaki trictrac: ortaya konan bir kent."],["A, Marlborough","Ayakta tahtaya bakıyor — Müttefiklerin İngiliz komutanı."],["B, Bavyera Prens Seçicisi","Şapkasız, sandalyesine gömülmüş."],["C, Ouwerkerk","Tüylü şapkalı — Hollandalı general."],["E, arka oda","Arkadaki yatak odasında bir kadınla V. Felipe."],["Şiir","Altta basılı Felemenkçe şiir; A’dan E’ye oyuncularla alay ediyor."]]},"stembus":{"title":"Sandık: Siyasi Bir Kaz Oyunu","artist":"Johan Michaël Schmidt Crans (baskıcı)","date":"1867","place":"Hollanda","game":"Kaz oyunu (hiciv)","medium":"Taş baskı","size":"66 × 50 cm","credit":"","p":["Kaz oyunu biçiminde hicivli bir baskı. De Nederlandsche Spectator haftalık dergisinin 2 Mart 1867 tarihli 9. sayısıyla, ayrı bir kural yaprağıyla birlikte çıkmıştır (müze kaydı). Karelerde dönemin bakanlarının portreleri var.","Oyun Lahey’deki parlamento binası Binnenhof’ta başlar ve ortada 64. kare “Insulinde”de — Hollanda Doğu Hint Adaları’nın şiirsel adı — biter; orada Cava adasına asılmış bakan Pieter Mijer’in portresi bekler. Mijer sömürgeler bakanlığından Doğu Hint genel valiliğine geçmişti ve bu atama siyasette fırtına koparmıştı. Olağan 63’ten bir fazla olan kare, büyük olasılıkla bu son espri içindir."],"spots":[["Başlangıç","Sol üstteki bina: oyun Lahey’deki Binnenhof’ta başlar."],["Mijer’in portresi","63. kare: Pieter Mijer’in çerçeveli portresi iplerle adaya asılı."],["Insulinde 64","Ortadaki ada ve 64 sayısı: bitiş."],["Sandık","Sağ alttaki “DE STEMBUS” (sandık): başlıktaki kutu."],["Bakanlar","Karelerden dönemin bakanlarının yüzleri bakıyor."],["Horoz","Bir karedeki horoz; neyi alaya aldığı bilinmiyor."]]},"koorai":{"title":"Bir Masa Oyunu Başında Koreliler (Siebold’un Nippon’undan)","artist":"James Erxleben (taşbaskıcı), “Toioske”nin çiziminden","date":"1832–52","place":"Hollanda (Leiden) / Koreliler","game":"Masa oyunu (büyük olasılıkla go)","medium":"Tonlu taşbaskı, elle boyanmış","size":"Kâğıt 38 × 55,5 cm","credit":"F. G. Waller bağışı","p":["Alman doğumlu hekim Philipp Franz von Siebold’un Nagasaki’deki Hollanda ticaret karakolunda (1823–30) gördüklerine dayanarak Leiden’de yayımladığı büyük eser NIPPON’dan bir levha. Sağ üstte “TAB. I”, altta “KOORAI” (Kore) ve Felemenkçe ile Almanca “bir balıkçı ailesi” yazar. Taşa Erxleben çizmiş; levha çizeri “Toioske” olarak anar.","Dört adam yere oturmuş bir tahtanın çevresinde; solda bir kadın küçük bir çocuğu elinden tutuyor, sağda uzun bir sopa ve kese tutan bir adam ayakta. Önde yerde geniş kenarlı siyah bir şapka (gat) var. Tahtada ızgara ve yuvarlak taşlar görülüyor; büyük olasılıkla go (Korecede baduk), ama kayıtta yalnızca “bir masa oyunu” denir."],"spots":[["Tahta","Izgara ve yuvarlak taşlar: büyük olasılıkla bir go oyunu."],["Siyah şapka","Yerde geniş kenarlı siyah bir şapka (gat)."],["Anne ve çocuk","Elinde çocukla oyunu izleyen kadın."],["Ayaktaki adam","Uzun sopa ve keseyle ayakta duran adam."],["Eğilen adam","Mavi ceketli, tahtaya bakıyor."],["Başlık","“KOORAI” (Kore) ve Felemenkçe ile Almanca “bir balıkçı ailesi”."]]},"cairo":{"title":"Bir Kahvenin Önünde Masa Oyunu Çevresindekiler (Kahire)","artist":"Délié & Béchard (Hippolyte Délié ve Émile Béchard)","date":"y. 1869–90","place":"Mısır (Kahire)","game":"Masa oyunu (büyük olasılıkla satranç)","medium":"Albümin baskı","size":"10,8 × 16,4 cm","credit":"","p":["Kahire’de stüdyo işleten Fransız fotoğrafçılar Hippolyte Délié ve Émile Béchard’ın bir fotoğrafı. Kartonda stüdyonun adı, “Ezbekiye Bahçesi yanında”, ve “Kahire (Mısır)” basılıdır. Mısır’a gelen yolcular bu tür fotoğrafları hatıra olarak alırdı.","Kafesli pencereli bir dükkânın önünde yere oturmuş adamlar alçak bir sehpadaki tahtanın çevresinde. Tahtada uzun taşlar duruyor; büyük olasılıkla satranç (Arapçada şatranç), ama müze kaydında yalnızca “bir masa oyunu” denir. Uzun pozlama için herkes kıpırdamadan duruyor."],"spots":[["Tahta ve taşlar","Alçak sehpadaki tahta, uzun taşlarla: büyük olasılıkla satranç."],["Kafesli pencere","Ahşap kafesli pencere; eski Kahire evlerine özgü."],["Sopalı adam","Elinde sopa, oturmuş oyunu izliyor."],["Sepet","Yerde örme bir sepet."],["İzleyen çocuk","Arkadan tahtaya bakan bir çocuk."],["Stüdyonun adı","Kartondaki “AU JARDIN DE L’ESBÉKIEH” ve “CAIRE (EGYPTE)”."]]},"vanmour":{"title":"İskambil Oynayan Ermeni Topluluğu","artist":"Jean-Baptiste Vanmour","date":"y. 1720–37","place":"Osmanlı İmparatorluğu (İstanbul)","game":"İskambil","medium":"Tuval üzerine yağlıboya","size":"44,5 × 58,5 cm","credit":"","p":["Flandre doğumlu Vanmour 1699’da Fransız elçisiyle İstanbul’a geldi ve ölene dek bu şehirde yaşayarak saray törenlerini ve halkın gündelik hayatını resmetti. Müze, erkeklerin giysilerinden Ermeni oldukları anlaşıldığını belirtir.","Büyük bir mumun ışığında kadınlı erkekli bir grup, kırmızı örtülü bir masanın çevresinde iskambil oynuyor. Masada dağıtılmış kâğıtlar var, bazıları elindeki kâğıtlara bakıyor. Sol köşede yaşlı bir kadın iplik eğiriyor. Kayıtta hangi oyun olduğu yazmıyor."],"spots":[["Masadaki kâğıtlar","Kırmızı örtülü masadaki iskambil kâğıtları."],["Büyük mum","Tüm topluluğu tek bir mum aydınlatıyor."],["İplik eğiren yaşlı kadın","Sol köşede iplik eğiren yaşlı kadın."],["Elindeki kâğıtlara bakan kadın","En sağda kâğıtlarına bakan bir kadın."],["Kürklü adam","Kürk kenarlı kaftanlı adam; giysileri Ermeni olduklarını gösterir."],["Masaya uzanan","Elinde kâğıtlarla masaya eğilen biri."]]},"algiers":{"title":"Masa Oyunu Oynayan Üç Adam (Cezayir)","artist":"Anonim","date":"1851–1900","place":"Cezayir (Cezayir kenti)","game":"Masa oyunu (büyük olasılıkla tavla)","medium":"Albümin baskı","size":"14,0 × 10,0 cm","credit":"","p":["Görüntünün altına el yazısıyla “Alger” (Cezayir) yazılmış, fotoğrafçısı bilinmeyen bir fotoğraf. Düz bir fonun önüne sandalyeler ve küçük bir masa konduğundan büyük olasılıkla stüdyoda çekilmiştir. Kuzey Afrikalıları gösteren bu tür fotoğrafları yolcular ve koleksiyoncular alırdı.","İki adam kenarlı bir tahtanın iki yanında karşılıklı oturuyor; sağdaki bir pula uzanıyor. Tahtada üst üste yuvarlak pullar var; büyük olasılıkla tavla, ama kayıtta yalnızca “bir masa oyunu” denir. Öndeki küçük masada kahve takımı duruyor."],"spots":[["Tahta ve pullar","Kenarlı bir tahta, üzerinde üst üste yuvarlak pullar."],["Ayaktaki seyirci","Belinde kuşak, arkada ayakta oyunu izleyen adam."],["Soldaki yaşlı","Başı sarılı, düşünceli yaşlı adam."],["Sağdaki adam","Başında beyaz örtü, tahtaya eğilmiş adam."],["Kahve takımı","Oymalı küçük masada tepsi ve fincanlar."],["Pulu süren el","Sağdaki oyuncunun pula uzanan eli."]]},"circo":{"title":"Sirk Oyunu (Juego del Circo)","artist":"Manuel Manilla (?)","date":"Tarihsiz","place":"Meksika","game":"İki zarla oynanan bahis oyunu","medium":"Kabartma baskı (uç ağaç ya da fotoğrafik kabartma) ten rengi kâğıt üzerine","size":"26,2 × 35,0 cm","credit":"","p":["Soru işaretiyle Meksikalı baskıcı Manuel Manilla’ya atfedilen bir oyun kâğıdı. Sağ altta satıcısı olan “El Teatro” baskıevinin adı ve adresi yazılı. Bu tür ucuz baskılar sokakta satılır ve anlaşılan olduğu gibi üzerinde oynanırdı.","Ortada bir sirk çadırı, çevresinde atlı akrobatlar, insan kulesi, güçlü adam ve başkaları; her birinde 2’den 12’ye bir sayı var. Sol üstteki “Açıklama”ya göre herkes, çocuklar da oynayabilir: iki zar atılır, gelen sayının karesine bahis konur ya da orada olan bahis alınır. 12 atan her şeyi alır."],"spots":[["Sirk çadırı","“JUEGO DEL CIRCO” başlığı ve 12 numaralı kare olan çadır."],["Oyun kuralları","“ESPLICACION” başlıklı kurallar."],["Atlı akrobat","Dörtnala koşan atın sırtında dansçı: 6 numara."],["İnsan kulesi","Birinin omzunda duran adam: 4 numara."],["Güçlü adam","Top biçimli bir ağırlık kaldıran adam: 8 numara."],["Baskıevinin adı","“De venta, Estampería ‘El Teatro’” ve adres."]]},"loteria":{"title":"Lotería Resimli Kartları","artist":"José Guadalupe Posada","date":"1880–1913","place":"Meksika","game":"Lotería (resim çağırma oyunu)","medium":"Kabartma baskı (uç ağaç ya da fotoğrafik kabartma) ten rengi kâğıt üzerine","size":"30,0 × 40,0 cm","credit":"","p":["Meksikalı baskıcı Posada, haber, şarkı ve oyun taşıyan ucuz basmalar çıkaran Mexico City’li yayıncı Antonio Vanegas Arroyo için sayısız resim çizdi. Bu kâğıtta da “JUEGO DE LOTERIA” başlığı ve Vanegas Arroyo’nun adı basılı.","Kâğıdı adı yazılı otuz sekiz küçük resim dolduruyor: yıldız, ay, akrep, şeytan, kurukafa, horoz, matbaa ve daha fazlası. Tombalaya benzeyen lotería’da çağıran kişi kart çekip resmin adını söyler, oyuncular kendi levhalarındaki o resmi fasulye gibi şeylerle işaretler. Kâğıt büyük olasılıkla kesilip kart yapılırdı."],"spots":[["Başlık ve yayıncı","“JUEGO DE LOTERIA” ve Vanegas Arroyo’nun dükkânının adı."],["Yıldız","“ESTRELLA”, sol üstteki ilk resim."],["Ay","“LUNA”, yüzlü bir hilal."],["Ölüm","“MUERTE”: tırpanlı, kaval çalan bir iskelet."],["Tlachiquero","“TLACHIQUERO”: agav özü toplayan adam."],["Matbaa","“IMPRENTA”: preste çalışan işçiler; bu tür kâğıtların basıldığı yer."]]},"jeupol":{"title":"“Jeu polonais”, yani Dama Tahtası","artist":"Anonim","date":"1833–1900","place":"Belçika ya da Hollanda","game":"Dama (10 × 10 tahta)","medium":"Ağaç baskı, matbaa harfli metin","size":"32,2 × 39,6 cm","credit":"","p":["Üstünde Fransızca ve Felemenkçe “JEU POLONAIS OF DAMSPEL” başlığı basılı tek yaprak. “Jeu polonais” (Leh oyunu), Fransa’da 10 × 10 tahtada oynanan damaya verilen addı. Sağ üstte yayıncının sıra numarası “n. 106” var.","Müze kaydında dendiği gibi 50 beyaz, 50 siyah, toplam 100 kare var; sağda ve solda süslü kenarlar. Taşlar basılmamış; büyük olasılıkla fasulye ya da düğmeyle, kâğıdın üstünde oynanan ucuz bir tahtaydı. Kâğıtta katlama izleri duruyor."],"spots":[["Başlık","“JEU POLONAIS OF DAMSPEL” yazısı."],["Sıra numarası","Yayıncı numarası “n. 106”."],["Sol kenar","Yuvarlak çiçek motiflerinden bir sütun."],["Sağ kenar","Öbür yanda aynı desen."],["Yüz kare","10 × 10 tahta; koyu kareler ince çizgilerle taranmış."],["Katlama izi","Kâğıtta kalan kat izi; belki katlanıp taşınıyordu."]]},"dkaart":{"title":"Kesilip Kullanılacak Domino ve İskambil","artist":"Anonim (Brepols)","date":"1800–1833","place":"Belçika (Turnhout)","game":"Domino ve iskambil","medium":"Mavi, kırmızı ve sarıyla boyanmış ağaç baskı; matbaa harfli metin","size":"34,3 × 41,9 cm","credit":"","p":["Müze kaydına göre bu kâğıtta kesilip kullanılacak 32 iskambil kâğıdı ve 28 domino taşı basılı. Yayıncı Brepols’un listesinde 114 numaradır; altta satıcı “D. Pouwels, Bergen-op-Zoom” yazar. Başlık Felemenkçe ve Fransızcadır.","Solda boş-boştan altı-altıya 28 taş üçgen biçiminde dizilmiş. Sağda her renkten yediden ona ve resimli kâğıtlarla asların oluşturduğu 32 kâğıt var: piket gibi oyunlar için bir deste. Kimse kesmediği için baskıdan çıktığı hâliyle görüyoruz."],"spots":[["Başlık","“DOMINO EN KAARTSPEL” yazısı."],["Boş-boş","Üçgenin tepesi: hiç noktası olmayan taş."],["Altı-altı","En büyük taş, en alt sıranın sağ ucunda."],["Maça ası","Sol sütunda yukarıdan ikinci kâğıt."],["Resimli kâğıt","Kırmızı, mavi ve sarıyla boyanmış bir papaz."],["Satıcı","Alttaki “D. POUWELS, Bergen-op-Zoom”."]]},"apen":{"title":"Tavla Oynayan İki Maymun","artist":"Quirin Boel, David Teniers’in tasarımından","date":"1635–1690","place":"Flandre","game":"Triktrak (tavlanın bir türü)","medium":"Asitle oyma baskı","size":"11,0 × 14,5 cm","credit":"","p":["Maymunların insan uğraşlarını canlandırdığı, bir başlık ve altı levhadan oluşan dizinin bir parçası. Sol altta “D. Teniers tasarladı ve yayımladı, imtiyazla” yazar; Quirin Boel, Flaman ressam Teniers’in tasarımını baskıya aktarmıştır.","Müze kaydının anlattığı gibi iki maymun yere oturmuş, aralarında bir triktrak tahtası var. Soldaki kadehten şarap içiyor, sağdaki horoz tüylü şapkasıyla bir pula uzanıyor. Büyük olasılıkla içkiye ve kumara dalmış insanlarla alay ediyor."],"spots":[["Tahta","Yerdeki katlanır triktrak tahtası; hanelerle pullar görülüyor."],["Soldaki maymun","Ceketli, tahtanın önünde oturan maymun."],["Şarap kadehi","Soldaki maymunun kaldırdığı kadeh."],["Tüylü şapka","Sağdaki maymunun şapkasındaki horoz tüyü."],["Testi","Soldaki maymunun ayağının dibindeki testi."],["Yazı","“D Teniers in et excud cum privilegio”."]]},"dstereo":{"title":"Masada Domino Oynayan Adamlar (Stereo Fotoğraf)","artist":"Anonim","date":"1850–1880","place":"Bilinmiyor (Felemenkçe yazı)","game":"Domino","medium":"Albümin baskı (stereo fotoğraf)","size":"8,5 × 17,0 cm","credit":"","p":["Bir stereo fotoğraf: yan yana neredeyse aynı iki fotoğraf. Stereoskopla bakılınca derinlikli tek bir sahneye dönüşür. Sol kenarda el yazısıyla “Het dominospel” (domino oyunu) yazar.","Bir binanın önünde güneşe bir masa konmuş; gömlekli adamlar taşlarını tutuyor. İkisi ayakta oyunu izliyor; sağdaki beyaz takke giymiş. Herkesin kıpırdamaması gerektiğinden sahne büyük olasılıkla fotoğraf için kurulmuştur."],"spots":[["Masadaki taşlar","Elde kapalı tutulan domino taşları."],["Beyaz takkeli adam","Sağda oturan, taşlarını tutan adam."],["Boyun atkılı adam","Ayakta, oyuna yukarıdan bakan adam."],["Soldaki adam","Dirseğine dayanıp taşlarına bakan genç."],["Yazı","Sol kenardaki “Het dominospel.”."],["İkinci görüntü","Biraz kaydırılmış noktadan çekilen sağdaki fotoğraf; ikisi birlikte derinlik verir."]]},"gojo":{"title":"Go Oynayan İki Kadın","artist":"Anonim","date":"1870–1891","place":"Japonya","game":"Büyük olasılıkla go","medium":"Elle boyanmış albümin baskı","size":"9,0 × 13,5 cm","credit":"","p":["Siyah beyaz bir fotoğrafın fırçayla elle boyanmış hâli. Bu tür fotoğraflar Yokohama gibi yerlerdeki stüdyolarda yabancılara hatıra olarak yapılırdı. Bu fotoğraf Manila’ya bir yolculuğun albümüne yapıştırılmıştı.","Bir niş süslemesi ve paravanın önünde iki kadın ayaklı bir tahtanın iki yanında oturuyor; soldaki bir taş koyuyor. Tahtada beyaz ve siyah taşlar var; büyük olasılıkla go, ama müze kaydında “bir masa oyunu” denir. Öndeki tepside tatlılar ve kaplar duruyor."],"spots":[["Tahta ve taşlar","Ayaklı kalın bir tahta, beyaz ve siyah taşlar."],["Taş koyan el","Soldaki kadın bir taş koyuyor."],["Soldaki kadın","Bize dönmüş; kuşağı büyük bir fiyonkla bağlı."],["Sağdaki kadın","Çizgili kimonolu, eli tahtanın yanında."],["Tepsi ve kaplar","Öndeki tatlılar ve fincanlar."],["Çiçekler","Arkada ayaklı bir sehpada çiçek vazosu."]]},"meade":{"title":"Satranç Oynayan İki Adam","artist":"Charles Richard Meade ve Henry William Mathew Meade","date":"1852","place":"Amerika Birleşik Devletleri","game":"Satranç","medium":"Dagerotip","size":"6,9 × 8,3 cm","credit":"","p":["İngiltere doğumlu, Amerika’da çalışan Meade kardeşlerin stüdyosundan bir dagerotip. Dagerotip görüntüyü doğrudan gümüş kaplı bir bakır levhada oluşturur; bu yüzden her biri tektir ve çoğaltılamaz. Bu, yaldızlı bir paspartunun ardında küçük bir deri kutuda durur.","İki genç adam küçük bir sehpadaki satranç tahtasının iki yanında; soldaki parmaklarını bir taşa koymuş. Sağdaki elini göğsüne koymuş, tahtayı inceliyor. Uzun süre kıpırdamamaları gerektiğinden hamle büyük olasılıkla poz içindir."],"spots":[["Satranç tahtası","Çiçekli kumaş örtülü sehpada tahta ve beyaz taşlar."],["Soldaki adam","Parmakları bir taşta."],["Sağdaki adam","Tahtaya bakıyor."],["Göğüsteki el","Sağdaki oyuncunun düşünceli eli."],["Örtü","Çiçekli kumaşla örtülü küçük sehpa."],["Yaldızlı paspartu","Levhayı koruyan yaldızlı çerçeve ve kutu."]]},"weiqidai":{"title":"Weiqi Oynayan Taocu Ölümsüzlerle Manzara","artist":"Dai Jin’e atfedilir","date":"Ming hanedanı, 15.–16. yüzyıl","place":"Çin","game":"Weiqi (go)","medium":"Asma rulo; ipek üzerine mürekkep ve renk","size":"175,2 × 106,7 cm","credit":"","p":["Ming ressamı Dai Jin’e (y. 1388–1462) atfedilen büyük bir asma rulo. Zhejiang’lı olan ve güçlü manzaralarıyla tanınan Dai Jin, sonradan Zhe okulunun kurucusu sayıldı. Yükselen uçurumların ve büyük bir ağacın altında insanlar küçük çizilmiş.","Gölgede yerde iki ölümsüz, çizgili bir weiqi tahtasının iki yanında oturuyor; yanlarında bir meyve tabağı ve bir kap var. Solda çömelen figür, dağda ölümsüzlerin oyununu izlerken baltasının sapı çürüyen oduncunun hikâyesini (Lanke efsanesi) hatırlatır; ama müzenin başlığı yalnızca weiqi oynayan Taocu ölümsüzlerden söz eder."],"spots":[["Tahta","İnce ızgaralı, kenarlı bir tahta."],["Sakallı ölümsüz","Uzun sakallı, rahatça oturan bir ölümsüz."],["Mavi başlıklı ölümsüz","Tahtaya eğilmiş; dizinin yanında taş kâsesi var."],["Çömelen figür","Soldan tahtaya bakıyor; belki de efsanedeki oduncu."],["Meyve ve kap","Tahtanın ötesinde tabak ve küp."],["İmza ve mühürler","Sağ üstte bir imza ve iki kırmızı mühür."]]},"reise":{"title":"Dünya Çevresinde Yolculuk, Suda ve Karada","artist":"Anonim","date":"19. yüzyıl","place":"Büyük olasılıkla Almanca konuşulan topraklar","game":"Tek zarla bahisli yarış oyunu","medium":"Taş baskı","size":"42,5 × 33,7 cm","credit":"","p":["Almanca başlığı “Dünya çevresinde yolculuk, suda ve karada: yeni ve eğlenceli bir zar oyunu” olan bir oyun kâğıdı. Yuvarlak tahtada 1’den 41’e kadar kareler var; balon, yelkenliler, vapur, lokomotif, çeşitli milletlerden insanlar ve başka resimler içeriyor. Sağ altta “No. 107” numarası var.","Altta kurallar Almanca, İngilizce, Felemenkçe ve Fransızca basılı. Herkes önce ortak “yol kesesi”ne 15 mark öder, sonra sırayla tek zar atıp işaretini ilerletir. Büyük bir resme gelen 2 mark kazanır, resimsiz bir sayı 2 mark ceza demektir, 41’e varan da kalanın hepsini alır."],"spots":[["41: posta arabası","Ortadaki hedef: yolcular ve arabacıyla bir posta arabası."],["1: İngiliz","Başlangıç karesi, silindir şapkalı “Engländer”."],["Balon","Gökte bir balonun olduğu kare."],["Yelkenli","Tüm yelkenleri açık bir gemi."],["Lokomotif","Duman çıkaran buharlı lokomotif."],["Kurallar","Dört dilde basılmış kurallar."]]},"huchten":{"title":"Hayatına Zar Atmak","artist":"Jan van Huchtenburg","date":"1680–1720","place":"Hollanda","game":"Zar","medium":"Tuval üzerine yağlıboya","size":"67,5 × 76,0 cm","credit":"","p":["Savaş sahneleriyle tanınan Hollandalı ressam Jan van Huchtenburg’un (1647–1733) eseri; sol altta imzası var. Müzedeki adı “Hayat için zar oyunu”. Bir kalenin dışında iki tutsak bir davulun üstünde zar atıyor, çevrelerinde subaylar ve askerler var.","Sağ arkada bir darağacı yükseliyor, solda kale duvarından askerler izliyor. Büyük olasılıkla mahkûm askerlerin hangisinin idam edileceğini zarla kura çekerek belirlediği an. Tutsaklardan biri davulu gösteriyor, öbürü diz çökmüş atışa bakıyor."],"spots":[["Davul ve zarlar","Zarların atıldığı masa yerine davul."],["Gösteren tutsak","Ayakta, davulu işaret ediyor."],["Diz çökmüş tutsak","Beyaz gömlekle davula eğilmiş."],["Atlı subay","Şapkalı, atının üstünden bakıyor."],["Darağacı","Sağ üstteki darağacı."],["Duvardaki askerler","Kale duvarından izleyen askerler."]]},"vertu":{"title":"Erdem Oyunu (Spel der Deugd)","artist":"Jan Gerritsz. Visser (tasarım J. Voorman)","date":"1798","place":"Hollanda","game":"İki zarla bahis oyunu","medium":"Gravür, asitle oyma ve matbaa","size":"56,9 × 38,0 cm","credit":"","p":["Felemenkçe ve Fransızca “Erdem Oyunu” başlıklı büyük bir oyun kâğıdı. Sütunlu bir tapınağın ortasında Erdem oturuyor; solda Bolluk, sağda Yoksulluk duruyor. Sütunlarda İçtenlik, Şükran, Sevgi gibi erdemlerin madalyonları, aşağıdaki kaidelerde Cimrilik, Kibir, Tembellik gibi kötülükler var.","Alttaki kurallara göre iki zarla ya da kura çekerek oynanır. Zarla oynarken herkes toplam 63 koyar ve güneşin yönünde sırayla atar. Her atış bir erdem ya da kötülüğe karşılık gelir: düşeş “Erdem” potun hepsini alır, hepyek “Kötülük” sekiz öder. Her resmin altındaki “T” alınanı, “B” ödeneni gösterir."],"spots":[["Başlık","Alınlıktaki “SPEL DER DEUGD”."],["Erdem","Ortada tahtta oturan Erdem; düşeş potu alır."],["Bolluk","Bolluk boynuzuyla Bolluk."],["Kötülük","Hepyek, Kötülük: kadeh kaldıran bir çocuk."],["Cimrilik","Kaidedeki Cimrilik; “B” ve zarlar ödemeyi gösterir."],["Kurallar","Altta sıkışık basılmış kurallar."]]},"charros":{"title":"Kaçakçı Çarrolar: Bir Zar Oyunu","artist":"José Guadalupe Posada","date":"Tarihsiz","place":"Meksika","game":"Üç zarlı yarış oyunu","medium":"Taş baskı","size":"29,9 × 40,4 cm","credit":"","p":["Posada’nın resimlediği, “LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS” (Kaçakçı Çarrolar / Zar oyunu) başlıklı bir yarış oyunu. Altta “A. Vanegas Arroyo Matbaası, Meksika” yazılı, sağ altta Posada’nın imzası var. Çarrolar Meksikalı atlılardır; köşelerde sombrerolarıyla dörtnala gidiyorlar.","Halatla çevrili yuvarlak kareler tahtanın her yanında kıvrılıyor; içlerinde hayvanlar, insanlar, tren ve başka resimler var. Sağ üstteki “Açıklama” üç zarla oynandığını söyler. İlk atışta üç tane bir gelirse kazanılır; kurukafaya düşen kaybeder; geyikte kasadan alınır, haydutlarda ödenir, aslanda biri gelene dek beklenir."],"spots":[["Başlık","“LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS”."],["Açıklama","“EXPLICACION” başlıklı kurallar."],["Oyuncular","Sol altta masa çevresinde tahtada oynayanlar."],["Zarlar","Tahtanın ortasında çizilmiş üç zar."],["Atlı çarro","Kement savuran, dörtnala giden çarro."],["Matbaa","“IMPRENTA DE A. VANEGAS ARROYO, MÉXICO”."]]},"snuffwq":{"title":"Weiqi Oynayanların Resmedildiği Enfiye Şişesi","artist":"Çin","date":"Qing hanedanı, Daoguang mührü ve dönemi (1820–50)","place":"Çin","game":"Weiqi (go)","medium":"Sır üstü emaye boyalı porselen","size":"Yükseklik 5,7 cm","credit":"","p":["Qing Çin’inde toz tütün taşımak için kullanılan küçük bir şişe. Müze kaydına göre Daoguang döneminin mührünü taşır ve 1820–50 tarihlidir. Altı santim kadar yüksekliğindeki beyaz porselen gövdeye emayelerle dağ manzarası ve figürler boyanmış.","Mağara gibi bir kayanın yanında iki yaşlı adam, mavi bir sehpadaki weiqi tahtasının iki yanında oturuyor; soldaki taş koymak üzere. Arkasında elinde asa olan bir çocuk izliyor. Konu büyük olasılıkla ölümsüzlerin oyununu izleyen oduncu hikâyesini hatırlatır."],"spots":[["Tahta","Mavi sehpada ince ızgaralı bir tahta."],["Sakallı yaşlı","Mor giysili, tahtaya uzanıyor."],["Karşıdaki yaşlı","Sağda oturmuş, elini kaldırmış."],["Asalı çocuk","Arkadan izliyor."],["Mağara","Arkadaki mağara gibi kaya."],["Tıpa","Yeşil bir tıpa."]]},"ostade":{"title":"Meyhanede Triktrak Oynayanlar","artist":"Adriaen van Ostade","date":"1653","place":"Hollanda (Haarlem)","game":"Triktrak (tavlanın bir türü)","medium":"Asitle oyma baskı","size":"8,5 × 7,4 cm","credit":"","p":["Köylü sahneleriyle tanınan Haarlemli ressam Ostade’nin avuç içi büyüklüğünde bir baskısı; altta “A. ostade” imzası var. Karanlık bir meyhanede kurşun çerçeveli pencereden gelen ışık insanları aydınlatıyor.","Soldaki masada iki adam triktrak tahtasının başında karşılıklı oturuyor, üçüncüsü arkadan bakıyor. Sağda bir adam elinde kupayla duvara yaslanmış. Yerde büyük bir testi yatıyor; meyhanede tembel bir öğleden sonra gibi."],"spots":[["Tahta","Masadaki triktrak tahtası."],["Soldaki oyuncu","Şapkalı, tahtaya dönük adam."],["Sağdaki oyuncu","Tahtaya eğilmiş adam."],["Bakan adam","Arkada ayakta izleyen adam."],["Dinlenen adam","Duvar dibinde, elinde kupa."],["Kurşun çerçeveli pencere","Işığın girdiği baklava camlı pencere."]]},"lenain":{"title":"Zar Oyuncuları","artist":"Mathieu Le Nain’in izleyicisi","date":"1630–1680","place":"Fransa","game":"Zar","medium":"Tuval üzerine yağlıboya","size":"92,8 × 119,7 cm","credit":"","p":["Fransız Le Nain kardeşlerin en küçüğü Mathieu’nün üslubunu izleyen bir ressamın eseri. Müzeye göre benzer bir kompozisyonun Gabriel de Saint-Aubin’ce yapılmış bir taslağı Paris’teki Ulusal Kütüphane’de.","Açık havada küçük yuvarlak bir masanın çevresinde üç adam zar atıyor; iki kişi izliyor, soldaki bir şişeye sarılmış. Sağda iki ince tazı, açıklığın ötesinde geniş bir manzara var. Masadaki küçük beyaz şeyler zarlar."],"spots":[["Masadaki zarlar","Yuvarlak masada zarlar."],["Açık renk şapkalı adam","Oturmuş, atışa bakmak için elini uzatıyor."],["Siyahlı adam","Elini beline koymuş genç adam."],["Arkadaki oğlan","Masanın arkasından oyunu izliyor."],["Şişeli adam","Solda bize gülümsüyor."],["İki tazı","Sağdaki ince köpekler."]]},"tunisie":{"title":"Bir Arap Kahvesinin Önünde Kâğıt Oyunu (Anvers Dünya Fuarı, Tunus Bölümü)","artist":"Anonim (baskı Ch. Bernhoeft)","date":"1894","place":"Belçika (Anvers)","game":"İskambil","medium":"Kolotipi","size":"15,4 × 21,6 cm","credit":"","p":["1894 Anvers Dünya Fuarı’nı gösteren 49 levhalık bir dizinin parçası; üstte “EXPOSITION UNIVERSELLE D’ANVERS 1894”, altta “Tunus. Bir Arap kahvesinin önünde kâğıt oyunu” yazılı. Baskısını Lüksemburg saray fotoğrafçısı Bernhoeft yapmıştır.","Fuarın Tunus bölümü için kubbeli ve kuleli olarak yapılmış bir meydanda çekilmiş. Tunus giysileri içindeki adamlar çini kaplı küçük masalarda iskambil oynuyor; biri nargile içiyor, yakında fincan tepsisi var. Sağda takım elbiseli ziyaretçiler oturuyor; büyük olasılıkla uzak bir ülkenin yaşamını gösteren bir sergiydi."],"spots":[["Oyun masası","Çini kaplı küçük masada kâğıt tutan adamlar."],["Nargile","Soldaki adamın ağzındaki nargile marpucu."],["Takım elbiseli ziyaretçiler","Sağda oturan, büyük olasılıkla fuar ziyaretçisi adamlar."],["Fincan tepsisi","Masanın altındaki küçük fincanlar."],["Kubbeler ve kule","Fuar için yapılmış Tunus üslubu yapılar."],["Altyazı","“TUNISIE” ve “PARTIE DE CARTES DEVANT UN CAFÉ ARABE”."]]},"laghouat":{"title":"Lagvat Civarından Kaidler","artist":"Anonim","date":"1880–1890","place":"Cezayir (Lagvat civarı)","game":"Büyük olasılıkla domino","medium":"Albümin baskı","size":"20,9 × 27,0 cm","credit":"","p":["“Cezayir tipleri. Lagvat civarından kaidler” başlıklı, bir albüme yapıştırılmış ve “239” numarası basılmış bir fotoğraf. Kaid, Fransız yönetimindeki Cezayir’de yerel önderlerin unvanıydı.","Beyaz giysili adamlar kerpiç bir duvarın önünde hasıra oturmuş, alçak bir masaya uzun taşlar diziyor. Dizilişinden büyük olasılıkla domino, ama müze kaydında yalnızca “bir oyun” denir. Önde bir çay tepsisi ve çıkarılmış pabuçlar var."],"spots":[["Alçak masadaki taşlar","Masada sıraya dizilmiş uzun taşlar."],["Çay tepsisi","Öndeki tepside bardaklar ve demlik."],["Pabuçlar","Hasırın yanına bırakılmış ayakkabılar."],["Ayaktaki kişi","Duvarın dibinde durup bakan biri."],["Kerpiç duvar","Arkadaki pürüzlü toprak duvar."],["Hasır","Adamların oturduğu örme hasır."]]},"hangong":{"title":"Saray Hanımları (Han Sarayında Bahar Sabahı), ayrıntı","artist":"Qiu Ying’den kopya","date":"Qing hanedanı (1644–1911)","place":"Çin","game":"Weiqi (go)","medium":"Yatay rulo; ipek üzerine mürekkep ve renk","size":"36,2 × 454,4 cm (rulonun tamamı)","credit":"","p":["Ming ressamı Qiu Ying’in (1494–1552) kompozisyonundan Qing döneminde yapılmış, dört buçuk metreyi aşan bir yatay rulonun bir bölümü. Bahar günü bir sarayda saray hanımları, kızlar ve hizmetçiler salıncakta sallanıyor, oyun oynuyor, şakayıklara bakıyor, müzik yapıyor, qin çalıyor, papağanı ve balıkları besliyor.","Bu sahnede bir korkuluğun ardında iki kadın bir weiqi tahtasının iki yanında oturuyor, ötekiler eğilip bakıyor. Önde nilüfer biçimli bir kapta bir bilgin taşı duruyor; hizmetçiler çalgı ve bohça taşıyor. Müzenin dediği gibi rulo, sarayın iç bölümlerinde yaşayan kadınların hayatını idealleştirir."],"spots":[["Tahta","Korkuluğun ardında masadaki weiqi tahtası."],["Taş koyan kadın","Tahtaya uzanan açık mor giysili kadın."],["İzleyenler","Oyuna eğilen kadınlar."],["Yelpazeli hanım","Sütunların arasında yuvarlak yelpaze tutan kadın."],["Bilgin taşı","Nilüfer biçimli kaptaki mavi taş."],["Çalgılı hizmetçi","Büyük olasılıkla bir pipa taşıyan hizmetçi."]]},"homerbg":{"title":"Tavla","artist":"Winslow Homer","date":"y. 1877","place":"Amerika Birleşik Devletleri","game":"Tavla","medium":"Uç ağaç baskı","size":"","credit":"","p":["Amerikalı ressam Winslow Homer’ın (1836–1910) çizimine göre yapılmış bir uç ağaç baskı. Homer gençliğinde bu tür baskılar için pek çok resimleme yaptı. Altta “396.—BACKGAMMON.—WINSLOW HOMER.” basılı; büyük olasılıkla bir kitap ya da dergideki numaralı bir dizinin yaprağı.","Süslü bir kanepede karşılıklı oturan iki kadın, dizlerine koydukları bir tahtada tavla oynuyor. Tahtanın üstünde beyaz, yuvarlak bir şey duruyor ama ne olduğu belli değil. Uzun eteklerin kıvrımları ve kanepenin kıvrık kolları ince çizgilerle oyulmuş."],"spots":[["Tahta","İki kadının dizlerine konmuş tahta."],["Soldaki kadın","Saçı toplu, tahtaya uzanıyor."],["Sağdaki kadın","Öne eğilip tahtaya bakıyor."],["Kanepe kolu","Kıvrık biçimli kol."],["Etekler","İnce çizgilerle oyulmuş uzun etek kıvrımları."],["Altyazı","Alttaki “396.—BACKGAMMON.—WINSLOW HOMER.”."]]},"chessst":{"title":"Satranç Oynayan Kadın ve Adam (Stereo Fotoğraf)","artist":"Anonim","date":"1852–1858","place":"Bilinmiyor","game":"Satranç","medium":"Stereo fotoğraf, boyalı","size":"8,3 × 16,5 cm","credit":"","p":["İngilizcede “The Chess Players” diye bilinen, stereo fotoğraf olarak yapıştırılmış bir çift görüntü. Stereoskopla bakınca tahta ve taşlar derinlikli görünür. Siyah beyaz görüntünün üstüne kırmızı perdeye ve sarı elbiseye renk verilmiş.","Sarı giysili kadın elini bir taşa koymuş, karşısındaki arkası dönük adam tahtayı inceliyor. Kırmızı ve beyaz taşlar oyunun ortasında, ama sahne büyük olasılıkla stüdyoda kurulmuştur. Bu tür ev sahnelerinin stereo fotoğrafları 19. yüzyıl ortasında çok satılırdı."],"spots":[["Tahta ve taşlar","Damalı tahtada kırmızı ve beyaz taşlar."],["Hamle yapan el","Kadının bir taştaki eli."],["Kadın","Beyaz yakalı sarı elbiseli, tahtaya bakıyor."],["Adam","Arkası bize dönük oturuyor."],["Kırmızı perde","Arkadaki boyanmış perde."],["İkinci görüntü","Sağdaki görünüm; stereoskopta çift derinlik kazanır."]]},"corrida":{"title":"Boğa Güreşi Zar Oyunu (Corrida de Toros)","artist":"José Guadalupe Posada","date":"1898","place":"Meksika","game":"İki zarlı, bahisli yarış oyunu","medium":"Velen kâğıt üzerine fotoğrafik kabartma baskı","size":"40,4 × 30,0 cm","credit":"","p":["Posada’nın resimlediği, “CORRIDA DE TOROS” (Boğa güreşi) başlıklı bir yarış oyunu. Kareler sarmal biçiminde dizilir ve dıştaki 1’den merkeze doğru boğa güreşinin hareketlerini ve anlarını sırayla gösterir. Ortada bir arena, altta Antonio Vanegas Arroyo matbaasının adı var.","Alttaki “Açıklama”ya göre iki ya da daha çok kişi bahis koyar ve iki zar atarak ilerler. 5, “sırıkla atlama”, 10’a götürür; 12, “pikadoru boynuzlama”, ödetir ve sıra kaybettirir; 28, “göğüs pası”, baştan başlatır. 32’ye, “boğayı sürüklemek”e varan tüm bahisleri alır."],"spots":[["Başlık","“CORRIDA DE TOROS” yazısı."],["Arena","Sarmalın ortasındaki arena binası."],["1 numaralı kare","Sarmalın ağzındaki başlangıç karesi."],["Boğa başı","Sağ üstte boynuzlu bir boğa başı."],["Matador","Sol altta bir matador portresi."],["Açıklama","Altta basılı “EXPLICACION”."]]},"ambrocards":{"title":"İskambil Oynayan Üç Adam","artist":"Bilinmeyen yapımcı (Amerikalı)","date":"1865","place":"Amerika Birleşik Devletleri","game":"İskambil","medium":"Ambrotip","size":"14,0 × 11,0 cm","credit":"","p":["Ambrotip, cam üzerindeki ince bir negatifin arkası siyahla kaplanarak pozitif gibi görünmesi sağlanan bir fotoğraftır. Dagerotipten ucuz olduğu için 1850–60’ların Amerika’sında yaygındı. Bu fotoğraf yaldızlı bir paspartunun ardında, kırmızı kadife kaplı bir kutuda durur.","Düz bir fonun önünde üç adam küçük bir masanın çevresinde, ellerinde kâğıtlar. Soldaki melon şapkalı, sağdaki kasketli; ikisinin de ağzında puro var. Ortadaki koyu ceketli adam bize bakıyor. Büyük olasılıkla fotoğraf için oyunun ortasındaymış gibi poz verdiler."],"spots":[["Eller","Masanın üstünde kâğıt tutan eller."],["Melon şapkalı","Solda, purolu."],["Ortadaki adam","Koyu ceketli, bize bakıyor."],["Kasketli","Sağda, purolu."],["Yaldızlı paspartu","Görüntüyü çevreleyen kabartmalı altın çerçeve."],["Kutu","Kırmızı kadife kaplı kutu."]]},"morphy":{"title":"Satranç Şampiyonu Paul Morphy","artist":"Winslow Homer","date":"1859","place":"Amerika Birleşik Devletleri","game":"Satranç","medium":"Uç ağaç baskı","size":"","credit":"","p":["Altında “PAUL MORPHY, THE CHESS CHAMPION” basılı bir portre uç ağaç baskı; o sırada genç bir resimleyici olan Winslow Homer’ın (1836–1910) çizimine göre yapılmış. New Orleans’lı Morphy (1837–1884) 1858–59’da Avrupa’yı dolaşıp önde gelen ustaları birbiri ardına yendi ve ünlü olarak döndü.","Genç Morphy oturmuş, sol elini bir tahtanın kenarına koymuş; yanında şah, kale, piyon ve başka taşlar duruyor. Ünlü olarak döndüğü 1859’da yapılan bu baskı, büyük olasılıkla bir gazete ya da dergide resim olarak basıldı."],"spots":[["Taşlar","Tahtada şah, kale, piyonlar ve ötekiler."],["Tahtadaki el","Tahtanın kenarındaki sol eli."],["Morphy’nin yüzü","Yirmisini yeni geçmiş şampiyon."],["Papyon","Özenli bir yaka."],["Dizdeki el","Dizine koyduğu sağ eli."],["Başlık","Alttaki “PAUL MORPHY, THE CHESS CHAMPION”."]]},"dutton":{"title":"Sherborne Park’ın Salonunda Dutton Ailesi, Gloucestershire","artist":"Johann Zoffany","date":"y. 1772","place":"İngiltere","game":"İskambil","medium":"Tuval üzerine yağlıboya","size":"101,5 × 127,0 cm","credit":"","p":["Almanya doğumlu olup İngiltere’de ün yapan Johann Zoffany’nin (1733–1810) eseri. Aileleri rahat bir hâlde gösteren “sohbet tablosu” 18. yüzyıl İngiltere’sinde doğdu ve çok sevildi. Sahne, Gloucestershire’daki Sherborne Park’ın salonu.","Müzeye göre baba ile kızı, anne ile oğlu bir iskambil oyununda sonraki hamleyi düşünüyor. Aile yakın zamanda bir yakınını kaybetmiş; bu yüzden anne baba tam yas siyahı, çocuklar ise hafif yas renkleri olan leylak, beyaz ve gri giymiş."],"spots":[["Oyun masası","Yeşil çuha kaplı masa ve kâğıtlar."],["Baba","Siyahlar içinde, kâğıtlarını tutuyor."],["Kız","Beyazlar içinde, kâğıtlarına bakıyor."],["Oğul","Grilerle, kâğıtlarını tutuyor."],["Anne","Siyah yas giysisiyle."],["Şömine","Ateşi yanan mermer şömine."]]},"whist":{"title":"Noel Akademisyenleri: Bir Birleşik Whist Oyunu","artist":"James Bretherton (büyük olasılıkla H. W. Bunbury’den)","date":"1773","place":"İngiltere","game":"Whist (iskambil)","medium":"Asitle oyma baskı","size":"26,5 × 39,6 cm","credit":"","p":["Müzeye göre Cambridge akademisyenleriyle alay eden bir karikatür. Sol altta “H. W. Bunbury del. 1772”, sağ altta “J. Bretherton f.” yazıyor gibi; 1773’te Londra’da New Bond Street’teki bir dükkândan yayımlanmış. Duvarda akademik kepler asılı.","Dört beyefendi whist oynarken birbirine yüz buruşturuyor. Whist iki ikili takımla oynanır; başlıktaki “birleşik oyun” büyük olasılıkla bir kelime oyunu. Arkada biri parmaklarını başka birinin başı üstünde kaldırarak alay ediyor. Yakında iki hizmetçi ve iki köpek var."],"spots":[["Masadaki kâğıtlar","Masaya oynanmış kâğıtlar."],["Peruklu akademisyen","Büyük peruklu, kâğıtlarını göğsüne tutan bilgin."],["Parmak işareti","Arkadaki adam parmaklarını başka birinin başı üstünde kaldırıyor."],["Hizmetçi kadın","Şapkalı, tepsi taşıyan hizmetçi."],["Kepler","Duvarda asılı üniversite kepleri."],["Sağdaki köpek","Sağ altta havlayan küçük köpek."]]},"hey":{"title":"Satranç Oynayan Üç Adam","artist":"Paul Hey","date":"1877–1952","place":"Almanya","game":"Satranç","medium":"Baskı (büyük olasılıkla asitle oyma)","size":"19,3 × 26,0 cm","credit":"","p":["Alman ressam ve çizer Paul Hey’in (1867–1952) bir baskısı. Üç yaşlı adam tek bir satranç tahtasına eğilmiş; ince, üst üste çizgiler derin kırışıklıkları ve beyaz sakalları çiziyor.","Müze kaydında belirtildiği gibi soldaki adam elini çenesine dayamış, sağdaki parmakları arasında puro tutarak taşlara uzanıyor. Masanın solunda iki kahve fincanı, bir bardak ve bir kibrit kutusu var. Büyük olasılıkla bir kahvede oynanan oyun."],"spots":[["Satranç tahtası","Masadaki tahta ve taşlar."],["Elini çenesine dayayan","Beyaz sakallı, düşüncelere dalmış."],["Ortadaki adam","Öne eğilmiş, bir taşa uzanıyor."],["Sağdaki adam","Arkadan bakıyor."],["Purolu el","Parmaklar arasında bir puro."],["Kahve ve kibrit","Solda iki fincan, bir bardak, bir kibrit kutusu."]]},"artful":{"title":"Kurnaz Kâğıt ya da Nineye Bir Fazla. Kupa Kozdur!","artist":"Anonim","date":"1852–1863","place":"Büyük olasılıkla Britanya","game":"İskambil","medium":"Stereo fotoğraf, boyalı","size":"8,4 × 17,4 cm","credit":"","p":["İngilizce başlığı “The artful card, or, one too many for granny. Hearts are trumps!”. Kurnaz bir kâğıtla nineyi atlatmayı anlatan komik bir sahne, stereo fotoğraf çifti olarak yapılmış. İngilizce başlığından büyük olasılıkla Britanya’da üretilmiştir.","Yuvarlak masada nine ile küçük bir kız iskambil oynuyor; yeşil giysili genç kadın elinde kâğıtlarla arkadan bir genç adamın kollarında. “Kupa kozdur” büyük olasılıkla kâğıt rengiyle aşkı birleştiren bir kelime oyunu. Çıkrıklı ve büfeli oda kuşkusuz bir stüdyo dekoru."],"spots":[["Genç kadının kâğıtları","Yeşil giysili kadının elindeki kâğıtlar."],["Genç adam","Arkadan elini omzuna koymuş."],["Nine","Başörtülü yaşlı kadın, gözü kâğıtlarında."],["Küçük kız","Gülümseyerek kâğıt atıyor."],["Masa","Kâğıtlar ve ufak şeylerin durduğu yuvarlak masa."],["Büfe","İçinde tabak çanak olan camlı dolap."]]},"cezcards":{"title":"Kâğıt Oynayanlar İçin Etüt","artist":"Paul Cézanne","date":"1890–92","place":"Fransa","game":"İskambil","medium":"Bej velen kâğıt üzerine suluboya ve kurşun kalem","size":"36,2 × 48,5 cm","credit":"","p":["1890’larda Güney Fransa’daki Aix’te Cézanne, kâğıt oynayan adamları birkaç kez resmetti. Bu, o dizi için yapılmış bir suluboya etüttür: şapkalı, bıyıklı bir adam masada oturmuş elindeki kâğıtlara bakıyor.","Kurşun kalem çizgilerinin üstüne ince mavi ve gri suluboyalar ceketin kıvrımlarını ve bedenin ağırlığını yakalar. Sağ taraf ve masanın uzak ucu yarım bırakılmış; renk yalnızca figürün çevresinde. Modellerinin yöredeki çalışan insanlar olduğu söylenir."],"spots":[["Yüz","Şapkanın altında gözlerini indirmiş, kâğıtlarına bakıyor."],["Kâğıtlar","İki eliyle tuttuğu kâğıtlar."],["Masa","Yalnızca kalemle çizilmiş masa."],["Sandalye","Soldaki sandalye arkalığı."],["Ceket","Mavi ve griyle kurulmuş kıvrımlar."],["Yarım kalan yer","Masa ayaklarının yanında yalnızca çizgiler kalmış."]]},"vuillardck":{"title":"Dama Oyunu, Manzaralar ve İç Mekânlar’dan","artist":"Édouard Vuillard","date":"1899","place":"Fransa","game":"Dama","medium":"Gri fildişi Çin kâğıdı üzerine renkli taş baskı","size":"36,9 × 28,5 cm","credit":"","p":["Fransız ressam Vuillard’ın, sanat taciri Ambroise Vollard’ın yayımladığı ve taş baskıcı Auguste Clot’un bastığı renkli taş baskı albümü Manzaralar ve İç Mekânlar’ın ilk levhası.","Desenli duvar kâğıdıyla kaplı bir odada sakallı bir adam dama tahtasının başında oturuyor, kareli elbiseli bir kadın ayakta, eli çenesinde izliyor. Figürler, duvar kâğıdı ve kanepe düz renklere ve desenlere karışıyor; yalnızca tahtanın siyah beyaz kareleri keskin biçimde öne çıkıyor."],"spots":[["Tahta","Siyah beyaz dama tahtası."],["Sakallı adam","Tahtanın başında oturuyor."],["Ayaktaki kadın","Kareli elbiseli, eli çenesinde."],["Duvar kâğıdı","Kıvrımlı çizgilerle dolu duvar kâğıdı."],["Çiçekli yastık","Sol alttaki desenli kumaş."],["Lamba","Duvar dibinde ince bir lamba biçimi."]]},"cruikchess":{"title":"Satranç Oyunu","artist":"George Cruikshank, Yüzbaşı Frederick Marryat’ın çiziminden","date":"1814","place":"İngiltere","game":"Satranç","medium":"Elle boyanmış asitle oyma baskı","size":"23,8 × 34,5 cm","credit":"","p":["İngiliz karikatürist Cruikshank’in, deniz subayı ve sonradan romancı olan Marryat’ın taslağından yaptığı, Londra’da Hannah Humphrey’nin yayımladığı bir baskı. Altta “GAME of CHESS” başlığı yazar.","Mumlu bir masada iki yaşlı beyefendi satranç tahtasının başında. Her birinin arkasında bir seyirci duruyor: soldaki parmağını dudağına götürüp “sus” diyor, sağdaki saplı gözlüğüyle tahtaya bakıyor. Büyük olasılıkla susamayan seyircilerle alay ediyor."],"spots":[["Tahta","Siyah beyaz taşlarıyla satranç tahtası."],["Mumlar","Tahtayı aydınlatan iki mum."],["“Sus” diyen adam","Parmağı dudağında bir seyirci."],["Gözlüklü adam","Saplı gözlükle tahtaya bakan seyirci."],["Uyuyan köpek","Masanın altında uyuyan köpek."],["Başlık","Alttaki “GAME of CHESS”."]]},"domino98":{"title":"Masada Domino Oynayan Kadın ve Çocuk","artist":"Bilinmeyen sanatçı (Amerikalı)","date":"y. 1898","place":"Amerika Birleşik Devletleri","game":"Domino","medium":"Cama yapıştırılmış albümin baskı","size":"40,8 × 51,1 cm","credit":"","p":["Büyük olasılıkla bir Amerikan stüdyosunda çekilmiş, cama yapıştırılarak tamamlanmış büyük bir fotoğraf. Beyaz giysili bir kadınla kıvırcık saçlı bir kız, çiçeklerle süslü küçük bir masanın iki yanında oturuyor.","Masada domino taşları var; kadın bir taş koyuyor. Kız elini çenesine dayamış izliyor. Perdeler, süslü dolap ve duvardaki resimler büyük olasılıkla stüdyo dekorudur."],"spots":[["Taşlar","Masada dizili beyaz domino taşları."],["Kız","Eli çenesinde, taşlara bakıyor."],["Kadın","Beyazlar içinde bir taş koyuyor."],["Çiçekler","Masadaki çiçekli vazo."],["Dolap","Sağ arkadaki süslü dolap."],["Yazı","Sağ alttaki beyaz harfler."]]},"langkat":{"title":"Albert Glaser İki Arkadaşıyla Teknede İskambil Oynuyor, Langkat, Sumatra","artist":"Anonim (H. Ernst & Co.)","date":"1895–1905","place":"Endonezya (Langkat, Sumatra)","game":"İskambil","medium":"Fotoğraf","size":"17,5 × 22,8 cm","credit":"","p":["Kuzey Sumatra’da Langkat’ta çekilmiş bir fotoğraf. Sağ altta “H. Ernst & Co. / Bindjey Langkat” stüdyosunun kabartma damgası var; arkasında el yazısıyla ortadaki adamın, bir hanımın kardeşi Albert Glaser olduğu yazılı.","Bir teknenin tentesi altındaki güvertede beyaz giysili üç adam ellerinde kâğıtlarla masaya oturmuş. Masada kâğıtlar ve madeni para gibi küçük parçalar, sağdaki adamın yanında bir şişe var. Beyaz giysiler ve tente, sıcak bir iklimdeki yaşamı anlatıyor."],"spots":[["Masada","Dağıtılmış kâğıtlar ve para benzeri parçalar."],["Glaser","Ortada kâğıtlarını açan adam; arkadaki not onu adlandırıyor."],["Soldaki adam","Yarı arkası dönük, elinde kâğıtlar."],["Sağdaki adam","Bıyıklı, elinde kâğıtlar."],["Şişe","Sağdaki adamın yanındaki şişe."],["Tente","Tenteden sarkan yaprak süsleri."]]},"chatur":{"title":"Bir Çaturanga Oyunu","artist":"Anonim","date":"1805–1815","place":"Hindistan","game":"Çaturanga","medium":"Guaş ve altın, fırça","size":"16,2 × 9,8 cm (resim)","credit":"","p":["Bir Hint minyatürü. Müze kaydına göre iki kadın çaturanga adlı bir masa oyunu oynuyor, bir hizmetçi de sinek kovucu tutuyor. Çaturanga, satrancın atası sayılan eski bir Hint oyunudur.","Beyaz kemerlerin altında, kırmızı bir halının üstünde lacivert giysili ve turuncu giysili iki kadın damalı bir tahtanın iki yanında oturuyor. Turuncu giysili kadın konuşur gibi elini uzatıyor. Resim siyah ve beyaz çizgili koyu kırmızı bir çerçeveyle çevrili."],"spots":[["Tahta","Kırmızı halıdaki damalı tahta."],["Lacivertli kadın","Altın takılı, tahtaya uzanıyor."],["Turunculu kadın","Karşısında, eli uzanmış."],["Hizmetçi","Arkada ayakta."],["Sinek kovucu","Hizmetçinin kaldırdığı."],["Kırmızı çerçeve","Siyah ve beyaz çizgili koyu kırmızı çerçeve."]]},"shabbarat":{"title":"Kadınlar Dairesinde Akşam","artist":"Anonim","date":"1760–1770","place":"Hindistan","game":"Çaupar (paçisi)","medium":"Guaş ve altın, fırça","size":"34,3 × 25,6 cm","credit":"","p":["Bir Hint minyatürü. Müze kaydına göre dört kadın bir sarayın geniş avlusunda çaupar ya da paçisi denen bir masa oyunu oynuyor. Haç biçimli bir kumaş tahtanın çevresinde oturuyorlar.","Öndeki sağdaki kadın üç uzun zarı atmaya hazır tutuyor. Yanında bir mindere yaslanan, en yüksek mertebeli hanım. Gece olmuş ama terasın her yerinde lambalar var, uzaktaki şehir surlarında da sayısız ışık yanıyor. Kayıt, İslami Berat Kandili’nin kutlandığını düşünür."],"spots":[["Haç biçimli tahta","Yere serilmiş haç biçimli tahta."],["Zarlı kadın","Önde, uzun zarları tutuyor."],["Mindere yaslanan hanım","En yüksek mertebeli hanım."],["Hizmetçi","Tepsiyle yaklaşıyor."],["Lamba","Cam fanus altında yanan mum."],["Uzaktaki köşk","Fıskiyeli bahçe, köşk ve şehrin ışıkları."]]},"govase":{"title":"Go Oynayan Kadınlarla Yumurta Biçimli Vazo","artist":"Anonim (“Tang Jintang” mührü)","date":"1724","place":"Çin (Guangdong)","game":"Go (weiqi)","medium":"Sır üstü emaye ve yaldızlı porselen","size":"Yükseklik 15,3 cm","credit":"","p":["Çok ince porselenden, emaye boyalarla süslenmiş bir Çin vazosu. Arkasında “jiachen yılının Çiçek Bayramı gününde, Lingnan’da İnci Nehri kıyısındaki rahat bir evde yapılmış bir go oyunu resmi” yazıtı ve kırmızı “Tang Jintang” mührü var. Lahey’li koleksiyoncu Jean Theodore Royer’in porselen koleksiyonundandır.","İki kadın masadaki bir go tahtasının iki yanında; soldaki bir taş kâsesi tutuyor. Sağda iki kadın ve iki çocuk eğilip bakıyor. Arkadaki sehpada tavus kuşu tüyleri konmuş bir vazo ve mercan gibi antikalar duruyor."],"spots":[["Tahta","Masadaki go tahtası, siyah ve beyaz taşlarla."],["Soldaki oyuncu","Taş kâsesiyle, parmağıyla gösteriyor."],["Sağdaki oyuncu","Tahtaya eğilmiş."],["İzleyen kadınlar","Arkadan tahtaya bakan kadınlar."],["Tavus tüyü ve mercan","Sehpadaki vazoda."],["Taş kâsesi","Soldaki kadının elinde."]]},"yokihi":{"title":"Bir Hanımla Tavla Oynayan Adam (İmparator Xuanzong ve Yang Guifei)","artist":"Anonim (surimono)","date":"1822","place":"Japonya","game":"Ban-sugoroku (Japon tavlası)","medium":"Metal pigmentli renkli ağaç baskı","size":"21,6 × 19,1 cm","credit":"","p":["Bir surimono: resmi şiirle birleştiren, kalın kâğıda metal tozlarıyla basılmış ve şairlerin dostlarına armağan olarak ısmarladığı lüks bir baskı. Bunda bir şiir ve şair adı Tachibana no Goen var.","Müze kaydına göre Tang imparatoru Xuanzong (685–762) gözdesi Yang Guifei (719–756) ile tavla ve triktrakla akraba bir oyun olan sugoroku oynuyor. Kırmızı bir sehpadaki kutu biçimli tahtada siyah ve beyaz pullar duruyor."],"spots":[["Tahta","Kırmızı sehpada kutu biçimli sugoroku tahtası."],["Yang Guifei","Saçında çiçekler, eli tahtada."],["Xuanzong","Eli çenesinde, tahtaya bakıyor."],["Şiir","Sol üstte bir şiir ve şairin adı."],["Paravan","Arkada dağlar resmedilmiş paravan."],["İmza ve mühür","Sağ altta imza ve kırmızı mühür."]]},"disderi":{"title":"Denizci Kıyafetiyle İskambil Oynayan Adamlar","artist":"Disdéri & Cie","date":"1850–1890","place":"Fransa (Paris)","game":"İskambil","medium":"Albümin baskı (kartvizit fotoğraf)","size":"8,6 × 5,3 cm","credit":"","p":["Bir albümden, arkasında “Disdéri & Cie, 8 Boulevard des Italiens, Paris” basılı kartvizit boyutunda bir fotoğraf. Disdéri, kartvizit gibi çok sayıda basılan küçük portreleri, “carte de visite”i yaygınlaştıran fotoğrafçıdır.","Üç köşe şapka, uzun ceket ve beyaz çoraplı eski usul giyinmiş adamlar desenli bir masada iskambil oynuyor. Müze kaydı “denizci kıyafeti” diyor, ama büyük olasılıkla bir oyun ya da maskeli balo kostümü. Ortadaki adam ayağa kalkıp masaya bakıyor."],"spots":[["Masa","Desenli kenarlı masa, üzerinde kâğıtlar ve kadehler."],["Ayaktaki adam","Üç köşe şapkalı, masaya eğiliyor."],["Soldaki adam","Oturmuş, elinde kâğıtlar."],["Sağdaki adam","Üç köşe şapkalı, elinde kâğıtlar."],["Tokalı ayakkabılar","Beyaz çoraplar ve tokalı ayakkabılar."],["Yaldızlı çerçeve","Kartonun altın kenarı."]]},"gans":{"title":"Kaz Oyunu (74 Kareli Sarmal)","artist":"Jan Oortman (baba), Daniel Willem Stoopendaal’in tasarımından","date":"1763–1823","place":"Hollanda","game":"Kaz oyunu (zarla yarış)","medium":"Mavi, kırmızı ve yeşile boyanmış ağaç baskı","size":"40,8 × 46,8 cm","credit":"","p":["Hollanda’da basılmış sarmal bir yarış tahtası. Müzeye göre kareler 1’den 74’e uzanıyor, bazılarında resim var. Kalıbı Stoopendaal’in tasarımından Jan Oortman oymuş; tasarımcının adı sağ altta “invenit” ile yazılı.","Hedef olan 74, ortada gün batımında deniz kıyısındaki bir tapınak. Karelerde “LEER GELD” (ders ücreti), “DWAALWEG” (yanlış yol), “DOMHEID / WYSHEID” (aptallık / bilgelik) gibi sözcükler ve tırpanlı bir iskelet, “EINDE” (son) var; büyük olasılıkla hayat yolunu anlatan öğretici bir oyun."],"spots":[["74: tapınak","Hedef: gün batımında kıyıdaki tapınak."],["1: başlangıç","Sol alttaki ilk kare."],["Ders ücreti","Büyük olasılıkla ödeme yapılan “LEER GELD” karesi."],["Yanlış yol","“DWAALWEG” yazılı orman yolu."],["Son","Tırpanlı iskelet: “EINDE”."],["Zarlar","İki zar çizili kare."]]},"merelle":{"title":"Dokuz Taş ve Uçurtma","artist":"Claudine Stella, Jacques Stella’dan","date":"1657","place":"Fransa (Paris)","game":"Merelle (dokuz taş)","medium":"Gravür","size":"11,7 × 14,1 cm","credit":"","p":["Claudine Stella’nın amcası ressam Jacques Stella’nın tasarımlarından oyduğu çocuk oyunları dizisinin 17. levhası. Müzeye göre 51 gravürlük bir albümden. Oynayanlar tombul, çıplak küçük çocuklar, yani puttolar.","Sol önde bir taş bloğa çizilmiş tahtada merelle (dokuz taş) oynuyorlar. Sağda yerde, karelere para atılan franc du carreau oyununun çizgileri var; uzakta bir çocuk uçurtmayla koşuyor. Alttaki dizeler herkesin iyi oynamak için uğraştığını söylüyor."],"spots":[["Dokuz taş tahtası","Taşa oyulmuş tahta ve üzerindeki taşlar."],["Uçurtma","Gökte yükselen uçurtma."],["Uçurtmalı çocuk","İpi tutarak koşan çocuk."],["Franc du carreau","Yere çizilmiş kareler ve köşegenler."],["Gösteren çocuk","Elinde bir şeyle çizgileri gösteriyor."],["Başlık","“LA MERELLE, & LE CERF VOLANT”."]]},"feldcards":{"title":"Bahçe Masasında İskambil (Stereo Fotoğraf)","artist":"Anonim","date":"1850–1880","place":"Bilinmiyor (arkasında Groningen’li bir firmanın damgası)","game":"İskambil","medium":"Albümin baskı (stereo fotoğraf)","size":"8,5 × 17,0 cm","credit":"","p":["Sarmaşıklı bir kafes çitin önünde, bahçedeki bir masada iskambil oynayan bir aile ya da arkadaş grubunun stereo fotoğrafı. Arkasında Hollanda’nın Groningen kentinden Feldbrugge & Co.’nun damgası var; büyük olasılıkla onu satan dükkân ya da yayıncı.","Soldaki sakallı adam bir kâğıdı yukarı kaldırmış, masaya vurmak üzere. Başını eline dayamış adam, kâğıtlarını tutan çocuk, beyaz saçlı yaşlı adam ve arkadan izleyen kadın anı tamamlıyor. Herkesin uzun süre kıpırdamaması gerektiğinden sahne büyük olasılıkla poz verilerek çekildi."],"spots":[["Kaldırılan kâğıt","Sakallı adamın havaya kaldırdığı kâğıt."],["Masada","Oynanmış kâğıtlar."],["Çocuğun kâğıtları","Arkası dönük çocuğun elindeki kâğıtlar."],["Yaşlı adam","Sağda oturan beyaz saçlı adam."],["İzleyen kadın","Arkada durup oyunu izliyor."],["İşlemeli sandalye","Öndeki çiçekli kumaş kaplı sandalye."]]},"tempel":{"title":"Oyun Tahtası “Talih Tapınağı”","artist":"Anonim","date":"1816","place":"Hollanda","game":"Zarla oynanan yarış oyunu","medium":"Ağaç baskı, matbaa harfli metin","size":"43,0 × 48,5 cm","credit":"","p":["1’den 74’e kadar kareleri sarmal biçiminde dizilmiş bir oyun kâğıdı. Ortada deniz kıyısında yuvarlak bir tapınak var; aynı koleksiyondaki kural kâğıdı ona “Talih Tapınağı” der ve bir atma oyunundan, yani zar oyunundan söz eder.","Karelerin çoğu boş daireler, ama yer yer gül, diken, zar, demir kapı, salın ve başka resimler ile “LEER GELD” (öğrenim parası), “DOMHEID” (aptallık), “WYSHEID” (bilgelik) gibi sözcükler var. Büyük olasılıkla iyi ve kötü davranışlardan geçerek tapınağa varılan öğretici bir oyundur."],"spots":[["Talih Tapınağı","Ortadaki kıyı tapınağı: 74, varış noktası."],["1 numaralı kare","Sol alttan başlayan çıkış."],["Öğrenim parası","“LEER GELD” yazılı kare."],["Zarlar","Üst sırada çizilmiş iki zar."],["Salın","Alt sıradaki “OVER HAAL” (geçit) resmi."],["Aptallık ve bilgelik","Sağdaki “DOMHEID” ve “WYSHEID”."]]},"verkeer":{"title":"Minyatür Verkeer Tahtası","artist":"Anonim","date":"1690–1710","place":"Hollanda (Amsterdam)","game":"Verkeer (tavlanın bir akrabası), satranç, dokuz taş","medium":"Zeytin, abanoz, şimşir ve kemik kakmalı ceviz; bakır bağlantılar","size":"Kapalı 5,8 × 5,8 cm (açık 11,6 cm)","credit":"","p":["Kenarı ancak altı santim olan, kutu gibi açılan bir oyun tahtası. Dışında bir satranç tahtası ile dokuz taş tahtası, içinde ise tavlanın Hollanda akrabası verkeer için bir tahta var. Bakır menteşeler ve minicik bir kancayla kapanır.","İçinde hâlâ bir zar, kemikten dokuz pul, abanozdan dört pul ve üç küçük sikke duruyor. Müze numarası, büyük olasılıkla Petronella Oortman’ın bebek evinin eşyalarından biri olduğunu gösterir. Küçük olsa da ahşap kakması özenli ve gerçek bir tahta gibi yapılmış."],"spots":[["Zar","Pirinç tanesi büyüklüğünde bir zar."],["Kemik pullar","Beyaz kemikten yuvarlak pullar."],["Abanoz pullar","Siyah abanoz pullar."],["Haneler","Açık ve koyu ağaçtan kakma üçgenler."],["Menteşeler","Katlamak için bakır menteşeler."],["Kanca","Kapatmak için minicik bakır kanca."]]},"silverbd":{"title":"Minyatür Gümüş Oyun Tahtası ve Taşları","artist":"Frederik van Strant II","date":"1739","place":"Hollanda (Amsterdam)","game":"Dama, dokuz taş","medium":"Gümüş","size":"5,4 × 5,4 cm","credit":"","p":["Kenarı yalnızca 5,4 santim olan gümüş bir tahta: 64 kare, yükseltilmiş bir kenar ve asmak için bir halka. Koyu karelere ince çizgiler kazınmış, arka yüze de dokuz taş oyununun çizgileri işlenmiş.","Üzerinde Amsterdam şehir damgası, 1739’u gösteren “E” yıl harfi ve gümüşçü Frederik van Strant II’nin damgası var. Yanında on beş dama taşı kalmış; sekizi çiçek, yedisi daire motifli. Büyük olasılıkla bir bebek evi ya da vitrin için yapılmış gümüş bir minyatürdür."],"spots":[["Çiçekli taşlar","Çiçek motifi basılmış taşlar."],["Daireli taşlar","Daire işaretli taşlar."],["Halka","Tahtanın köşesindeki halka."],["Kazınmış kareler","İnce çizgili koyu kareler."],["Düz kareler","Pürüzsüz, parlatılmış açık kareler."],["Kenar","Tahtanın çevresindeki yükseltilmiş kenar."]]},"schaak1550":{"title":"Atlı Taşlarla Satranç Takımı","artist":"Anonim","date":"1550","place":"Almanya","game":"Satranç","medium":"Şimşir ve iğne yapraklı ağaç","size":"En büyük taş 10,5 cm","credit":"","p":["Her taş, çiçek motifli bir parmaklıkla çevrili tornalanmış bir kaidede durur ve üstüne atlılar ve atlar oyulmuştur. Şahlar ve vezirler sanki ava çıkıyormuş gibi at ya da katıra biner.","Müze kaydına göre siyah şah bir ejderhayı çiğneyen şaha kalkmış bir ata biner ve boynunda Altın Post Nişanı’nı hatırlatan bir zincir taşır; belki V. Karl’dır. Bir vezir elinde şahinle katıra yan oturmuş. En sağda, bir adamın sırtına binmiş bir maymunu gösteren şakacı bir taş var."],"spots":[["Şah","Taçlı, sakallı atlı şah."],["Vezir","Elinde şahinle katıra yan oturan vezir."],["Maymun taşı","Bir adamın sırtındaki maymun."],["Şakacı taş","En solda birinin sırtına binen adam."],["Ayak altındaki yaratıklar","Toynakların altında çömelen ejderha ve hayvanlar."],["Kaideler","Çiçek motifli tornalanmış kaideler."]]},"kraaij":{"title":"Oturma Odasında Tavla Oynayan Kadınlar ve Erkekler","artist":"Anonim","date":"1900–1910","place":"Büyük olasılıkla Hollanda","game":"Tavla","medium":"Gün ışığında belirtilen kolodyon gümüş baskı","size":"8,0 × 11,1 cm","credit":"","p":["Şarap tüccarı Kraaij & Co.’nun (Bordeaux–Amsterdam) fotoğraflarını da içeren bir aile albümünden bir sayfa. Avizeli bir oturma odasında, aile ya da tanıdık olduğu anlaşılan kadınlar ve erkekler masada oturuyor.","Masada katlanır kutu biçimli bir tahta açılmış; iki yandaki kadınların her biri bir zar bardağı tutuyor. Müze kaydı “bir masa oyunu” diyor, ama kutu tahta ve bardaklardan büyük olasılıkla tavla. Yakındaki kahve fincanları ve arkadaki kuş kafesi, evde huzurlu bir akşamı anlatıyor."],"spots":[["Kutu tahta","Açılıp tahta olan katlanır kutu."],["Soldaki bardak","Gözlüklü kadının tuttuğu zar bardağı."],["Sağdaki bardak","Puantiyeli giysili kadın atmak üzere."],["Kuş kafesi","Arkada bir sehpadaki kuş kafesi."],["Avize","Tavandan sarkan cam fanuslu lambalar."],["Ayaktaki adam","Sağda durup oyuna bakıyor."]]},"braekel":{"title":"Dama Oynayan Yaşlı Karı Koca","artist":"Ferdinand De Braekeleer (baba)","date":"1862","place":"Belçika (Anvers)","game":"Dama","medium":"Asitle oyma baskı","size":"21,8 × 16,5 cm","credit":"","p":["Anversli ressam De Braekeleer’in (1792–1883) bir baskısı; sol altta “Ferdinand De Braekeleer Antwerpen 1862” imzası var. Ocaklı eski bir mutfakta yaşlı bir adamla yaşlı bir kadın küçük bir masada karşılıklı oturuyor.","Tahtada yuvarlak taşlar duruyor; adam birini alırken kadın karşılık verir gibi elini açıyor. Yerde bir şapka ve düşmüş birkaç taş var. Rafta tabaklar dizili, pencereden evler görünüyor."],"spots":[["Tahta ve taşlar","Masadaki tahta ve yuvarlak taşlar."],["Yaşlı adam","Öne eğilmiş, bir taşı alıyor."],["Yaşlı kadın","Başlıklı, konuşurken el hareketi yapıyor."],["Yerdeki şapka","Adamın yere koyduğu şapka."],["İmza","“Ferdinand De Braekeleer Antwerpen 1862”."],["Raftaki tabaklar","Ocağın üstündeki rafta büyük tabaklar."]]},"billiard":{"title":"Bilardo","artist":"H. W. Bunbury’den (baskıcı bilinmiyor)","date":"1780","place":"İngiltere (Londra)","game":"Bilardo","medium":"Asitle oyma ve noktalama","size":"30,0 × 39,1 cm","credit":"","p":["İngiliz karikatürcü Henry William Bunbury’nin çiziminden bir baskı; 1780’de Londra’da Watson & Dickinson tarafından yayımlanmış. Müzeye göre bir dizinin dördüncüsü.","İki adam bilardo oynuyor, ötekiler soluklarını tutup izliyor. Biri vuruş için masaya eğilmiş, bir başkası isteka omzunda bekliyor. Duvarda bir isteka rafı ve iki yuvarlak sayı kadranı var. Müze, masanın üçgen gibi göründüğünü belirtir."],"spots":[["Masa ve toplar","Çuha kaplı masa ve topları."],["Nişan alan","Vuruş için masaya eğilmiş adam."],["İstekalı adam","Uzun istekasıyla bekleyen adam."],["Sayı kadranları","Duvardaki iki yuvarlak kadran; büyük olasılıkla sayı tutmak için."],["İsteka rafı","Duvara dayalı bir sıra isteka."],["Gülen ikili","Sağda birlikte gülen iki seyirci."]]},"baizi":{"title":"Yüz Çocuk (ayrıntı)","artist":"Xu Yanghong","date":"18. yüzyıl","place":"Çin","game":"Weiqi (go)","medium":"Yatay rulo; kâğıt üzerine mürekkep (ve hafif renk)","size":"29,8 × 526 cm (rulonun tamamı)","credit":"","p":["Çinli profesyonel ressam Xu Yanghong’un beş metreyi aşan bir yatay rulosundan kesilmiş bir go sahnesi. Bir bahçede yüz çocuk oynuyor, müzik yapıyor, okuyor ve yazıyor. “Yüz çocuk” Asya sanatında doğurganlığı ve ailenin bolluğunu simgeleyen önemli bir konudur.","Rulo, Japon ustası Tani Bunchō’nun sonradan yaptığı ve aynı müzedeki kopyasıyla da tanınır. Muz yaprakları ve bir bilgin taşının yanında çocuklar alçak bir sehpadaki go tahtasının çevresinde; ikisi ellerinde taş kâseleriyle oynuyor, ötekiler bakıyor."],"spots":[["Tahta","Alçak sehpada taşlarıyla go tahtası."],["Taş koyan çocuk","Mavi ceketli, eli taş kâsesinde."],["Öteki oyuncu","Beyazlar içinde, tahtaya eğilmiş."],["Elleri başında","Arkadan bakan bir çocuk."],["Bilgin taşı","Delik deşik büyük bir taş."],["Tüy yelpaze","Solda tüy yelpaze tutan çocuk."]]},"schenkcards":{"title":"İskambil Oynayan İki Çinli Kadın","artist":"Pieter Schenk (II)","date":"1727–1775","place":"Hollanda (konu: Çin)","game":"İskambil","medium":"Asitle oyma baskı","size":"16,5 × 26,2 cm","credit":"","p":["Amsterdamlı gravürcü ve yayıncı genç Pieter Schenk’in yayımladığı, Çin üslubunda figür ve manzaralardan oluşan “Yeni Tasarlanmış Çinliler” albümünün ilk bölümünden bir levha. Avrupa’da moda olan, hayalî bir Çin’i gösteren şinuazri türündendir.","Müze kaydına göre bir bahçede iki Çinli kadın iskambil oynuyor, sağdan da dolu bir tepsiyle bir kadın geliyor. Masadaki kâğıtlar Avrupa iskambiline benziyor. Solda bir sehpada bir tavşan dinleniyor, nehirde de bir yelkenli var."],"spots":[["Kâğıtlar","Masaya yayılmış kâğıtlar; Avrupa kâğıtlarına benziyor."],["Soldaki kadın","Elinde kâğıtlar, ortağına bakıyor."],["Sağdaki kadın","Masaya bir kâğıt bırakıyor."],["Tepsili kadın","Yemek dolu tepsi getiriyor."],["Tavşan","Solda sehpada dinleniyor."],["Yelkenli","Nehirdeki tekne."]]},"gosaucer":{"title":"Go Oynayan Figürlerle Tabak","artist":"Anonim","date":"1725–1735","place":"Çin","game":"Go (weiqi)","medium":"Sır üstü emaye ve yaldızlı porselen","size":"Çap 16,4 cm","credit":"","p":["Famille rose denen yumuşak sır üstü renklerle süslenmiş bir Çin tabağı. Altında çift daire içinde bir fırça, bir ruyi asası ve bir mürekkep çubuğundan oluşan bir işaret var. Müze kayıtları figürleri kimi zaman go oynayan bir erkek ve bir kadın, kimi zaman ikisi oynayan üç kadın olarak anlatır.","Bir odada masada bir go tahtası var; iki oyuncu karşılıklı taş koyuyor, üçüncüsü arkada ayakta izliyor. Masada sarı taş kâseleri, arkada çiçekli vazo konmuş bir sehpa, sağda büyük mavi bir küp var."],"spots":[["Tahta","Masadaki taşlı go tahtası."],["Soldaki oyuncu","Açık mor giysili, masaya yaslanmış."],["Sağdaki oyuncu","Pembe giysili, taş koyuyor."],["İzleyen","Arkada ayakta izliyor."],["Vazo","Sehpadaki çiçek vazosu."],["Mavi küp","Sağdaki büyük küp."]]},"cheetham":{"title":"Küçük Bir İskambil Toplantısı (Rusya’da)","artist":"Anonim","date":"1903–1904","place":"Rusya","game":"İskambil","medium":"Gün ışığında belirtilen jelatin gümüş baskı","size":"9,2 × 11,5 cm","credit":"","p":["Rusya’da yaşamış İngiliz Cheetham ailesinin albümünden; kartonda İngilizce “a little card-party” yazıyor. Müze, bunların büyük olasılıkla Joseph Cheetham’ı ziyarete gelen İngiliz arkadaşlar olduğunu belirtiyor.","Duvar kâğıtlı bir odada üç kişi çiçekli örtülü bir masada kâğıtlarını açmış. Masada iki şamdan var, ortadaki kadın kâğıtlarını yelpaze gibi açarken gülüyor. Büyük olasılıkla uzak bir ülkede memleketten dostlarla geçen rahat bir an."],"spots":[["Soldaki adamın kâğıtları","Sakallı adamın açtığı kâğıtlar."],["Kadının kâğıtları","Ortadaki kadının yelpaze gibi açtığı kâğıtlar."],["Sağdaki adam","Öne eğilmiş, elinde kâğıtlar."],["Şamdanlar","Masadaki iki şamdan."],["Masa örtüsü","Çiçekli, desenli büyük örtü."],["Yazı","Kartondaki “a little card-party”."]]},"problem":{"title":"Problem (Stereo Fotoğraf)","artist":"Anonim","date":"1852–1863","place":"Bilinmiyor","game":"Satranç","medium":"Stereo fotoğraf, boyalı","size":"8,4 × 17,4 cm","credit":"","p":["İngilizce başlığı “The Problem”. Beyaz peruklu, 18. yüzyıl usulü giyinmiş iki kişi süslü bir masada satranç oynuyor; boyanmış bir stereo fotoğraf çifti. Arkasında el yazısıyla “Simons” yazılı.","Genç olan iki eliyle yanaklarını tutmuş tahtaya bakıyor, karşısındaki yaşlı adam ise sırıtıyor. Büyük olasılıkla, problemin kimde olduğunun bir bakışta anlaşıldığı, kurgulanmış tiyatromsu bir sahne. Ayaklarının dibinde bir köpek yatıyor."],"spots":[["Tahta ve taşlar","Süslü masadaki tahta ve taşlar."],["Düşünceli oyuncu","Başını iki eliyle tutmuş, tahtaya bakıyor."],["Sırıtan adam","Mavi ceketli yaşlı adam gülümsüyor."],["Köpek","Ayaklarının dibinde yatan köpek."],["Kırmızı perde","Arkadaki boyanmış perde."],["İkinci görüntü","Sağdaki görünüm; stereoskopta derinlik kazanır."]]},"tarocco":{"title":"Bir Tarot Destesinden On Kart","artist":"Anonim (büyük olasılıkla Giuseppe Maria Mitelli’nin tasarımından)","date":"1660–1718","place":"İtalya (Bologna)","game":"Tarocchi (kozlu kâğıt oyunları)","medium":"Asitle oyma ve gravür, kısmen açık kahveyle elle boyanmış","size":"Bir karton üzerinde on kart","credit":"","p":["Bologna yapımı bir tarot destesinden on kart, bir kartona yan yana yapıştırılmış. Tarot başlangıçta fal için değil, kozlu kâğıt oyunları için kullanılırdı. Sol üstte bir başlık kartı var; müze, portrenin sanatçı Mitelli olabileceğini düşünür.","Üst sırada taçlı bir adam ve bir atlı dahil dört figür, alt sırada “sikke” renginin altıdan ona kadar kartları var; her kartta numarası kadar sikke basılı. Basılı çizgiler kısmen açık kahveyle boyanmış."],"spots":[["Başlık kartı","Sol üstte çerçeveli bir portre ve yazı."],["Taçlı adam","Asa tutan taçlı bir figür."],["Ayaktaki kadın","Kadeh tutan taçlı bir kadın."],["Atlı","At üstünde bir figürün kartı."],["Sikke onlusu","Alt solda on sikke."],["Sikke altılısı","Alt sağda altı sikke."]]},"kindtegel":{"title":"Oynayan Çocuk Sahneli Çiniler","artist":"Anonim","date":"1680–1730","place":"Hollanda","game":"Çocuk oyunları (cambaz ayağı, salıncak vb.)","medium":"Kalay sırlı toprak (Delft çinileri), mavi boyalı","size":"107 × 80 cm (48 çini)","credit":"","p":["Sekiz sıra yüksekliğinde, altı sıra genişliğinde, toplam kırk sekiz çiniden oluşan bir pano. Her çinide mavi boyayla küçük çizilmiş, oynayan iki çocuk var; her köşede “örümcek” denen küçük bir süs bulunur.","Biri cambaz ayağıyla yürüyor, biri salıncakta itiliyor, ötekiler yerde bir şeyin başına çömelmiş: her çini farklı bir oyun gösterir. Bu tür “çocuk oyunları” çinileri Hollanda’da sevilirdi ve büyük olasılıkla mutfak duvarlarına ve şömine çevresine döşenirdi."],"spots":[["Cambaz ayağı","Cambaz ayağıyla yürüyen çocuk."],["Salıncak","Salıncakta itilen çocuk."],["Yerde oyun","Yerde bir şeyle oynayan çömelmiş çocuklar."],["Örümcek süsleri","Köşelerdeki küçük süsler."],["Kırk sekiz çini","Altışar çinilik sekiz sıra."],["Son çini","Sağ alt köşedeki çini."]]},"dammolen":{"title":"Dama ve Dokuz Taş İçin Minyatür Tahta","artist":"Anonim","date":"1740–1760","place":"Hollanda (Amsterdam)","game":"Dama, dokuz taş","medium":"Açık renk dolgu macunlu ceviz","size":"4,2 × 4,0 × 1,5 cm","credit":"","p":["Yaklaşık dört santim genişliğinde minicik bir ceviz tahta. Neredeyse kare ve kenarı yükseltilmiş; bir yüzü dama, öbür yüzü dokuz taş tahtası olarak kullanılır.","Dama yüzünde kareler oyulup açık renk macunla doldurulmuş, böylece ahşapla dama deseni oluşmuş; dokuz taş yüzündeki oyma çizgiler de aynı macunla doldurulmuş. Bu kadar küçük olduğuna göre büyük olasılıkla bir bebek evi için yapılmıştır."],"spots":[["Dolgulu kareler","Oyulup açık macunla doldurulmuş kareler."],["Ahşap kareler","Çıplak ceviz bırakılmış kareler."],["Kenar","Çevredeki yükseltilmiş kenar."],["Yakın köşe","Bize en yakın köşe."],["Kalınlık","1,5 cm yüksekliğindeki yan yüz."],["Arka sıra","En arkadaki kare sırası."]]},"karelpiece":{"title":"Şarlman Portreli Dama Taşı (yarım)","artist":"Anonim","date":"1525–1575","place":"Almanya (Nürnberg)","game":"Dama ya da tavla türü","medium":"Şimşir","size":"Çap 5,3 cm","credit":"","p":["Şimşirden oyulmuş bir dama taşının bir yüzü. Ortada defne çelengiyle çevrili bir profil, çevresinde “CAROLVS. MAGNVS. IMPER. AVGVST.” (İmparator Şarlman) yazısı var.","Müzede aynı yapımda on iki’den fazla taş bulunur; her birinde eski Roma’dan Orta Çağ’a bir imparator ya da imparatoriçe oyulmuştur: Tiberius, Agrippina, Dindar Louis, Otto ve diğerleri. Büyük olasılıkla hükümdarlar galerisi olarak düşünülmüş lüks bir takımdı."],"spots":[["Profil","Defne çelengi içinde Şarlman’ın profili."],["Çelenk","Portreyi çevreleyen defne halkası."],["CAROLVS","Üstteki “CAROLVS. MAGNVS”."],["AVGVST","Soldaki “IMPER. AVGVST”."],["Yıldız","Yazıyı ayıran küçük yıldız."],["Kenar","Taşın basamaklı kenarı."]]},"vdberge":{"title":"Hollanda Oyunu, Güzel Hayat! (İskambil)","artist":"Pieter van den Berge (tasarım ve yayın)","date":"1694–1737","place":"Hollanda (Amsterdam)","game":"İskambil","medium":"Kırmızı, mavi ve yeşil à la poupée basılmış asitle oyma baskı","size":"27,3 × 17,0 cm","credit":"","p":["Amsterdamlı baskıcı ve yayıncı Van den Berge’nin “LE JEU HOLLANDOIS. LA BELLE VIE!” başlıklı bir hicvi. Müzeye göre bir meyhanede adamlar iskambil oynuyor; kadehini kaldırıp iç geçiren bir adamın yanında ve masanın altında şeytanlar onun parasını kazanıyor.","Alttaki Felemenkçe dizelerde kaygısız çapkın, köpek ve horoz dövüşlerinin, kâğıtların ve zarların parasını erittiğinden yakınıyor. İki yanda iki şeytan Almanca olarak onu zarla, kâğıtla eğlenmeye çağırıyor. Arka duvardaki resimde de köpek ve horoz dövüşleri var."],"spots":[["Kadehli adam","Büyük peruklu çapkın kadehini kaldırıyor."],["Eldeki kâğıtlar","Adamın elinde açılmış kâğıtlar."],["Soldaki şeytan","Arkasında sırıtan bir şeytan."],["Masanın altındaki şeytan","Yere dökülen paraları topluyor."],["Dövüş resmi","Köpek ve horoz dövüşlerini gösteren tablo."],["Başlık ve dizeler","“LE JEU HOLLANDOIS” ve çapkının yakınması."]]},"crespi":{"title":"Zar Oynayan Çocuklar","artist":"Giuseppe Maria Crespi","date":"1675–1747","place":"İtalya","game":"Zar","medium":"Asitle oyma baskı","size":"22,5 × 15,1 cm","credit":"","p":["Bolonyalı ressam Crespi’nin kendi eliyle yaptığı bir baskı. Müzeye göre dört çocuk sokakta zar oynuyor; altta üç satırlık İtalyanca bir şiir var.","Çömelmiş çocuk zarları yere yeni atmış, öteki üçü izliyor. Şiir kemiklerden (zarlardan) ve sayılardan, kısa bir oyundan ve azalan paradan söz ediyor; büyük olasılıkla bir çocuk oyununa bile kumara karşı bir uyarı ekliyor."],"spots":[["Zarlar","Yerdeki küçük zarlar."],["Çömelen çocuk","Zarları yeni atmış."],["Ayaktaki çocuk","Atışa eğilip bakıyor."],["Sağdaki çocuk","Yere oturmuş izliyor."],["Arkadaki çocuk","Ötekilerin arkasından bakıyor."],["Şiir","Üç satır İtalyanca şiir."]]},"epinal":{"title":"Büyük Kaz Oyunu (Épinal)","artist":"Pellerin & Cie (Épinal)","date":"1791–1900","place":"Fransa (Épinal)","game":"Kaz oyunu (zarla yarış)","medium":"Sarı, kırmızı, yeşil ve maviye boyanmış ağaç baskı; matbaa harfli metin","size":"39,8 × 59,0 cm","credit":"","p":["Doğu Fransa’daki Épinal’de Pellerin baskıevinin renkli bir yaprağı; üstte Fransızca “GRAND JEU DE L’OIE” yazar. Müzeye göre 63 karelik sarmalda kazlar, başka hayvanlar ve figürler var; ortada Felemenkçe “GANZENBORD!” başlığı ve kurallar basılı.","Kurallara göre iki zar atılır; kaz karesine gelen bir o kadar daha ilerler. 6’daki köprü 12’ye götürür, 19’daki han iki el bekletir, 31’deki kuyuda başkası gelene dek beklenir, 42’deki labirent 30’a, 58’deki ölüm başa döndürür. Kazanmak için tam 63’e varmak gerekir. İki yanda kesilip kullanılacak fişler dizili."],"spots":[["63: kaz","Hedef 63: havuzdaki kaz."],["Kurallar","Ortadaki Felemenkçe kurallar."],["Kesilecek fişler","İki yanda numaralı yuvarlak fişler."],["Başlık","Üstteki “GRAND JEU DE L’OIE”."],["Oynayan çocuklar","Sol alt köşede oynayan çocuklar."],["Yayıncı","Sol üstte “PELLERIN & Cie”."]]},"matham":{"title":"Triktrak Oynayan Çift","artist":"Jacob Matham (yayıncı), şiir Simon Sovius","date":"1621","place":"Hollanda (Haarlem)","game":"Triktrak (tavlanın bir türü)","medium":"Gravür","size":"17,9 × 20,0 cm","credit":"","p":["Haarlemli gravürcü ve yayıncı Matham’ın yayımladığı dörtlü dizinin üçüncü baskısı. Müzeye göre şık giyimli bir çift küçük bir masada parasına triktrak oynuyor; kese masada, kadın zarları elinde tutuyor.","Tahtanın uzun haneleri ve açık-koyu taşları keskin biçimde oyulmuş. Altta Latince ve Felemenkçe dizeler var; Felemenkçe olanlar yalnızca içkinin aşırısının değil, oyun ve zarın da her türlü kazanca aykırı olduğunu söyleyerek uyarıyor. Arkada bir oğlan şarap kadehi kaldırıyor."],"spots":[["Tahta","Haneleri ve taşlarıyla triktrak tahtası."],["Taş süren adam","Şapkalı adam tahtaya uzanıyor."],["Zarlı kadın","Büyük yakalı kadın zarları tutuyor."],["Kadehli oğlan","Arkada şarap kadehi kaldırıyor."],["Kese","Masadaki bahis kesesi."],["Dizeler","Latince ve Felemenkçe uyarı dizeleri."]]},"jardin":{"title":"Bahçe Masasında İskambil Oynayan Üç Adam ve Bir Seyirci (Fransa)","artist":"Anonim (Fransız bir amatör fotoğrafçı)","date":"1900–1910","place":"Fransa","game":"İskambil","medium":"Albümin baskı","size":"11,8 × 17,2 cm","credit":"","p":["Fransız bir amatör fotoğrafçının albümünden; albümde bir ailenin, Delizy & Doistau içki fabrikasının, ordunun ve Fransa’nın görülecek yerlerinin fotoğrafları da var.","Çakıllı bir bahçenin gölgesinde üç adam küçük bir masada iskambil oynarken, beyaz sakallı yaşlı bir adam arkalarında durup izliyor. Masada kâğıtlar var, hasır şapkalı adam elindekilere bakıyor. Büyük olasılıkla aile ya da dostlar arasında rahat bir an."],"spots":[["Masadaki kâğıtlar","Oynanmış kâğıtlar."],["Seyirci","Beyaz sakallı yaşlı adam, arkada ayakta."],["Hasır şapkalı adam","Ortada, kâğıtlarına bakıyor."],["Sağdaki adam","Koyu ceketli, elinde kâğıtlar."],["Soldaki adam","Açık renk ceketli."],["Bahçe","Bahçenin çakılı ve çalıları."]]},"lamplight":{"title":"İskambil Oynayan İnsanlar (Lambanın Altında)","artist":"Anonim","date":"1900–1910","place":"Bilinmiyor","game":"İskambil","medium":"Jelatin gümüş baskı","size":"7,5 × 10,0 cm","credit":"","p":["Bir albümden küçük bir fotoğraf; müzedeki adı “İskambil oynayan kişiler”. Fotoğrafçı da yer de bilinmiyor.","Tavandan sarkan bir gaz lambasının ışığında, çizgili giysili bir kadın, bir kız ve birkaç oğlan saçaklı örtülü bir masada kâğıtlarını yelpaze gibi açmış. Karanlık bir odada fotoğraf çekmek zor olmalıydı; büyük olasılıkla bir aile akşamı yakalanmak istenmişti."],"spots":[["Saçaklı örtü","Desenli, saçaklı masa örtüsü."],["Lamba","Tavandan sarkan gaz lambası."],["Çizgili giysili kadın","Beyaz çizgili elbiseyle oturuyor."],["Kadının kâğıtları","Yelpaze gibi tuttuğu kâğıtlar."],["Kızın kâğıtları","Ortadaki kızın açtığı kâğıtlar."],["Sağdaki oğlan","Öne eğilmiş, elinde kâğıtlar."]]},"borduur":{"title":"Kâğıt Oynayanlar İşlenmiş Oyun Masası Tablası","artist":"Anonim","date":"1700–1725","place":"Bilinmiyor","game":"İskambil","medium":"Renkli yün ve ipekle gros point ve petit point işleme","size":"100 × 185 cm","credit":"","p":["Katlanır bir oyun masasının tablasından nakış; çok renkli yün ve ipekle, iri ilmekli gros point ile ince petit point birlikte kullanılmış. Köşeleri kesik bir biçimin içinde kıvrım ve çiçeklerden bir çerçeve dolanır.","Ortadaki manzarada iki hanım ve bir bey, bir masanın çevresinde kâğıt oynuyor. Müze kaydına göre masada bir kese, kâğıtlar ve başka oyun takımları var. Kâğıt oyunu masasına yerinde bir süs: bir kâğıt oyunu sahnesi."],"spots":[["Masa","Kese ve kâğıtların durduğu yeşil masa."],["Bey","Solda oturan şapkalı adam."],["Ortadaki hanım","Masanın arkasında oturan hanım."],["Sağdaki hanım","Mavi giysili oturan hanım."],["Ağaçlar","Figürlerin ardındaki ağaçlar."],["Çerçeve","Kıvrım ve çiçeklerden çerçeve."]]},"piquet":{"title":"Piket Oyunu Basılı Örtü","artist":"Anonim","date":"1725–1750","place":"Bilinmiyor","game":"Piket (kâğıt oyunu)","medium":"Keten, kırmızı ve mor baskı","size":"73,0 × 82,5 cm","credit":"","p":["Oyun masası için bir keten örtü; baştan başa kırmızı ve morla bir kâğıt oyununun takımları basılmış. Müze kaydı onu mendil olarak da tanımlar.","Yediden asa 32 kâğıtla oynanan piketin kâğıtları kenar şeridine ve ortaya saçılmış; ortada bir kese, çevresinde fişler var. Resimli kâğıtlar Caesar, Argine, Hogier gibi adlar taşıyan “Paris tipi”dir."],"spots":[["Kese","Ortadaki bahis kesesi."],["Resimli kâğıtlar","Paris tipi papaz ve kızlar."],["Fişler","Yuvarlak fişler."],["Kâğıt şeridi","Örtünün çevresindeki kâğıt şeridi."],["Ters desteler","Arkası görünen desteler."],["Mühürlü paket","Sağ altta mühürlü bir kâğıt paketi."]]},"schaakglas":{"title":"Satranç Oynayan İki Adam Oyulmuş Kadeh","artist":"Anonim","date":"1815–1830","place":"Bilinmiyor","game":"Satranç","medium":"Renksiz şeffaf cam, çark oyması","size":"Yükseklik 13,7 cm","credit":"","p":["Ayaklı şeffaf bir kadeh; resmi ve yazısı küçük dönen bir çarkla oyulmuş. İki mumun durduğu küçük bir masada iki adam satranç tahtasının iki yanında oturuyor.","Soldaki gözlüklü adam pipo içiyor, sağdaki tahtaya eğilmiş; masada bir şarap kadehi de var. Çevresinde Fransızca şu yazar: hamleleri bilmek çok basit bir şeydir; oyunu bilmek dehanın meyvesidir."],"spots":[["Satranç tahtası","Taşlarıyla tahta."],["Pipolu adam","Solda, gözlüklü ve pipolu."],["Eğilen adam","Sağda, tahtaya bakan adam."],["Mumlar","Tahtanın ardındaki iki mum."],["Şarap kadehi","Masadaki kadeh."],["Yazı","Fransızca oyulmuş sözler."]]},"arlequin":{"title":"Harlekin’in Loto Oyunu","artist":"Anonim (yayımcı Mindermann & Co.)","date":"1818–1845","place":"Hollanda (Amsterdam)","game":"Loto / yarış oyunu","medium":"Elle boyanmış gravür, kartona yapıştırılmış","size":"Bilinmiyor","credit":"","p":["Tahtası, bacaklarını açmış ayakta duran Harlekin’in kendisi olan bir oyun kâğıdı. 1’den 32’ye numaralı kare haneler yeşil kostümünün üstünde ve bacaklarının arasında sıralanır. Altta “Arlequin’s Lotto-Spel” başlığı ve Amsterdam’daki Mindermann & Co.’nun adı yazılı.","Yüzünde file bir maske var; elinde bir şapka ve tahta kılıca benzer bir şey tutuyor. Bazı hanelerde “HW” ya da “P” yazar. Elle boyanmış baskı, büyük olasılıkla oyun tahtası olarak kullanılmak üzere kartona yapıştırılmış."],"spots":[["File maske","Yüzünü örten file."],["1 numaralı hane","Sol bacağının altındaki başlangıç."],["HW hanesi","“HW” yazılı bir hane."],["P 32","“P” yazılı 32 numaralı hane."],["Başlık","Alttaki “Arlequin’s Lotto-Spel”."],["Şapka","Sağ elindeki şapka."]]},"vicaire":{"title":"Papaz Yardımcısının Oyunu","artist":"René Gayant (levhadaki yazıya göre)","date":"1888–1893","place":"Fransa","game":"İskambil","medium":"Kolotipi (müze kaydına göre)","size":"10,4 × 15,6 cm","credit":"","p":["Paris Foto Kulübü Bülteni’nde yayımlanmış, “La partie du Vicaire” (papaz yardımcısının oyunu) başlıklı bir levha. Kenarında “Phototype René Gayant” ve “Héliogravure Lemercier” basılı; fotoğraf büyük olasılıkla Gayant’ın, baskı Lemercier’nin. Kitaba yan çevrilmiş olarak ciltlenmişti.","Tencere tavaların asılı olduğu bir mutfakta siyah cüppeli bir papaz masada kâğıtlarına bakıyor, karşısındaki adam da kâğıt tutuyor. Kasketli bir adam çenesini eline dayamış, bir genç eli kulağında oyunu izliyor. Resim gibi ışık ve düzen, sanatsal fotoğrafa adanmış bir kulübe yakışıyor."],"spots":[["Papazın kâğıtları","Papazın baktığı kâğıtlar."],["Papaz","Siyah cüppe ve beyaz yakalık."],["Kâğıtlı adam","Kıvırcık saçlı, kâğıtlarına bakıyor."],["İzleyen genç","Eli yanağında oyunu izliyor."],["Kasketli adam","Çenesini eline dayamış."],["Mutfak duvarı","Asılı tencereler ve kepçeler."]]},"israels":{"title":"Satranç Oyuncuları","artist":"Isaac Israels","date":"1875–1922","place":"Hollanda","game":"Satranç","medium":"Pastel","size":"40,0 × 57,5 cm","credit":"","p":["Amsterdam şehir hayatını hızlı ve canlı sahnelerle çizen Hollandalı ressam Isaac Israels’in (1865–1934) bir pastel resmi. Penceresi aydınlık bir odada adamlar bir satranç tahtasının çevresinde.","Öndeki ikisi yanağını ya da çenesini eline dayamış, tahtaya dikkatle bakıyor; arkada kasketli bir adam eğilmiş. Taşlar ayrıntılı çizilmemiş, renk lekeleriyle konmuş; uzun bir düşünme anı geçiyor gibi."],"spots":[["Tahta ve taşlar","Tahta; taşlar renk lekeleri."],["Soldaki oyuncu","Yanağı elinde, tahtaya bakıyor."],["Sağdaki oyuncu","Çenesi elinde, düşünüyor."],["Kasketli adam","Arkadan eğiliyor."],["Pencere","Soldaki aydınlık pencere."],["Sandalye","Sağdaki sandalye."]]},"louisxi":{"title":"XI. Louis ve Kızı Anne de Beaujeu","artist":"Adrien Joseph Verhoeven-Ball","date":"1866","place":"Belçika (Anvers)","game":"Satranç","medium":"Baskı (büyük olasılıkla asitle oyma)","size":"26,4 × 31,3 cm","credit":"","p":["Anversli ressam Verhoeven-Ball bu baskıyı hem çizmiş hem oymuş (altta “pinx et sculp”). Müzedeki adı “XI. Louis ve kızı Anne de Beaujeu satranç oynuyor”. Alttaki bir satır Anvers Sanatçılar Derneği’nin ikinci sergisini anar.","15. yüzyıl Fransa kralı XI. Louis kürklü cüppesiyle masada oturuyor, kızı Anne çenesini eline dayamış tahtayı inceliyor. Masada taşlar ve bir meyve kâsesi var, yerde bir köpek yatıyor, arkada silahlı bir muhafız duruyor. Büyük olasılıkla tarihî baba ile kızın hayal edilmiş bir sahnesi."],"spots":[["Tahta ve taşlar","Masadaki satranç tahtası ve taşlar."],["XI. Louis","Şapkalı, kürklü cüppeli kral."],["Anne","Çenesi elinde kızı."],["Uyuyan köpek","Yerde uzanmış ince bir köpek."],["Muhafız","Gölgede silahlı bir asker."],["Başlık","“LOUIS XI ET SA FILLE ANNE DE BEAU-JEU”."]]},"bruining":{"title":"Dama Oynayan Keşişler","artist":"Tieleman Cato Bruining","date":"1750–1850","place":"Hollanda","game":"Dama","medium":"Asitle oyma baskı","size":"20,6 × 16,8 cm","credit":"","p":["Hollandalı baskıcı Bruining’in bir baskısı; sol altta “T. Bruining inv. et fecit aqua fort” (tasarladı ve asitle oydu) yazar. Müzeye göre iki keşiş bir masada dama oynuyor.","Arkalarında üçüncü bir keşiş ve keşiş cübbesi giymiş bir şeytan duruyor. Masanın yanında yine keşiş kılığına girmiş Ölüm, tırpanını sırtında saklayarak bekliyor. Keşişler oyuna öyle dalmış ki içeri sızanları fark etmiyor."],"spots":[["Dama tahtası","Masadaki tahta ve taşlar."],["Ölüm","Cübbeli, tırpanını sırtında saklıyor."],["Arkadaki ikisi","Üçüncü keşiş ve cübbeli şeytan."],["Soldaki oyuncu","Tahtaya eğilmiş keşiş."],["Sağdaki oyuncu","Kollarını masaya dayamış düşünen keşiş."],["İmza","“T. Bruining inv. et fecit aqua fort”."]]},"vanvliet":{"title":"Mum Işığında Triktrak Oynayanlar","artist":"Jan Gillisz. van Vliet","date":"1631–1634","place":"Hollanda (Leiden)","game":"Triktrak (tavlanın bir türü)","medium":"Asitle oyma ve gravür","size":"15,2 × 13,4 cm","credit":"","p":["Leiden’de Rembrandt’la birlikte çalışan Van Vliet’in bir baskısı. Müzeye göre solda cibinlikli bir yatak bulunan karanlık bir odada iki kişi triktrak oynuyor, sağda bir adam ve bir kadın var.","Siyahlı bir adam sırtı bize dönük, tahtaya iyice eğilmiş; rakibi elini tahtanın kenarına koymuş gülüyor. Haneler ve taşlar açıkça görülüyor. Işık kaynağı gizli, ama yalnızca tahta ve yüzler aydınlık; büyük olasılıkla gece oynanan bir oyun."],"spots":[["Tahta","Haneleri ve taşlarıyla triktrak tahtası."],["Gülen oyuncu","Eli tahtanın kenarında, gülüyor."],["Eğilen adam","Siyahlar içinde, sırtı dönük, tahtaya eğilmiş."],["Şapkalı adam","Arkada geniş kenarlı şapkasıyla duruyor."],["Kırma yakalı figür","Sağda, elini kaldırmış."],["Yatak perdeleri","Soldaki cibinlikli yatağın perdeleri."]]},"hermans":{"title":"Satranç Tahtasının Başında İki Kadın ve Bir Kız","artist":"François Hermans (stüdyo)","date":"1857–1895","place":"Hollanda (Rotterdam)","game":"Satranç","medium":"Albümin baskı (kartvizit fotoğraf)","size":"10,1 × 6,2 cm","credit":"","p":["Bir aile albümünden, arkasında stüdyonun adı “François Hermans / Hang 421 / Rotterdam” basılı kartvizit boyutunda bir fotoğraf. Büyük olasılıkla stüdyoda çekilmiş bir aile hatırası portresi.","Küçük yuvarlak bir masada satranç tahtası duruyor; soldaki kadın bir taşa dokunuyor, sağdaki kadın yanağını eline dayamış düşünüyor. Aralarında duran kız doğrudan bize bakıyor. Uzun pozlama boyunca üçü de kıpırdamadan durmuş olmalı."],"spots":[["Satranç tahtası","Yuvarlak masadaki tahta ve taşlar."],["Hamle yapan el","Soldaki kadın bir taşa dokunuyor."],["Kız","Tahtanın arkasında durup bize bakıyor."],["Düşünen kadın","Sağdaki kadın, eli yanağında."],["Ayak taburesi","Yerdeki yuvarlak tabure."],["Pencere","Sağ arkadaki kafesli pencere."]]},"norimberg":{"title":"Nürnberg Manzaralı Dama Taşı","artist":"Anonim","date":"1690","place":"Almanya (Nürnberg)","game":"Dama ya da tavla türü","medium":"Şimşir","size":"Çap 5,4 cm, kalınlık 1,5 cm","credit":"","p":["Kuleleri ve kalesiyle Nürnberg manzarası kabartma olarak oyulmuş şimşir bir dama taşı. Üstte “SVB AQVILAE ROMANAE ALIS QVIESCO” (Roma kartalının kanatları altında dinlenirim), altta “NORIBERGA VRBIVM REGINA” (şehirlerin kraliçesi Nürnberg) yazar.","Müze kaydına göre öbür yüzde İmparator I. Joseph ile yedi prens-seçicinin portreleri var. Büyük olasılıkla Kutsal Roma İmparatorluğu’nun imparatorluk şehri Nürnberg’in gururu bir oyun taşına oyulmuştur."],"spots":[["Şehir manzarası","Kilise kuleleri ve surlarıyla Nürnberg."],["Üst yazı","“SVB AQVILAE ROMANAE…”."],["Alt yazı","“NORIBERGA VRBIVM REGINA”."],["Amblem","En üstteki küçük işaret."],["Kale","Sağdaki tepedeki kale."],["Kenar","Taşın basamaklı kenarı."]]},"toovenaar":{"title":"Büyücü: Yeni ve Eğlenceli Bir Çocuk Oyunu","artist":"Anonim","date":"1856","place":"Hollanda (Amsterdam)","game":"Yarış oyunu (kaz oyunu akrabası)","medium":"Taş baskı ve matbaa metni, elle boyanmış","size":"44,5 × 53,5 cm","credit":"","p":["“DE TOOVENAAR” (Büyücü), “yeni ve eğlenceli bir çocuk oyunu” başlıklı, 1’den 63’e kadar kareleri sarmal dizilmiş bir yarış oyunu. Ortada kurukafa, kadeh, ay ve yıldızların durduğu bir masanın önünde bir büyücü, arkasında şeytani yaratıklar var; dört köşede hayvan başlı şeytanlar.","Ortaya basılı kurallar kaz oyununa çok benzer. İki zar atılır: ilk atışta altı ve üç gelen 26’ya, beş ve dört gelen 53’e gider. Büyücü karesi kaz gibi yeniden saydırır; köprü bir, han iki ve bir el kaybettirir, 42’deki labirent üç geri gönderir, Ölüm ise ödetip baştan başlatır."],"spots":[["Büyücü","Ortada masasının başındaki büyücü."],["Başlık ve kurallar","“DE TOOVENAAR” başlığı ve kurallar."],["63 hedefi","Sarmalın son karesi."],["Köşe şeytanları","Köşelerdeki hayvan başlı şeytanlar."],["Dış yol","Kenar boyunca resimli kareler."],["Masa","Masadaki kurukafa ve kadeh."]]},"fichesdoos":{"title":"Fişli Fildişi Kutu","artist":"Mariaval le Jeune","date":"1725","place":"Fransa (Paris)","game":"Kâğıt oyunları için fişler","medium":"Fildişi","size":"2 × 8 × 6 cm","credit":"","p":["Kâğıt oyunlarında para yerine kullanılan fişler için avuç içi büyüklüğünde fildişi bir kutu. Kapakta, bulutlar üstünde oturan taçlı, asalı bir kadın, yanında bir tavus kuşu ve iki arma var; tavus kuşuyla büyük olasılıkla tanrıça Juno’dur.","Müze kaydına göre kapakta “Mariaval le Jeune a Rouen fecit” yazar, alt yüzde bir kartal ve kuşlar, biri darağacına asılı. İçinde böcek ve çiçek resimli on dokuz büyük ve altı küçük fiş kalmış."],"spots":[["Taçlı kadın","Bulutlarda oturan taçlı kadın."],["Tavus kuşu","Ayaklarının dibindeki tavus kuşu."],["Armalar","Sağ üstteki iki arma."],["Küçük kuş","Yanındaki tünekte bir kuş."],["Bulutlar","Onu taşıyan bulutlar."],["Kapak kenarı","Kapağın kenarı ve kilidi."]]},"vuilmere":{"title":"Sanatçının Annesi Dama Oynarken","artist":"Édouard Vuillard","date":"y. 1890–91","place":"Fransa","game":"Dama","medium":"Fildişi velen kâğıt üzerine pastel, kurşun kalem, stump ve silme","size":"37,5 × 30,5 cm","credit":"","p":["Fransız ressam Vuillard’ın annesini çizdiği bir pastel. Vuillard annesiyle yaşadı ve onun terzilik yaptığı evin içinden sahneleri tekrar tekrar çizdi. Sağ altta “E Vuillard” imzası var.","Siyah giysili iki kişi parlak turuncu bir masanın iki yanında oturuyor; öndeki bir dama tahtası tutuyor. Müzenin başlığına göre burada sanatçının annesi resmedilmiştir. Siyah oval bir çizginin içinde insanlar ve eşyalar renk ve biçim kütlelerine karışır."],"spots":[["Tahta","Siyah beyaz kareli tahta."],["Arkadaki kişi","Masanın öbür yanındaki siyah giysili kişi."],["Öndeki kişi","Tahtayı tutan kişi."],["Turuncu masa","Resmi kaplayan parlak renk."],["Desenli duvar","Kıvrımlı çizgilerden duvar deseni."],["İmza","Sağ alttaki “E Vuillard”."]]},"dewitte":{"title":"Satranç Oynayan İki Adam","artist":"Adrien de Witte","date":"1877","place":"Belçika","game":"Satranç","medium":"Büyük olasılıkla asitle oyma","size":"13,2 × 12,5 cm","credit":"","p":["Liègeli Belçikalı ressam ve baskıcı de Witte’nin (1850–1935) küçük bir baskısı. Müzeye göre literatür (Clercx, 1981) iki oyuncunun Terme ve Zeyen olduğunu varsayar.","Örtülü bir masada genç adam kollarını kavuşturmuş tahtaya bakıyor, karşısındaki yaşlı adam başını eline dayamış düşünüyor. Tahtanın arkasında taş kutusuna benzeyen bir şey görülüyor. İnce taramalı karanlık odada sessiz bir oyun sürüyor."],"spots":[["Tahta ve taşlar","Masadaki tahta ve taşlar."],["Kutu","Tahtanın arkasında kutuya benzeyen şey."],["Genç adam","Kolları kavuşturmuş, tahtaya bakıyor."],["Yaşlı adam","Başı elinde, düşünüyor."],["Masa örtüsü","Masadaki kumaş."],["Sandalye","Solda bükme sandalyenin arkalığı."]]},"orphans":{"title":"Yetimler (Dama Oynayan Çocuklar)","artist":"Charles Rolls, W. Gill’den","date":"1810–1834","place":"İngiltere","game":"Dama","medium":"Baskı (gravür)","size":"22,6 × 13,9 cm","credit":"","p":["Altında “THE ORPHANS” (Yetimler) başlığı ve “Painted by W. Gill, Engraved by C. Rolls” yazısı olan bir baskı. Müzeye göre Londra’da yayımlanan yıllık armağan kitabı The Keepsake’te kullanılmış olabilir.","Bir mutfakta bir kız ve bir oğlan, bir fıçının üstüne konmuş tahtada dama oynuyor. Arkada bir kadın nakış işliyor, en arkada müzenin dokuma tezgâhı dediği bir alet var. Başlık, ikisinin kadının yanına aldığı yetimler olduğunu düşündürüyor."],"spots":[["Dama tahtası","Fıçının üstündeki tahta ve taşlar."],["Kız","Tahtaya eğilmiş bakıyor."],["Oğlan","Bir taşı sürüyor."],["Nakış işleyen kadın","Arkalarında nakış işliyor."],["Testi","Yerde bir testi."],["Başlık","Alttaki “THE ORPHANS”."]]},"richelieu":{"title":"XIII. Louis ve Richelieu","artist":"Jan Frederik Christiaan Reckleben","date":"1850","place":"Hollanda (Amsterdam)","game":"Satranç","medium":"Çelik gravür","size":"24,2 × 29,6 cm","credit":"","p":["Amsterdamlı gravürcü Reckleben’in, üstünde “1850. NEDERLANDSCH MUSEUM. Pl. II.” yazan bir çelik gravürü. Müzeye göre Nederlandsch Museum dergisindeki bir yazının resmi olabilir.","Büyük bir şöminenin önünde Fransa kralı XIII. Louis ile başbakanı Kardinal Richelieu satranç oynuyor, çevrelerinde adamlar toplanmış. Solda oturan kardinal bir taşa uzanıyor, tüylü şapkalı kral rahatça yaslanmış. En solda kollarını kavuşturmuş bir keşiş duruyor."],"spots":[["Satranç tahtası","Örtülü masada tahta ve taşlar."],["Richelieu","Bir taşa uzanan kardinal."],["XIII. Louis","Tüylü şapkalı kral."],["Keşiş","Kolları kavuşturmuş, soldan izliyor."],["Saray erkânı","Sağda toplanmış adamlar."],["Başlık","Alttaki “LODEWIJK DE XIII EN RICHELIEU”."]]},"coster":{"title":"Mum Işığında Triktrak Oynayan Adamlar (De Coster’den)","artist":"Adam de Coster’den (oyan Vorsterman)","date":"1619–1628","place":"Flandre","game":"Triktrak (tavlanın bir türü)","medium":"Gravür","size":"37,1 × 35,1 cm","credit":"","p":["Mum ışığı sahneleriyle tanınan Flaman ressam Adam de Coster’in bir tablosundan yapılmış baskı; altta “A. De Coster pi.” ve “Vorsterman” yazar. Müzeye göre iki adam bir masanın başında ayakta mum ışığında triktrak oynuyor.","Solda piposuyla bir adam izliyor; sağda bir kız ud çalıyor, şapkalı bir adam mumu gösteriyor. Öndeki oyuncu sırtı bize dönük masaya eğilmiş, rakibi elini tahtanın üstünde tutuyor. Tek bir mum sahneyi aydınlatıyor, yalnızca yüzleri ve elleri ortaya çıkarıyor."],"spots":[["Tahta","Masada yarı gölgede kalan tahta."],["Mum","Sahneyi aydınlatan tek mum."],["Sırtı dönük oyuncu","Masaya eğilmiş."],["Rakip","Elini tahtanın üstünde tutuyor."],["Pipolu adam","Solda piposuyla izliyor."],["Ud çalan kız","Sağda ud çalan kız."]]},"kiebitz":{"title":"Kiebitz (Oyun Seyircisi)","artist":"Hans Watzek","date":"1894","place":"Büyük olasılıkla Avusturya","game":"İskambil","medium":"Tram baskı (kitap resmi)","size":"10,0 × 12,1 cm","credit":"","p":["Viyanalı sanat fotoğrafçısı Hans Watzek’in bir fotoğrafı; sağ üstte “HANS WATZEK 94” imzası var. Sayfa başlığı “Fotoğraf bir sanat mıdır?” olan bir kitaba tram baskıyla basılmış bir resim.","Almanca başlık “Kiebitz” kız kuşu demektir; argoda iskambil oyununa karışan seyirciyi de anlatır. Şapkalı bir adam kâğıtlarına bakarken öndeki uzun pipolu adam yandan bakıyor. Kumlu, resim gibi ton, resme yaklaşmak isteyen dönemin sanatsal fotoğrafına özgüdür."],"spots":[["Kâğıtlar","Sağdaki adamın baktığı kâğıtlar."],["Oyuncu","Melon şapkalı, ağzında pipo."],["Seyirci","Uzun pipolu adam, büyük olasılıkla başlıktaki “Kiebitz”."],["Bira bardağı","Masadaki cam bira bardağı."],["İmza","Sağ üstteki “HANS WATZEK 94”."],["Altyazı","Alttaki “HANS WATZEK. — KIEBITZ.”."]]},"evdvelde":{"title":"Şato Bahçesinde Triktrak Oynayanlar","artist":"Esaias van de Velde","date":"1630","place":"Hollanda","game":"Triktrak (tavlanın bir türü)","medium":"Siyah tebeşir ve gri lavi","size":"18,5 × 30,1 cm","credit":"","p":["Hollanda tür ve manzara resminin öncülerinden Esaias van de Velde’nin (1587–1630) bir desen çalışması; sağ altta “E.V.VELDE” imzası var. Müzeye göre şık bir topluluk bir şato bahçesinde masada triktrak oynuyor.","Tahtaya eğilmiş bir adamla oturan bir adam karşılıklı oynuyor, arkada hanımlar izliyor. Sol önde iki testili bir şarap soğutucusu, onun gerisinde bir çeşme başında bir oğlan ve bir tavus kuşu var. Açık havada oyunla geçen zarif bir öğleden sonra."],"spots":[["Tahta","Masadaki triktrak tahtası."],["Eğilen adam","Şapkalı, tahtaya eğilmiş."],["Oturan adam","Bacak bacak üstüne atmış, tahtanın başında."],["İzleyen hanımlar","Arkada ayakta oyunu izliyorlar."],["Tavus kuşu ve oğlan","Çeşme başında tavus kuşu ve oğlan."],["Şarap soğutucusu","Sol önde soğutucu ve iki testi."]]},"cooghen":{"title":"Triktrak Oynayan İki Adam","artist":"Leendert van der Cooghen","date":"1666","place":"Hollanda (Haarlem)","game":"Triktrak (tavlanın bir türü)","medium":"Asitle oyma baskı","size":"9,3 × 15,6 cm","credit":"","p":["Haarlemli ressam Van der Cooghen’in bir baskısı; tahtanın üstündeki duvara “1666” yılı kazınmış. Müzeye göre bir meyhanede iki adam masada triktrak oynuyor, bir kadın soldaki adamın omzunun üstünden bakıyor.","Soldaki yaşlı adam kürk kenarlı bir ceket giymiş, uzun bir kadeh tutuyor; sağdaki genç adamda gösterişli tüylü bir şapka var. Pencerede küçük bir maymun oturuyor. Tahtanın kenarı ve haneleri açıkça çizilmiş."],"spots":[["Tahta","Masadaki triktrak tahtası."],["Yaşlı adam","Kürk kenarlı ceketli."],["Kadeh","Yaşlı adamın elindeki uzun kadeh."],["Bakan kadın","Soldaki adamın omzunun üstünden bakıyor."],["Maymun","Pencerede küçük bir maymun."],["Tüylü şapkalı adam","Tüylü şapkalı genç oyuncu."]]},"roybet":{"title":"Satranç Oyuncusu","artist":"Ferdinand Roybet","date":"1875","place":"Fransa (Paris)","game":"Satranç","medium":"Büyük olasılıkla asitle oyma","size":"26,1 × 19,6 cm","credit":"","p":["17. yüzyıl şövalyelerini resmetmeyi seven Fransız ressam Roybet’in hem çizip hem oyduğu bir baskı (sol altta “F. Roybet del. et sc.”). Altta “LE JOUEUR D’ÉCHECS” başlığı, sağda yayıncı Cadart’ın adı var.","Tüylü şapkalı, belinde kılıçlı bir adam bir sıraya yan oturmuş, taşlara uzanıyor. Rakip görünmüyor; konumu tek başına düşünüyor gibi. Arkadaki rafta bir maşrapa, bir sürahi ve kadehler var."],"spots":[["Tahta ve taşlar","Sıradaki tahta ve taşlar."],["Şövalye","Tüylü şapkalı adam."],["Uzanan el","Bir taşa uzanan eli."],["Kılıç","Belindeki uzun kılıç."],["Raftaki kaplar","Maşrapa, sürahi ve kadehler."],["Başlık","“LE JOUEUR D’ÉCHECS”."]]},"capot":{"title":"“Aziz Petrus, Dostum, Kapot Oldunuz!” (Ressam ve Modeli İskambilde)","artist":"Anonim (Aubert & Cie yayını)","date":"1838","place":"Fransa (Paris)","game":"İskambil (büyük olasılıkla piket)","medium":"Taş baskı","size":"30,5 × 22,2 cm","credit":"","p":["Paris’in mizah gazetesi Le Charivari’nin 9 Eylül 1838 sayısında kullanılmış bir taş baskı; “Les Artistes” dizisinin 13 numarası. Alt yazı: “St. Pierre, mon ami, vous êtes capot!”","Müzeye göre ressam, kâğıt ortağına “Aziz Petrus” diyor, çünkü adam tablodaki azize modellik ediyor. “Kapot” olmak pikette hiç el alamadan yenilmektir; oynanan oyun büyük olasılıkla piket."],"spots":[["Masadaki kâğıtlar","Küçük masaya oynanmış kâğıtlar."],["Model","Sırtı dönük uzun saçlı adam; saçı ve sakalı tablodaki aziz gibi, büyük olasılıkla model."],["Ressam","Sağda elinde kâğıtlarla duran adam, büyük olasılıkla ressam."],["Aziz tablosu","Şövalede yarım kalmış aziz."],["Tabure","Modelin oturduğu tahta tabure."],["Alt yazı","“St. Pierre, mon ami, vous êtes capot!”"]]},"ziacard":{"title":"Sinek Papazı (Zia Pueblo valisi Antonio Salva)","artist":"Adam Clark Vroman (fotoğraf), Lazarus & Melzer (yayıncı)","date":"1900","place":"Amerika Birleşik Devletleri (Los Angeles)","game":"İskambil","medium":"Otoipi (tram baskı)","size":"8,8 × 6,3 cm","credit":"","p":["Müze kaydına göre bu, Yerli Amerikalıların fotoğraflarıyla tram baskı basılmış, jokeri de içeren 53 kartlık kutulu bir destenin bir kartıdır. Fotoğraflar Adam Clark Vroman’ın, yayıncı Los Angeles’taki Lazarus & Melzer’dir.","Sinek papazında çizilmiş bir kral yerine, New Mexico’daki Zia Pueblo’nun valisi Antonio Salva’nın portresi var. Altta adı ve unvanı, köşelerde K ve sinek işareti basılı. Batı’yı ziyaret edenler için bir hatıra olarak yapıldığı düşünülüyor."],"spots":[["Köşe işareti","Sol üstte K ve sinek, her destedeki gibi."],["Valinin yüzü","Yana bakan Antonio Salva."],["Uzun saçlar","Omuza inen saçlar ve düz kesilmiş perçem."],["Boyun bezi","Beyaz gömleğin yakasına bağlanmış bez."],["Ad ve unvan","Basılı: “Antonio Salva. Governor Pueblo of Sia.”"],["Ters köşe işareti","Sağ altta ters duran K ve sinek."]]},"gothink":{"title":"Go oynayanlar","artist":"Japon fotoğrafçı (adı bilinmiyor)","date":"1887–1897","place":"Japonya","game":"Go","medium":"Elle boyanmış fotoğraf (kitap resmi)","size":"8,8 × 13 cm","credit":"","p":["Adı bilinmeyen bir Japon fotoğrafçının çektiği ve Japonya’da elle boyanan bu fotoğraf, Japonya üzerine İngilizce bir kitabın 65. sayfasına yapıştırılmış. Altta basılı açıklama şöyle: “Go satrançtan daha zor bir oyundur. 8. yüzyılda Çin’den Japonya’ya geldi.”","Ayaklı bir go tahtasının başında soldaki kadın taş koyarken, beyaz sakallı yaşlı adam elini başına götürmüş düşünüyor. Ortadaki kadın tahtayı izliyor; önde bir tepsi tatlı ve çay kâseleri var. Muhtemelen yabancı ziyaretçiler için stüdyoda kurgulanarak çekildi."],"spots":[["Tahta","Taşlarıyla ayaklı bir go tahtası."],["Taş koyan el","Soldaki kadın tahtaya uzanıyor."],["Düşünceli yaşlı adam","Beyaz sakallı, eli başında."],["İzleyen kadın","Ortada, çizgili kimonolu."],["Tatlı tepsisi","Önde tepside tatlılar."],["Taş kâsesi","Tahtanın yanında kapaklı taş kâsesi."]]},"craps":{"title":"Küçük Kumarbazlar","artist":"Francis A. Place","date":"1888–1893","place":"Muhtemelen Amerika Birleşik Devletleri","game":"Zar","medium":"Fotoğraf (kitap resmi)","size":"14 × 9,9 cm","credit":"","p":["Müze kaydına göre kimliği bilinmeyen dört oğlan zar oynuyor; fotoğrafçı Francis A. Place’in adı kartonda basılı. Bir kitabın 142. sayfasından iki sayfa önce yapıştırılmış ve üzerinde “Amerikan ‘Aristo’ kâğıdına basılmıştır” ile “Williams flaş aygıtıyla çekilmiştir” yazıları var. Muhtemelen kâğıdın ve flaşın örneği olarak kullanıldı.","Yere saman serili bir duvarın önünde oğlanlar bir sandığın çevresinde. Sandığın üstünde teneke bir tabak ve iki zar var. Sağdaki oğlan parmak şıklatıyor, yerde oturan çenesini eline dayamış bakıyor. Altta kazınmış “COME SEV” yazısı, Amerikan zar oyunu crapste “gel yedi!” diye bağırılan söz olmalı."],"spots":[["İki zar","Sandığın üstündeki iki zar."],["Teneke tabak","Sandıktaki tabak, muhtemelen bahis için."],["Parmak şıklatan oğlan","Sağdaki oğlan zarlara parmak şıklatıyor."],["Oturan oğlan","Yerde, çenesi elinde."],["“COME SEV”","Altta kazınmış harfler: muhtemelen “gel yedi!”."],["Sandıktaki yazı","Sandığın yanına basılmış harfler."]]},"bikkel":{"title":"Aşık Kemiği Oynayan Bir Adam Etüdü","artist":"Jan Baptist Weenix (olası)","date":"1642–1647","place":"İtalya (Roma)","game":"Aşık kemiği oyunu","medium":"Mavi kâğıt üzerine siyah ve beyaz tebeşir","size":"26,7 × 18,0 cm","credit":"","p":["Mavi kâğıda siyah ve beyaz tebeşirle yapılmış bir desen. Müzeye göre büyük olasılıkla Hollandalı ressam Weenix’in Roma yıllarından; bir zamanlar Anthonie Palamedesz’in eseri olarak satılmış.","Şapkalı bir adam iyice eğilmiş, ellerine bakıyor; ayaklarının dibinde yerde birkaç küçük kemik var. Koyun gibi hayvanların aşık kemiklerini atıp tutmak çok eski bir oyundur ve sık sık zarın atası diye anılır."],"spots":[["Yüz","Şapkanın altından ellerine bakıyor."],["Eller","Büyük olasılıkla kemikleri atmak üzere."],["Yerdeki kemikler","Yerde küçük kemikler."],["Ayakkabı","Sağlam basan ayak."],["Beyaz tebeşir","Işığı veren beyaz tebeşir."],["Pelerin","Sırtındaki pelerin."]]},"stukken":{"title":"Satranç Taşları Tasarımı","artist":"Anonim (Fransa)","date":"1850–1875","place":"Fransa","game":"Satranç","medium":"Kalem ve siyah mürekkep, siyah tebeşir taslak üzerine beyaz ve turuncu-kırmızı guaş, mavi kâğıt","size":"26,5 × 20,0 cm","credit":"","p":["Kimliği bilinmeyen bir Fransız çizerin yaptığı bir satranç takımı tasarımı. İki sırada beşer taş türü var: şah, vezir, kale, insan biçimli bir taş ve at.","Üst sırada taçlı kral ve kraliçe ile mızraklı, diz çökmüş bir asker; alt sırada sarıklı kral, peçeli kraliçe ve diz çökmüş okçu var: iki taraf büyük olasılıkla Batı ve Doğu orduları olarak düşünülmüş. Beyaz ve turuncu-kırmızı boya oyma ve parlaklığı gösteriyor."],"spots":[["Şah (üst)","Taçlı, asalı."],["Vezir (üst)","Taçlı kraliçe."],["Kule","Kale olarak kule."],["Mızraklı asker","Diz çökmüş, mızraklı taş."],["Sarıklı şah","Alt sıranın şahı."],["Okçu","Yay geren, diz çökmüş taş."]]},"rozetempel":{"title":"Çiçek Bahçesi ya da Eğlenceli Gül Tapınağı (zar oyunu tahtası)","artist":"Anonim (Hendrik Moolenyzer yayını)","date":"1792–1847","place":"Hollanda (Amsterdam)","game":"Zar oyunu tahtası","medium":"Baskı","size":"46,1 × 39,6 cm","credit":"","p":["Amsterdamlı yayıncı Moolenyzer’in tek yaprak oyun tahtası; üstte “BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL” (Çiçek Bahçesi ya da Eğlenceli Gül Tapınağı) başlığı var.","Ortadaki “ROZE TEMPEL”in içinde bir vazo gül, çevresinde halka hâlinde zar çiftleri ve çiçekler var. Büyük olasılıkla iki zar atılır, atışa denk gelen çiçekte bahis ödenir ya da alınırdı."],"spots":[["Başlık","“BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL”."],["Gül tapınağı","Ortadaki “ROZE TEMPEL”."],["Zar çiftleri","İki zarın birleşimleri."],["Gül vazosu","Tapınaktaki vazoda güller."],["Lale","Halkadaki çiçeklerden biri."],["Yayıncı","“Te AMSTERDAM bij H. Moolenyzer”."]]},"brelan":{"title":"Le Brelan (Çocukluk Oyunları’ndan)","artist":"Claudine Stella (Jacques Stella’dan)","date":"1657","place":"Fransa (Paris)","game":"Brelan (üç kâğıtlı oyun)","medium":"Gravür","size":"12,0 × 14,2 cm","credit":"","p":["51 çocuk oyunu sahnesini toplayan Les Jeux et plaisirs de l’enfance albümünden bir levha. Dizelerin üstünde “LE BRELAN” yazıyor; tombul çocuklar yere oturmuş kâğıt oynuyor.","Dizeler, birinin çemberini yuvarladığını, ötekilerin bir yığın hâlinde kâğıtla şanslarını denediğini, kazanacağını sanan birinin ise cebi hafiflemiş gittiğini anlatıyor. Brelan sık sık pokerin uzak atalarından biri sayılır."],"spots":[["Eldeki kâğıtlar","Kâğıtlarını yelpaze gibi açan çocuk."],["Yerdeki kâğıt","Yerde “A” işaretli bir kâğıt."],["Bakan çocuk","Arkadan kâğıtlara bakan çocuk."],["Çember","Sopayla çember çeviren çocuk."],["Kule","Arkadaki yuvarlak kule."],["Başlık","“LE BRELAN” ve dizeler."]]},"pwkarte":{"title":"Altı Papağanlı Yuvarlak Oyun Kâğıdı","artist":"Kölnlü Usta PW","date":"1470–1500","place":"Almanya (Köln)","game":"Oyun kâğıtları (yuvarlak deste)","medium":"Gravür","size":"Çap 7,0 cm","credit":"","p":["Beş yüz yıldan uzun süre önce gravürle basılmış yuvarlak bir oyun kâğıdı. Müzeye göre gül, hasekiküpesi, karanfil, papağan ve tavşandan oluşan beş renkli, 70 yuvarlak kâğıtlık bir destenin parçası.","Her renkte 1’den 10’a numaralı on kâğıt ve figürlü dört kâğıt vardı. Bu, papağan altılısı: üstte Arap rakamıyla “6”, altta Roma rakamıyla “VI” var; altı papağan ortadaki süsün çevresinde dönüyor."],"spots":[["“6”","Üstteki Arap rakamı."],["“VI”","Alttaki Roma rakamı."],["Üstteki papağan","Dala konmuş gibi."],["Kanat çırpan papağan","Kanatları açık."],["Ters papağan","Başı aşağıda."],["Ortadaki süs","Işık saçan orta süs."]]},"nilson":{"title":"Tahta Oyunu (Dama ve Tokadil)","artist":"Johann Esaias Nilson","date":"1731–1788","place":"Almanya (Augsburg)","game":"Dama ve tokadil","medium":"Asitle oyma ve gravür","size":"18,9 × 28,8 cm","credit":"","p":["Augsburglu gravürcü Nilson’un tasarlayıp yayımladığı rokoko çerçeveli bir baskı; üstte “Das Bretspiel” (Tahta Oyunu) yazıyor. Dört baskılık bir dizinin üçüncüsü.","Müzeye göre soldaki masada bir adamla bir kadın dama oynuyor, sağdaki masada iki adam tavla ailesinden bir oyun olan tokadil oynuyor. Almanca dize, tokadil oynayanın kazanmaya hevesli olduğunu, dama oynayanın ise bütün duyularına ihtiyaç duyduğunu söylüyor."],"spots":[["Dama tahtası","Soldaki masada."],["Tokadil tahtası","Sağdaki küçük masada."],["Mektup okuyan","Pipo içerek mektup okuyan adam."],["Tabaklı kadın","Sağda tabak taşıyor."],["Park manzarası","Süslü çerçevenin ardındaki park."],["Dize","“Wer Tocadille spielt…”."]]},"chateau":{"title":"Kâğıttan Şato","artist":"François Joullain (Charles-Antoine Coypel’den)","date":"1725","place":"Fransa (Paris)","game":"İskambil (kâğıttan ev)","medium":"Gravür","size":"23,2 × 15,8 cm","credit":"","p":["Joullain’in ressam Coypel’in tasarımından oyup Paris’te Duchange’ın yayımladığı bir baskı. Yerdeki bir kâğıtta “CH. COYPEL” adı var.","Süslü giyimli bir çocuk masada iskambil kâğıtlarından şato kuruyor, arkadaki oğlan parmağını dudağına koymuş izliyor. Altındaki dizeler kâğıt oyuncularına takılıyor: en küçük rüzgâra yenik bir şato kuran bu çocuklara gülen, kâğıdı başka işe hiç kullanmasaydı bilge sayılırdı."],"spots":[["Kâğıttan şato","Masada üst üste kâğıtlar."],["Eldeki kâğıtlar","Çocuğun tuttuğu kâğıtlar."],["Şatoyu kuran","Tüylü takkeli çocuk."],["İzleyen oğlan","Parmağı dudağında."],["Yerdeki kâğıt","“CH. COYPEL” yazılı yaprak."],["Dizeler","“Tel qui rit, voyant ces Enfans…”."]]},"pugillus":{"title":"Zarda Her Şeyini Kaybetmiş Genç ve Şık Kadın","artist":"Jacob van der Heyden (olası)","date":"1608–1618","place":"Fransa (Strazburg)","game":"Zar","medium":"Gravür","size":"9,0 × 13,2 cm","credit":"","p":["Öğrencilere yönelik “Pugillus facetiarum iconographicarum” (bir avuç resimli şaka) dizisinden bir levha; müzeye göre büyük olasılıkla 36 ya da daha fazla baskıdan oluşuyordu.","Solda yelpazeli, şık giyimli bir kadın; sağda üstü başı yırtık bir genç şapkasını kaldırmış, yerdeki iki zara ve boş keseye bakıyor. Alt yazılar — kabaca “gözün cenneti, ruhun cehennemi, kesenin arafı” ve “hiç nakit para yok, pantolon hep yırtık” — aşk maceralarıyla ve kumarla alay ediyor."],"spots":[["Şık kadın","Kürk şapkalı, uzun giysili."],["Yelpaze","Elindeki tüy yelpaze."],["Genç adam","Selam verir gibi şapkasını kaldırıyor."],["Yırtık giysiler","Paramparça ceket ve pantolon."],["Zarlar ve kese","Yerde iki zar ve boş bir kese."],["Alt yazı","“Nunquam bar gelt, semper zerrissen hosen”."]]},"grootebroek":{"title":"Grootebroek Piyangosu","artist":"Cornelis Dusart","date":"1694–1695","place":"Hollanda (Haarlem / Amsterdam)","game":"Piyango","medium":"Mezzotint ve gravür","size":"25,1 × 19,5 cm","credit":"","p":["20 Ağustos 1694’te Enkhuizen yakınlarındaki Grootebroek köyünde büyük bir yangın çıktı ve felaketzedeler yararına bir piyango düzenlendi. Dusart’ın bu baskısını Amsterdam’da Jacob Gole yayımladı.","Müzeye göre bir adam kazananlara bir kazan ve mühürlü bir mektup getiriyor. Başlık kabaca “büyük ikramiyelerin eve ne sevinçle getirildiğini gösteren” anlamına geliyor: borazan çalan adam, kazanı havaya kaldıran adam ve pencerede ellerini kaldıran kadın kazanmanın coşkusunu yansıtıyor."],"spots":[["Mühürlü mektup","Kazananlara getiriliyor."],["Kazan","İkramiye kazanını kaldıran adam."],["Borazan","Haberi borazanla duyuran adam."],["Penceredeki kadın","Şaşkınlıkla ellerini kaldırmış."],["Eğlenenler","Sağda içip kutlayanlar."],["Başlık","“Lottery van Groottenbroek”."]]},"narren":{"title":"Zar Oynayan İki Soytarı (Erasmus’un Deliliğe Övgü’sünden)","artist":"Caspar Merian (Hans ve Ambrosius Holbein’in desenlerinden)","date":"1516 (desenler)","place":"İsviçre (Basel)","game":"Zar","medium":"Asitle oyma baskı","size":"5,5 × 6,0 cm","credit":"","p":["Erasmus’un Deliliğe Övgü kitabı için minik bir resim. Holbein kardeşler bu sahneleri 1516’da bilgin Oswald Myconius’un nüshasının kenarlarına çizmişti; Merian bunları 1676’da Basel’de basılan baskı için oydu.","Çıngıraklı soytarı külahlı bir adamla kukuletalı bir adam, üstünde üç zar duran yuvarlak bir masada zar atıyor. Çıplak ayaklar, kumara kapılmış budalaların resmini tamamlıyor."],"spots":[["Zarlar","Masada üç zar."],["Külahlı soytarı","Solda öne eğilmiş."],["Çıngıraklar","Külahın uçlarında."],["Kukuletalı adam","Sağda rakibine bakıyor."],["Kukuletanın çıngırağı","Kukuletanın ucunda."],["Çıplak ayaklar","Masanın altında."]]},"historiespel":{"title":"Vatan Tarihi Oyunu","artist":"Johannes Christiaan Bendorp","date":"1816","place":"Hollanda (Amsterdam)","game":"Yarış oyunu (kaz oyunu türü)","medium":"Asitle oyma ve gravür","size":"50,3 × 61,0 cm","credit":"","p":["Hollanda tarihinde dolaşan bir tahta oyunu; yayıncısı Amsterdam’dan Gartman. Müzeye göre kaz oyunu düzeninde 1’den 80’e numaralı hanesi var: 1 Batavi isyanı, 80 Amsterdam denizcilik okulu.","1787 tarihli bir sürümün uyarlaması; 70–79. hanelerdeki olaylar değiştirilmiş, en yeni olay 1816’dan. Oyunla birlikte ayrı bir açıklama yaprağı veriliyordu. Haneler savaş sahneleri ve kahraman portreleriyle dolu: oynayarak tarih öğrenmek için."],"spots":[["Başlangıç: 1","Sol alttaki hane."],["Bitiş: 80","Ortadaki denizcilik okulu."],["Başlık","“VADERLANDSCH HISTORIESPEL”."],["Portreli hane","Bir portre bulunan hane."],["70’li haneler","İç halkadaki haneler."],["Yayıncı","“HENDRIK GARTMAN”."]]},"daumier":{"title":"Asla Polis Gözetimine Alınmayacak Parisliler","artist":"Honoré Daumier","date":"1847","place":"Fransa (Paris)","game":"Dama","medium":"Taş baskı","size":"29,7 × 22,6 cm","credit":"","p":["Karikatürist Daumier’nin bir taş baskısı; Paris gazetesi Le Charivari’nin 25 Ağustos 1847 sayısında kullanılmış. Üstte dizinin adı “TOUT CE QU’ON VOUDRA” (Ne isterseniz) ve 12 numarası var.","Bir odadaki küçük masada iki yaşlı adam dama oynuyor, üçüncüsü elini çenesine dayamış, aradaki tahtaya bakıyor. Alt yazı “Asla yüksek polisin gözetimine alınmayacak Parisliler” diyor; büyük olasılıkla bu zararsız yaşlılara tatlı bir takılma."],"spots":[["Tahta","Masadaki dama tahtası."],["Hamle yapan","Solda taşa uzanıyor."],["Seyirci","Ortada, eli çenesinde."],["Sağdaki oyuncu","Tahtaya dikkatle bakıyor."],["Duvardaki resim","Arka duvarda bir çerçeve."],["Alt yazı","“Parisiens qui ne seront jamais placés…”."]]},"arnauts":{"title":"Dama Oynayan Arnavutlar","artist":"Henry Augustin Valentin (Jean-Léon Gérôme’dan)","date":"1856–1886","place":"Fransa (Paris)","game":"Dama","medium":"Baskı (büyük olasılıkla asitle oyma)","size":"21,7 × 27,0 cm","credit":"","p":["Valentin’in Fransız ressam Gérôme’un tablosundan yaptığı, Paris’te Goupil & Cie’nin yayımladığı bir baskı; altta “ARNAUTES JOUANT AUX DAMES” yazıyor. Arnavutlar (Arnaut), Osmanlı İmparatorluğu hizmetindeki Arnavut askerlerdi.","Müzeye göre iki Arnavut bir sedirde karşılıklı oturmuş dama oynuyor. Soldaki, etek gibi pileli bir giysiyle elindeki bir şeyle oynuyor; sağdaki ağzında uzun bir çubukla tahtaya eğilmiş. Solda duvarda Gérôme’un imzası görülüyor."],"spots":[["Tahta","İkisinin arasındaki dama tahtası."],["Soldaki adam","Pileli giysiyle oturuyor."],["Elleri","Bir şeyle oynuyor."],["Sağdaki adam","Tahtaya eğilmiş."],["Çubuk","Ağzındaki uzun tütün çubuğu."],["İmza","Duvarda Gérôme’un imzası."]]},"luyken":{"title":"Tütün İçip Satranç Oynayan Türkler","artist":"Jan Luyken","date":"1698","place":"Hollanda (Amsterdam / Delft’te yayımlandı)","game":"Satranç","medium":"Asitle oyma ve gravür","size":"30,5 × 19,1 cm","credit":"","p":["Luyken’in, gezgin Cornelis de Bruyn’ün Küçük Asya seyahatnamesinin (Delft, 1698) 136. sayfası için oyduğu bir resim. Tek levhada iki sahne var: üstte A, altta B.","Üstteki sahnede sarıklı altı adam uzun çubuklarla tütün içiyor, ikisi halının üstünde satranç oynuyor; alttaki sahnede dört kadın kahve içiyor, bir hizmetçi bekliyor. Sekinin önünde çıkarılmış pabuçlar sıra sıra duruyor."],"spots":[["Tahta","Halıdaki satranç tahtası."],["Oyuncu","Bir taşa uzanıyor."],["Eğilen adam","Tahtaya bakıyor."],["Çubuklar","Uzun tütün çubukları."],["Pabuçlar","Önde sıralanmış pabuçlar."],["Penceredeki ağaçlar","Pencerelerin ardındaki ağaçlar."]]},"kabinet":{"title":"Kâğıt Oynayanlar","artist":"Amsterdam Kabinesi Ustası","date":"1483–1487","place":"Almanya","game":"İskambil","medium":"Kuru iğne","size":"13,1 × 12,0 cm","credit":"","p":["Bakıra doğrudan iğneyle kazınan kuru iğne tekniğinin erken bir başyapıtı; sanatçı “Amsterdam Kabinesi Ustası” diye anılır. Müzeye göre yalnızca dört baskısı kalmış; ötekiler Coburg, Münih ve Oxford’da.","Açık havada şık giyimli genç bir kadın üç genç ve bir soytarı arasında oturuyor, kucağında bir kâğıt var. Soytarı ve sağ arkadaki çeşme, bir “aşk bahçesi” sahnesi olduğunu düşündürüyor. Önde bir köpek oturuyor."],"spots":[["Genç kadın","Kucağında bir kâğıt."],["Kâğıt","Kadının kucağında."],["Soldaki genç","Onunla konuşuyor."],["Soytarı","Yere uzanmış."],["Köpek","Önde oturuyor."],["Çeşme","Sağ arkada."]]},"lievens":{"title":"Kavga Eden Kâğıt Oyuncuları ve Ölüm","artist":"Jan Lievens","date":"1638","place":"Flandre (Anvers)","game":"İskambil","medium":"Asitle oyma baskı","size":"19,7 × 25,9 cm","credit":"","p":["Rembrandt’ın gençlik arkadaşı Jan Lievens’in kendi tablosundan oyduğu, Anvers’te Frans van den Wyngaerde’nin yayımladığı bir baskı.","Müzeye göre iki kâğıt oyuncusu birbirine girmiş: sağdaki yaşlı adam bir testiyi silah gibi savuruyor, rakibi kâğıtların durduğu masayı devirmiş, bıçaklı bir el havaya kalkmış. Ölüm araya girip soldaki adamı gırtlağından yakalıyor ve bir kemik sallıyor. Alttaki Latince söz, ölüm karşısında insan kavgalarının boşluğunu anlatıyor."],"spots":[["Ölüm","Araya giren iskelet."],["Kemik","Ölüm’ün salladığı kemik."],["Bıçak","Havaya kalkmış."],["Testi","Yaşlı adamın savurduğu."],["Yerdeki kâğıtlar","Dağılmış kâğıtlar."],["Söz","“Rixas atque odia…”."]]},"sorgheloos":{"title":"Kumar (Sorgheloos’un Öyküsünden)","artist":"Cornelis Anthonisz. (oyma ve yayın: Jan Ewoutsz.)","date":"1541","place":"Hollanda (Amsterdam)","game":"Parasına kâğıt oyunu","medium":"Elle renklendirilmiş ağaç baskı","size":"39,5 × 28,9 cm","credit":"","p":["Tasasız genç Sorgheloos’un düşüşünü anlatan, elle boyanmış altı ağaç baskının dördüncüsü. Figürlerin üstünde ad şeritleri var, altta Felemenkçe iki şiir basılı.","Müzeye göre Sorgheloos, kolunu Weelde’nin (Lüks) omzuna atmış, seyyar satıcı Lichte Fortune (Dönek Talih) ile kumar oynuyor; solda Ghemack (Rahatlık) oturuyor. Sağdan pejmürde bir çift, Armoede (Yoksulluk) ve Pover (Sefalet), giriyor: talih dönmek üzere."],"spots":[["Kâğıtlar ve paralar","Yeşil masada."],["Sorgheloos","Tasasız genç."],["Lüks","Kolundaki kadın."],["Rahatlık","Solda oturan adam."],["Dönek Talih","Sırtında sandık taşıyan satıcı."],["Yoksulluk ve Sefalet","Sağdan giren çift."]]},"aleabelli":{"title":"Savaş Oyunu (Kuzey Savaşı Alegorisi)","artist":"Anonim (büyük olasılıkla Crispijn van de Passe II)","date":"1656","place":"Hollanda","game":"Triktrak (tavlanın bir türü)","medium":"Asitle oyma, gravür ve tipo baskı","size":"38,8 × 35,5 cm","credit":"","p":["1656 Kuzey Savaşı’nı hicveden bir baskı; altına dört sütunlu bir metin yaprağı yapıştırılmış. Masa örtüsünde “ALEA BELLI” (savaşın zarı) yazıyor.","Müzeye göre İsveçli ile Danimarkalı triktrak oynuyor; çevrelerinde başka figürler ve ucunda “Aurea Libertas” şapkası olan bir mızrak var. Sağda Hollandalı bir denizci delik bir hazine sandığına para döküyor, önde domuzlar kesilmeyi ya da İsveç’e götürülmeyi bekliyor. Uzakta Kronborg şatosu ve bir kuyruklu yıldızdan uzanan Tanrı’nın eli görünüyor."],"spots":[["Tahta","Masadaki triktrak tahtası."],["ALEA BELLI","Örtüdeki yazı."],["Özgürlük şapkası","Mızraktaki “Aurea Libertas”."],["Delik sandık","Denizcinin para sandığı."],["Domuzlar","Ön planda."],["Kuyruklu yıldız","Sağ üstte, Tanrı’nın eliyle."]]},"shunman":{"title":"Şiir Kartları ve Kutuları (surimono)","artist":"Kubota Shunman","date":"1806","place":"Japonya (Edo)","game":"Şiir kartları (Hyakunin isshu)","medium":"Renkli ağaç baskı (surimono)","size":"16,1 × 21,3 cm","credit":"","p":["Bir surimono: resimle şiiri birleştiren, çoğu kez hediye olarak yapılan lüks bir baskı. Kubota Shunman imzalı; Nakasandō, Tago no Ishibumi ve Naokoto Shibaura’nın şiirleri basılı.","Müzeye göre beyaz kasımpatı desenli, açılmış ahşap bir kutunun önünde ünlü şairleri ve şiirlerinden bir parçayı gösteren birkaç kart duruyor. Bunlar Hyakunin isshu’ya (Yüz Şairden Birer Şiir) dayanan bir şiir oyununun kartları; sol üstteki üç şiirin her biri resimdeki üç karttan birine gönderme yapıyor."],"spots":[["Kasımpatılı kutu","Beyaz kasımpatılı ahşap kutu."],["Kartlar","Dizeli kartlar."],["Şair kartı","Bir şair resmi taşıyan kart."],["Üç şiir","Sol üstte basılı."],["İmza ve mühür","Sağ üstte Shunman’ın imzası."],["Örtü","Altta koyu kırmızı bir örtü."]]},"mitelli":{"title":"Meslekler Oyunu: Kimin İşi Rast Gider, Kiminki Ters","artist":"Giuseppe Maria Mitelli","date":"1698","place":"İtalya (Bologna)","game":"Zar oyunu tahtası","medium":"Asitle oyma baskı","size":"32,6 × 43,8 cm","credit":"","p":["Bolonyalı Mitelli’nin tasarlayıp oyduğu bir zar oyunu. Başlıkta üç zarla oynandığı yazıyor; büyük olasılıkla atışa göre bahis ödenir ya da alınırdı.","Müzeye göre yirmi hanede meslekler gösteriliyor — çalgıcılar, tütüncü, likörcü, kuyumcu, şapkacı, kitapçı, fenerci, matbaacı, çerçeveci, dokumacı, ressam ve heykeltıraş gibi — her birinin talihi kısa bir satırla anlatılıyor. Kumarhane işletenlere ayrılmış bir hane bile var."],"spots":[["Başlık","“GIOCO DE MESTIERI…”."],["Zar atışları","Çalgıcılar hanesindeki zarlar."],["Kumarhaneciler","“Quelli che tengono gioco”."],["Tütüncü","Tütün tartıyor."],["Matbaacı","“Stampatore” hanesi."],["İmza","“MITELLI… 1698”."]]},"hogarth":{"title":"Piyango","artist":"William Hogarth","date":"1721","place":"Britanya (Londra)","game":"Piyango","medium":"Baskı","size":"25,9 × 32,8 cm","credit":"","p":["İngiliz hicivci Hogarth’ın tasarlayıp yaptığı bir baskı; altta “The LOTTERY” başlığı ve İngilizce bir açıklama var. Bu nüshaya açıklamanın elle yazılmış Felemenkçe çevirisi eklenmiş.","Müzeye göre Ulusal Kredi’nin kişileştirmesi, ulusal piyangonun simgesini gösteren tanrılar ve kumar ile kurayla ilgili erdemler ve kusurlar resmedilmiş. Sağda ve solda ikramiye ve boş bilet çekilen büyük piyango çarkları duruyor, önde ise talihlilerle talihsizler birbirine karışıyor."],"spots":[["Sol çark","Büyük bir piyango çarkı."],["Sağ çark","İkinci çark."],["Ulusal Kredi","Kaidede tahta oturan figür."],["Kaide","Ortadaki büyük kaide."],["Coşanlar","Sağ öndeki kalabalık."],["Başlık","“The LOTTERY”."]]},"matthieu":{"title":"Mum Işığında Dama Oynayan Hanımlar","artist":"Georg David Matthieu","date":"1765","place":"Almanya","game":"Dama","medium":"Asitle oyma baskı","size":"17,9 × 22,7 cm","credit":"","p":["Alman portre ressamı Matthieu’nün bir baskısı; sağ altta “G. D. Matthieu 1765” imzası var. Meyhane değil, evde sakin bir akşam.","Müzeye göre başlıklı üç kadın üzerinde mum yanan yuvarlak bir masada oturuyor. Biri elinde kitapla öteki ikisinin dama oynamasını izliyor. Masada bir fitil makası ve küçük bir kutu da var."],"spots":[["Tahta","Masadaki dama tahtası."],["Mum","Masanın ortasında yanıyor."],["Fitil makası","Fitili kısaltmak için."],["Ortadaki kadın","Bize bakıyor."],["Sağdaki kadın","Gözleri yerde, tahtaya uzanıyor."],["İmza","“G. D. Matthieu 1765”."]]},"pillement":{"title":"Kâğıttan Ev Yapan Çinli Çocuklar (Çinli Çocuk Oyunları’ndan)","artist":"Pierre Charles Canot (Jean Baptiste Pillement’dan)","date":"1759","place":"Britanya (Londra) / Fransa (Paris)","game":"Kâğıttan ev","medium":"Asitle oyma baskı","size":"42,6 × 27,3 cm","credit":"","p":["Çin üslubu süslemeleriyle ünlü Pillement’ın desenlerinden Canot’nun oyduğu, Londra ve Paris’te yayımlanan sekiz levhalık “Recueil de plusieurs jeux d’enfants chinois” dizisinden biri. Avrupa’daki şinuvazri (Çin hayranlığı) modasının hayal ettiği Çinli çocuklar bunlar.","Müzeye göre üstteki sahnede iki çocuk yuvarlak bir masada kâğıttan ev kuruyor, üçüncüsü elinde sopayla koşarak geliyor; alttaki sahnede bir çocuk ötekinin sırtına binmiş, üçüncüsü solda duruyor. İki sahne de çit ve yapraklardan bir çerçeveyle çevrili."],"spots":[["Kâğıttan ev","Yuvarlak masada."],["Sopalı çocuk","Koşarak geliyor."],["Köşk","Arkadaki Çin üslubu yapı."],["Sırtta taşıma","Bir çocuk ötekinin sırtında."],["Ayaktaki çocuk","Alt sahnenin solunda."],["Yayın satırı","“London Published… 1759”."]]},"skating":{"title":"Paten Pisti Oyunu","artist":"Anonim (Gebroeders Koster yayını)","date":"1870","place":"Hollanda (Amsterdam)","game":"Yarış oyunu (kaz oyunu benzeri)","medium":"Renkli taş baskı ve tipo baskı","size":"42,6 × 57,5 cm","credit":"","p":["Tekerlekli paten konulu bir tahta oyunu; Amsterdam’da Gebroeders Koster yayımlamış. Müzeye göre kaz oyununa benziyor; dört köşede Felemenkçe, Fransızca, Almanca ve İngilizce kurallar basılı.","Ortada patenli bir oğlan ve kız el ele tutuşuyor, çevredeki hanelerde kayan ve düşen insanların küçük sahneleri var. Bazı hanelerde zar çiftleri çizili; bitiş “SKATINGRINK 52”."],"spots":[["Patenli çift","Ortadaki oğlan ve kız."],["Bitiş","“SKATINGRINK 52”."],["Zar atışları","Zar çizili haneler."],["Düşenler","Düşme sahnesi."],["Kurallar","Köşelerdeki metin."],["Yayıncı","“GEBROEDERS KOSTER”."]]},"gavarni":{"title":"Kocasıyla Âşığının Tahta Oyununu İzleyen Kadın","artist":"Paul Gavarni","date":"1837","place":"Fransa (Paris)","game":"Tahta oyunu (türü kayıtlı değil)","medium":"Taş baskı","size":"31,7 × 23,3 cm","credit":"","p":["Karikatürist Gavarni’nin, Paris gazetesi Le Charivari’nin 20 Aralık 1837 sayısında kullanılan bir taş baskısı; on ikilik bir dizinin 2 numarası.","Müzeye göre bir kadın kocasıyla âşığının bir tahta oyunu oynamasını izliyor. Solda sabahlık ve fes giymiş adam büyük olasılıkla koca, tahtaya eğilmiş genç ise âşık. Alt yazı âşığın yakınmasını aktarıyor: bütün akşam paranızı kazanan, sizinle alay eden ve burnunuzun dibinde yatmaya giden aptal bir kocayla oynamak."],"spots":[["Koca","Sabahlık ve fesli."],["Tahta","Masada."],["Âşık","Tahtaya eğilmiş."],["Kadın","Arkada ayakta."],["Süs eşyası","Cam fanus altında bir heykelcik."],["Alt yazı","“Faire toute la soirée…”."]]},"picart":{"title":"Sahnede Piyango (Büyük Ahmaklık Aynası’ndan)","artist":"Bernard Picart","date":"1720–1733","place":"Hollanda (Amsterdam)","game":"Piyango","medium":"Asitle oyma ve gravür","size":"23,8 × 37,7 cm","credit":"","p":["1720 hisse senedi çılgınlığını hicveden “Büyük Ahmaklık Aynası” derlemesine sonradan eklenen levhalardan biri; sol altta “B. Picart inv. et fec.” yazıyor.","Müzeye göre bir kent meydanındaki sahnede piyango çekiliyor, iki oğlan bilet kutularından kura çekiyor. Öndeki kalabalıkta yer yer kavgalar çıkıyor. Devrilmiş bir el arabası, meyve sepetli bir kadın ve havlayan bir köpek kargaşayı artırıyor."],"spots":[["Piyango kutuları","Sahnedeki büyük kutular."],["Çekiliş","Sahnedeki kişiler."],["Kavga","Önde boğuşanlar."],["Düşen adam","Merdiven ve el arabasının yanında."],["Köpek","Sağ altta."],["İmza","“B. Picart inv. et fec.”."]]}};
